// Silence noisy Firestore internal assertions to avoid UI error loops
const FIRESTORE_ASSERTION_PATTERN = /INTERNAL ASSERTION FAILED/i;
const FIRESTORE_FORCE_LONG_POLLING_KEY = '__gcsemate_force_long_polling';
const BLOCKED_BY_CLIENT_PATTERN = /ERR_BLOCKED_BY_CLIENT|blocked by client|Failed to fetch/i;
const STRIPE_BLOCKED_PATTERN = /r\.stripe\.com|errors\.stripe\.com|pricing-table/i;
const FIRESTORE_CHANNEL_PATTERN = /firestore\.googleapis\.com\/.+\/(Listen|Write)\/channel/i;
const EXTENSION_NOISE_PATTERN = /chrome-extension:\/\/|moz-extension:\/\/|safari-extension:\/\/|extension context invalidated|message channel closed|content script|removelisteners/i;
const CHECKOUT_PENDING_SUCCESS_KEY = 'gcsemate_checkout_pending_success';
const CHECKOUT_SUCCESS_TIMEOUT_MS = 10 * 60 * 1000;
const STRIPE_BILLING_PORTAL_URL = 'https://billing.stripe.com/p/login/4gM8wO6ZT0280mg3CZfAc00';
let hasShownBlockerWarning = false;
let firestoreAssertionCount = 0;
let hasShownFirestoreRecoveryWarning = false;
let firestoreTransportUnstableUntil = 0;
let lastHandledCheckoutSuccessAt = 0;
let recaptchaScriptPromise = null;
let stripePricingTableScriptPromise = null;

function isFirestoreTransportUnstable() {
    return Date.now() < firestoreTransportUnstableUntil;
}

function isLikelyBlockedByClient(errorLike) {
    const text = typeof errorLike === 'string'
        ? errorLike
        : `${errorLike?.message || ''} ${errorLike?.reason?.message || ''} ${errorLike?.filename || ''} ${errorLike?.target?.src || ''}`;
    return BLOCKED_BY_CLIENT_PATTERN.test(text) && (
        STRIPE_BLOCKED_PATTERN.test(text) ||
        FIRESTORE_CHANNEL_PATTERN.test(text)
    );
}

function isIgnorableExtensionNoise(errorLike) {
    const text = typeof errorLike === 'string'
        ? errorLike
        : `${errorLike?.message || ''} ${errorLike?.reason?.message || ''} ${errorLike?.filename || ''} ${errorLike?.target?.src || ''}`;
    return EXTENSION_NOISE_PATTERN.test(text);
}

function getNextQuickThemeMode(currentMode = 'auto') {
    if (currentMode === 'dark') return 'light';
    if (currentMode === 'light') return 'dark';
    return 'dark';
}

function toggleQuickThemeMode() {
    const currentMode = getSavedUIPreferences().themeMode || 'auto';
    saveUIPreferences({ themeMode: getNextQuickThemeMode(currentMode) });
    applyUserInterfacePreferences();
}

function syncQuickThemeToggles(themeMode = 'auto') {
    const isDark = document.documentElement.classList.contains('dark-theme');
    [document.getElementById('theme-quick-toggle'), document.getElementById('theme-quick-toggle-mobile')]
        .filter(Boolean)
        .forEach((button) => {
            const icon = button.querySelector('i');
            const label = button.querySelector('span');
            if (icon) {
                icon.className = `fas ${isDark ? 'fa-sun' : 'fa-moon'}${button.id === 'theme-quick-toggle' ? ' text-xs' : ''}`;
            }
            if (label) label.textContent = isDark ? 'Light mode' : 'Dark mode';
            button.setAttribute('aria-pressed', isDark ? 'true' : 'false');
            button.dataset.themeMode = themeMode;
        });
}

function applyFeedbackWidgetVisibility() {
    const dismissed = (() => {
        try { return localStorage.getItem('gcsemate_feedback_hidden') === '1'; } catch (_) { return false; }
    })();
    document.body.classList.toggle('feedback-widget-hidden', dismissed);
    const dismissButton = document.getElementById('feedback-dismiss-button');
    if (dismissButton) dismissButton.classList.toggle('hidden', dismissed);
}

function dismissFeedbackWidget() {
    try { localStorage.setItem('gcsemate_feedback_hidden', '1'); } catch (_) {}
    applyFeedbackWidgetVisibility();
}

function applyStripeEmbedFallback() {
    const pricingTable = document.querySelector('stripe-pricing-table');
    if (!pricingTable) return;
    const wrapper = pricingTable.parentElement;
    if (!wrapper || wrapper.dataset.blockerFallbackApplied === '1') return;

    wrapper.dataset.blockerFallbackApplied = '1';
    pricingTable.classList.add('hidden');

    const fallback = document.createElement('div');
    fallback.className = 'rounded-2xl border border-amber-200 bg-amber-50/95 p-5 text-left text-amber-950 shadow-sm';
    fallback.innerHTML = `
        <div class="flex items-start gap-3">
            <div class="mt-0.5 text-amber-600"><i class="fas fa-shield-alt"></i></div>
            <div class="space-y-2">
                <h4 class="text-base font-bold text-amber-900">Checkout embed blocked</h4>
                <p class="text-sm leading-relaxed text-amber-900">A browser extension or privacy blocker stopped Stripe from loading fully. You can temporarily allow Stripe for this site, or email <a class="font-semibold underline hover:text-amber-700" href="mailto:admin@gcsemate.com">admin@gcsemate.com</a> for manual setup.</p>
            </div>
        </div>`;
    wrapper.appendChild(fallback);
}

function showBlockedByClientWarningOnce(errorLike = '') {
    if (hasShownBlockerWarning) return;
    hasShownBlockerWarning = true;
    const messageText = typeof errorLike === 'string'
        ? errorLike
        : `${errorLike?.message || ''} ${errorLike?.reason?.message || ''} ${errorLike?.filename || ''} ${errorLike?.target?.src || ''}`;
    if (STRIPE_BLOCKED_PATTERN.test(messageText)) {
        applyStripeEmbedFallback();
    }
    setTimeout(() => {
        try {
            showToast('Content blocker detected: Stripe/Firestore telemetry requests were blocked. Core app features may be limited.', 'warning', 7000);
        } catch (_) {}
    }, 200);
}

function handleFirestoreAssertionEvent() {
    firestoreAssertionCount += 1;
    firestoreTransportUnstableUntil = Date.now() + 120000;
    if (firestoreAssertionCount < 3) return;

    try {
        localStorage.setItem(FIRESTORE_FORCE_LONG_POLLING_KEY, '1');
    } catch (_) {}

    if (!hasShownFirestoreRecoveryWarning) {
        hasShownFirestoreRecoveryWarning = true;
        try {
            showToast('Detected unstable Firestore transport. Switching to compatibility mode…', 'warning', 4500);
        } catch (_) {}
    }

    recoverFirestoreSession();
}

window.addEventListener('error', (event) => {
    if (isIgnorableExtensionNoise(event)) {
        event.preventDefault();
        event.stopImmediatePropagation();
        return;
    }
    if (isLikelyBlockedByClient(event)) {
        event.preventDefault();
        event.stopImmediatePropagation();
        console.warn('[suppressed] blocked-by-client resource error');
        showBlockedByClientWarningOnce(event);
        return;
    }
    if (event?.message && FIRESTORE_ASSERTION_PATTERN.test(event.message)) {
        event.preventDefault();
        event.stopImmediatePropagation();
        console.warn('[suppressed] Firestore assertion error');
        handleFirestoreAssertionEvent();
    }
}, { capture: true });

window.addEventListener('unhandledrejection', (event) => {
    const reason = event?.reason;
    const msg = (reason && (reason.message || reason.toString())) || '';
    if (isIgnorableExtensionNoise(reason || msg)) {
        event.preventDefault();
        event.stopImmediatePropagation();
        return;
    }
    if (isLikelyBlockedByClient(reason || msg)) {
        event.preventDefault();
        event.stopImmediatePropagation();
        console.warn('[suppressed] blocked-by-client rejection');
        showBlockedByClientWarningOnce(reason || msg);
        return;
    }
    if (FIRESTORE_ASSERTION_PATTERN.test(msg)) {
        event.preventDefault();
        event.stopImmediatePropagation();
        console.warn('[suppressed] Firestore assertion rejection');
        handleFirestoreAssertionEvent();
    }
}, { capture: true });

// Download rate limiting - 3 files per minute
const DOWNLOAD_RATE_LIMIT = {
    maxDownloads: 3,
    timeWindow: 60 * 1000, // 1 minute in milliseconds
    storageKey: 'gcsemate_downloads'
};

function getDownloadHistory() {
    try {
        const stored = localStorage.getItem(DOWNLOAD_RATE_LIMIT.storageKey);
        if (!stored) return [];
        const history = JSON.parse(stored);
        // Filter out old entries (older than 1 minute)
        const now = Date.now();
        return history.filter(timestamp => (now - timestamp) < DOWNLOAD_RATE_LIMIT.timeWindow);
    } catch (error) {
        console.error('Error reading download history:', error);
        return [];
    }
}

function recordDownload() {
    try {
        const history = getDownloadHistory();
        history.push(Date.now());
        localStorage.setItem(DOWNLOAD_RATE_LIMIT.storageKey, JSON.stringify(history));
    } catch (error) {
        console.error('Error recording download:', error);
    }
}

function canDownload() {
    const history = getDownloadHistory();
    return history.length < DOWNLOAD_RATE_LIMIT.maxDownloads;
}

function getTimeUntilNextDownload() {
    const history = getDownloadHistory();
    if (history.length < DOWNLOAD_RATE_LIMIT.maxDownloads) return 0;
    
    // Find the oldest download in the current window
    const oldest = Math.min(...history);
    const elapsed = Date.now() - oldest;
    const remaining = DOWNLOAD_RATE_LIMIT.timeWindow - elapsed;
    return Math.ceil(remaining / 1000); // Return seconds
}

function formatFilenameWithWatermark(originalName) {
    if (!originalName) return 'download - Downloaded from GCSEMate.com';
    
    // Extract file extension
    const lastDot = originalName.lastIndexOf('.');
    if (lastDot === -1) {
        return `${originalName} - Downloaded from GCSEMate.com`;
    }
    
    const nameWithoutExt = originalName.substring(0, lastDot);
    const extension = originalName.substring(lastDot);
    return `${nameWithoutExt} - Downloaded from GCSEMate.com${extension}`;
}
