// --- LOADING OVERLAY SAFETY NET ---
// Prevent the app from getting permanently stuck behind the initial overlay
// if a network dependency (Firebase/CDN) is slow or blocked.
function hideAppLoadingOverlay() {
    const overlay = document.getElementById('app-loading');
    if (!overlay) return;
    if (overlay.dataset && overlay.dataset.hidden === 'true') return;

    overlay.dataset.hidden = 'true';
    overlay.style.transition = overlay.style.transition || 'opacity 200ms ease-out';
    overlay.style.opacity = '0';
    overlay.style.pointerEvents = 'none';
    setTimeout(() => {
        overlay.style.display = 'none';
    }, 220);
}

// Hide as soon as the page load event fires, and also force-hide after a timeout.
window.addEventListener('load', () => {
    hideAppLoadingOverlay();
}, { once: true });

setTimeout(() => {
    hideAppLoadingOverlay();
}, 12000);

// --- LIGHTWEIGHT PERFORMANCE MODE ---
function applyLowSpecMode() {
    try {
        const prefersReducedMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
        const coarsePointer = window.matchMedia && window.matchMedia('(hover: none), (pointer: coarse)').matches;
        const saveData = navigator.connection && navigator.connection.saveData;
        const effectiveType = navigator.connection && navigator.connection.effectiveType;
        const slowConnection = typeof effectiveType === 'string' && (effectiveType.includes('2g') || effectiveType.includes('slow-2g'));
        const smallViewport = window.innerWidth > 0 && window.innerWidth <= 768;

        if (prefersReducedMotion || coarsePointer || saveData || slowConnection || smallViewport) {
            document.documentElement.classList.add('low-spec');
        }
    } catch (_) {
        // Best-effort only
    }
}

applyLowSpecMode();

function loadDeferredScript(src, attributes = {}) {
    return new Promise((resolve, reject) => {
        const existing = Array.from(document.scripts).find((node) => node.src === src);
        if (existing) {
            if (existing.dataset.loaded === 'true') {
                resolve(existing);
                return;
            }
            existing.addEventListener('load', () => resolve(existing), { once: true });
            existing.addEventListener('error', () => reject(new Error(`Failed to load ${src}`)), { once: true });
            return;
        }

        const script = document.createElement('script');
        script.src = src;
        Object.entries(attributes).forEach(([key, value]) => {
            if (key in script && typeof value === 'boolean') {
                script[key] = value;
                return;
            }
            if (value === true) {
                script.setAttribute(key, '');
                return;
            }
            script.setAttribute(key, String(value));
        });
        script.addEventListener('load', () => {
            script.dataset.loaded = 'true';
            resolve(script);
        }, { once: true });
        script.addEventListener('error', () => reject(new Error(`Failed to load ${src}`)), { once: true });
        document.head.appendChild(script);
    });
}

async function ensureRecaptchaScriptLoaded() {
    if (!RECAPTCHA_SITE_KEY) return null;
    if (window.grecaptcha && typeof window.grecaptcha.ready === 'function') {
        await new Promise((resolve) => window.grecaptcha.ready(resolve));
        return window.grecaptcha;
    }
    if (!recaptchaScriptPromise) {
        const src = `https://www.google.com/recaptcha/api.js?render=${encodeURIComponent(RECAPTCHA_SITE_KEY)}`;
        recaptchaScriptPromise = loadDeferredScript(src, { async: true, defer: true })
            .then(() => new Promise((resolve) => {
                if (window.grecaptcha && typeof window.grecaptcha.ready === 'function') {
                    window.grecaptcha.ready(() => resolve(window.grecaptcha));
                    return;
                }
                resolve(null);
            }))
            .catch((error) => {
                recaptchaScriptPromise = null;
                console.warn('reCAPTCHA script load failed:', error);
                return null;
            });
    }
    return recaptchaScriptPromise;
}

async function ensureStripePricingTableLoaded() {
    if (!document.querySelector('stripe-pricing-table')) return true;
    if (window.customElements && window.customElements.get('stripe-pricing-table')) {
        try { configureStripePricingTableIdentity(); } catch (_) {}
        return true;
    }
    if (!stripePricingTableScriptPromise) {
        stripePricingTableScriptPromise = loadDeferredScript('https://js.stripe.com/v3/pricing-table.js', { async: true })
            .then(() => {
                try { configureStripePricingTableIdentity(); } catch (_) {}
                return true;
            })
            .catch((error) => {
                stripePricingTableScriptPromise = null;
                console.warn('Stripe pricing table script load failed:', error);
                return false;
            });
    }
    return stripePricingTableScriptPromise;
}

function ensureDeferredAssetsForPage(pageId) {
    if (pageId === 'features-page' || pageId === 'checkout-page') {
        void ensureStripePricingTableLoaded();
    }
}

// Comprehensive Error Handling System
class ErrorHandler {
    constructor() {
        this.errorCount = 0;
        this.maxErrors = 10;
        this.errorLog = [];
        this.firestoreRecoveryTriggered = false;
        this.setupGlobalErrorHandlers();
    }
    
    setupGlobalErrorHandlers() {
        // Handle uncaught JavaScript errors
        window.addEventListener('error', (event) => {
            if (isIgnorableExtensionNoise(event)) {
                event.preventDefault();
                return;
            }
            if (isLikelyBlockedByClient(event)) {
                event.preventDefault();
                showBlockedByClientWarningOnce(event);
                return;
            }
            if (event?.message && FIRESTORE_ASSERTION_PATTERN.test(event.message)) {
                event.preventDefault();
                handleFirestoreAssertionEvent();
                return;
            }
            this.handleError({
                type: 'JavaScript Error',
                message: event.message,
                filename: event.filename,
                lineno: event.lineno,
                colno: event.colno,
                error: event.error
            });
        });
        
        // Handle unhandled promise rejections
        window.addEventListener('unhandledrejection', (event) => {
            const reasonMessage = event.reason?.message || event.reason?.toString() || 'Unknown promise rejection';
            const isFirestoreAssertion = typeof reasonMessage === 'string' && reasonMessage.includes('INTERNAL ASSERTION FAILED');
            const isBlockedByClient = isLikelyBlockedByClient(reasonMessage);
            const isExtensionNoise = isIgnorableExtensionNoise(reasonMessage);
            if (isExtensionNoise) {
                event.preventDefault();
                return;
            }
            if (isBlockedByClient) {
                event.preventDefault();
                showBlockedByClientWarningOnce(reasonMessage);
                return;
            } else if (isFirestoreAssertion) {
                // Prevent noisy console spam and immediately try recovery
                event.preventDefault();
                recoverFirestoreSession();
                return;
            }

            // Mark as handled so browsers don't double-log while we surface our own toast
            event.preventDefault();
            this.handleError({
                type: 'Unhandled Promise Rejection',
                message: reasonMessage,
                error: event.reason
            });
        });
        
        // Handle Firebase errors
        this.setupFirebaseErrorHandling();
    }
    
    setupFirebaseErrorHandling() {
        // Override Firebase error handling
        const originalConsoleError = console.error;
        console.error = (...args) => {
            const combinedMessage = args.map(arg => typeof arg === 'string' ? arg : (arg?.message || '')).join(' ');
            if (isIgnorableExtensionNoise(combinedMessage)) return;
            if (isLikelyBlockedByClient(combinedMessage)) {
                showBlockedByClientWarningOnce(combinedMessage);
                return;
            }
            if (FIRESTORE_ASSERTION_PATTERN.test(combinedMessage)) {
                handleFirestoreAssertionEvent();
                return;
            }
            if (args[0] && typeof args[0] === 'string' && args[0].includes('Firebase')) {
                this.handleError({
                    type: 'Firebase Error',
                    message: args[0],
                    details: args.slice(1)
                });
            }
            originalConsoleError.apply(console, args);
        };
    }
    
    handleError(errorInfo) {
        this.errorCount++;
        this.errorLog.push({
            ...errorInfo,
            timestamp: new Date().toISOString(),
            userAgent: navigator.userAgent,
            url: window.location.href
        });

        // Attempt automatic recovery for Firestore assertion loops (common with restricted networks)
        if (!this.firestoreRecoveryTriggered && typeof errorInfo?.message === 'string' && errorInfo.message.includes('INTERNAL ASSERTION FAILED')) {
            this.firestoreRecoveryTriggered = true;
            recoverFirestoreSession();
        }
        
        // Log to console in development
        if (isDevelopment) {
            console.error('Error Handler:', errorInfo);
        }
        
        // Send to analytics in production
        if (isProduction && typeof gtag !== 'undefined') {
            gtag('event', 'exception', {
                description: `${errorInfo.type}: ${errorInfo.message}`,
                fatal: false
            });
        }
        
        // Prevent error spam
        if (this.errorCount > this.maxErrors) {
            this.showErrorLimitReached();
            return;
        }
        
        // Show user-friendly error message for critical errors
        if (this.isCriticalError(errorInfo)) {
            this.showUserFriendlyError(errorInfo);
        }
    }
    
    isCriticalError(errorInfo) {
        if (isLikelyBlockedByClient(errorInfo?.message || '')) return false;
        const criticalPatterns = [
            'Firebase',
            'Authentication',
            'Network',
            'Database',
            'Storage'
        ];
        
        return criticalPatterns.some(pattern => 
            errorInfo.message?.includes(pattern) || 
            errorInfo.type?.includes(pattern)
        );
    }
    
    showUserFriendlyError(errorInfo) {
        const errorMessages = {
            'Firebase Error': 'There was a temporary issue with our servers. Please try again in a moment.',
            'Authentication': 'There was an issue with your login session. Please refresh the page.',
            'Network': 'Please check your internet connection and try again.',
            'Database': 'We\'re experiencing technical difficulties. Please try again later.',
            'Storage': 'There was an issue saving your data. Please try again.'
        };
        
        const message = errorMessages[errorInfo.type] || 'Something went wrong. Please try again.';
        
        showToast(message, 'error');
    }
    
    showErrorLimitReached() {
        showToast('Multiple errors detected. Please refresh the page.', 'error');
    }
    
    getErrorSummary() {
        return {
            totalErrors: this.errorCount,
            recentErrors: this.errorLog.slice(-5),
            errorTypes: this.getErrorTypeCount()
        };
    }
    
    getErrorTypeCount() {
        const types = {};
        this.errorLog.forEach(error => {
            types[error.type] = (types[error.type] || 0) + 1;
        });
        return types;
    }
}

// Initialize error handler
const errorHandler = new ErrorHandler();

// Firestore resilience: force long polling on recovery and reset local cache when assertion loops occur
async function recoverFirestoreSession() {
    if (typeof firebase === 'undefined' || !firebase.firestore) return;
    if (!db || typeof db.disableNetwork !== 'function' || typeof db.enableNetwork !== 'function') return;
    if (window.__firestoreRecoveryRunning) return;
    if (window.__lastFirestoreRecoveryAt && (Date.now() - window.__lastFirestoreRecoveryAt) < 60000) return;
    window.__firestoreRecoveryRunning = true;
    window.__lastFirestoreRecoveryAt = Date.now();
    firestoreTransportUnstableUntil = Date.now() + 120000;
    try {
        localStorage.setItem(FIRESTORE_FORCE_LONG_POLLING_KEY, '1');
    } catch (_) {
        // ignore
    }
    try {
        await db.disableNetwork();
    } catch (_) {}
    try {
        await new Promise(resolve => setTimeout(resolve, 700));
        await db.enableNetwork();
    } catch (_) {}
    // Avoid forced-refresh loops; continue running and retry with long polling transport.
    setTimeout(() => {
        window.__firestoreRecoveryRunning = false;
    }, 2500);
}

function getFirebaseBootstrapError() {
    return window.__gcsemateFirebaseInitError || null;
}

function isAuthAvailable() {
    return !!(auth && typeof auth.onAuthStateChanged === 'function');
}

function isFirestoreAvailable() {
    return !!(db && typeof db.collection === 'function');
}

function getFirebaseFriendlyMessage(errorLike, fallback = 'A live service is temporarily unavailable. Please try again in a moment.') {
    const code = errorLike?.code || '';
    const text = `${code} ${errorLike?.message || errorLike || ''}`.toLowerCase();

    if (text.includes('permission-denied')) return 'You do not have permission to complete that action.';
    if (text.includes('unauthenticated') || text.includes('auth/')) return 'Your session could not be verified. Please sign in again.';
    if (text.includes('network-request-failed') || text.includes('failed to fetch') || text.includes('offline')) return 'Network connection lost. Check your internet connection and try again.';
    if (text.includes('unavailable') || text.includes('deadline-exceeded')) return 'The live database is busy right now. Please retry in a few seconds.';
    if (text.includes('failed-precondition')) return 'A required Firebase setting is missing or still loading.';
    if (text.includes('resource-exhausted')) return 'The service is temporarily rate-limited. Please wait a moment and try again.';
    if (text.includes('internal assertion failed') || text.includes('internal')) return 'A temporary Firebase transport issue was detected. GCSEMate will keep retrying in compatibility mode.';

    return fallback;
}

function setAppStatusBanner(message, tone = 'warning') {
    const banner = document.getElementById('app-status-banner');
    if (!banner) return;
    if (!message) {
        banner.textContent = '';
        banner.className = 'hidden';
        return;
    }

    const classes = ['mx-4', 'sm:mx-6', 'mb-2', 'rounded-2xl', 'px-4', 'py-3', 'text-sm', 'font-semibold', 'shadow-md'];
    if (tone === 'error') classes.push('is-error');
    else if (tone === 'success') classes.push('is-success');

    banner.className = classes.join(' ');
    banner.textContent = message;
}

function showFirebaseDegradedBanner(context = 'Live sync', errorLike = null) {
    const message = getFirebaseFriendlyMessage(errorLike, `${context} is temporarily unavailable. Some synced features may be limited until the connection recovers.`);
    setAppStatusBanner(message, 'warning');
}

function handleFirebaseBootstrapFailure(errorLike) {
    const message = getFirebaseFriendlyMessage(
        errorLike,
        'GCSEMate could not connect to Firebase. Public pages are still available, but sign-in and synced tools are temporarily unavailable.'
    );
    hideAppLoadingOverlay();
    try { showLandingOnly(); } catch (_) {}
    setTimeout(() => setAppStatusBanner(message, 'warning'), 0);
}

// Enhanced logging function
function logError(error, context = '') {
    const errorInfo = {
        type: 'Application Error',
        message: error?.message || error?.toString() || 'Unknown error',
        context: context,
        error: error,
        stack: error?.stack
    };
    
    // Development logging
    if (isDevelopment) {
        console.error(`[${context}]`, error);
    }
    
    // Production logging
    if (isProduction) {
        try {
            if (typeof gtag !== 'undefined') {
                gtag('event', 'exception', {
                    description: `${context}: ${error.message || error}`,
                    fatal: false
                });
            }
        } catch (e) {
            // Silent fail for logging
        }
    }
    
    errorHandler.handleError(errorInfo);
}

// Safe function execution wrapper
function safeExecute(fn, context = '', fallback = null) {
    try {
        return fn();
    } catch (error) {
        logError(error, context);
        return fallback;
    }
}

// Safe async function execution wrapper
async function safeExecuteAsync(fn, context = '', fallback = null) {
    try {
        return await fn();
    } catch (error) {
        logError(error, context);
        return fallback;
    }
}

// Enhanced input validation utilities with detailed feedback
const Validator = {
    email(email) {
        if (!email || !email.trim()) {
            return { valid: false, error: 'Email is required' };
        }
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailRegex.test(email)) {
            return { valid: false, error: 'Please enter a valid email address' };
        }
        if (email.length > 254) {
            return { valid: false, error: 'Email is too long (max 254 characters)' };
        }
        return { valid: true };
    },
    
    password(password, isNew = false) {
        if (!password) {
            return { valid: false, error: 'Password is required' };
        }
        if (password.length < 6) {
            return { valid: false, error: 'Password must be at least 6 characters' };
        }
        if (password.length > 128) {
            return { valid: false, error: 'Password is too long (max 128 characters)' };
        }
        if (isNew) {
            // Additional strength checks for new passwords
            if (password.length < 8) {
                return { valid: false, error: 'For better security, use at least 8 characters' };
            }
            const hasUpper = /[A-Z]/.test(password);
            const hasLower = /[a-z]/.test(password);
            const hasNumber = /[0-9]/.test(password);
            const strength = (hasUpper ? 1 : 0) + (hasLower ? 1 : 0) + (hasNumber ? 1 : 0);
            if (strength < 2) {
                return { valid: true, warning: 'Consider using a mix of letters and numbers for better security' };
            }
        }
        return { valid: true };
    },
    
    displayName(name) {
        if (!name || !name.trim()) {
            return { valid: false, error: 'Name is required' };
        }
        const trimmed = name.trim();
        if (trimmed.length < 2) {
            return { valid: false, error: 'Name must be at least 2 characters' };
        }
        if (trimmed.length > 50) {
            return { valid: false, error: 'Name is too long (max 50 characters)' };
        }
        if (!/^[a-zA-Z\s'-]+$/.test(trimmed)) {
            return { valid: false, error: 'Name can only contain letters, spaces, hyphens, and apostrophes' };
        }
        return { valid: true };
    },
    
    file(file, options = {}) {
        const { maxSize = 5 * 1024 * 1024, allowedTypes = [] } = options;
        
        if (!file) return { valid: false, error: 'No file provided' };
        if (file.size > maxSize) {
            const maxSizeMB = (maxSize / (1024 * 1024)).toFixed(1);
            return { valid: false, error: `File too large (max ${maxSizeMB}MB)` };
        }
        if (allowedTypes.length && !allowedTypes.includes(file.type)) {
            return { valid: false, error: 'Invalid file type' };
        }
        
        return { valid: true };
    },
    
    url(url) {
        if (!url || !url.trim()) {
            return { valid: false, error: 'URL is required' };
        }
        try {
            const urlObj = new URL(url);
            if (!['http:', 'https:'].includes(urlObj.protocol)) {
                return { valid: false, error: 'URL must start with http:// or https://' };
            }
            return { valid: true };
        } catch {
            return { valid: false, error: 'Please enter a valid URL' };
        }
    },
    
    title(title) {
        if (!title || !title.trim()) {
            return { valid: false, error: 'Title is required' };
        }
        const trimmed = title.trim();
        if (trimmed.length < 2) {
            return { valid: false, error: 'Title must be at least 2 characters' };
        }
        if (trimmed.length > 200) {
            return { valid: false, error: 'Title is too long (max 200 characters)' };
        }
        return { valid: true };
    }
};

// Form validation helper with real-time feedback
function setupFormValidation(formId, validationRules) {
    const form = document.getElementById(formId);
    if (!form) return;
    
    Object.keys(validationRules).forEach(inputId => {
        const input = document.getElementById(inputId);
        if (!input) return;
        
        const rule = validationRules[inputId];
        let errorElement = input.parentElement.querySelector(`#${inputId}-error`) || 
                          input.nextElementSibling;
        
        if (!errorElement || !errorElement.classList.contains('error-message')) {
            errorElement = document.createElement('div');
            errorElement.id = `${inputId}-error`;
            errorElement.className = 'error-message text-red-600 text-sm mt-1 h-4 transition-all';
            errorElement.setAttribute('role', 'alert');
            errorElement.setAttribute('aria-live', 'polite');
            input.parentElement.appendChild(errorElement);
        }
        
        // Real-time validation on input
        input.addEventListener('input', () => {
            const value = input.value.trim();
            const result = rule.validator(value, rule.options);
            
            if (result.valid) {
                input.classList.remove('border-red-500', 'bg-red-50');
                input.classList.add('border-gray-300');
                errorElement.textContent = '';
                if (result.warning) {
                    errorElement.textContent = result.warning;
                    errorElement.className = 'error-message text-amber-600 text-sm mt-1 h-4 transition-all';
                }
            } else {
                input.classList.add('border-red-500', 'bg-red-50');
                input.classList.remove('border-gray-300');
                errorElement.textContent = result.error;
                errorElement.className = 'error-message text-red-600 text-sm mt-1 h-4 transition-all';
            }
        });
        
        // Validation on blur
        input.addEventListener('blur', () => {
            const value = input.value.trim();
            const result = rule.validator(value, rule.options);
            if (!result.valid) {
                input.classList.add('border-red-500', 'bg-red-50');
                errorElement.textContent = result.error;
                errorElement.className = 'error-message text-red-600 text-sm mt-1 h-4 transition-all';
            }
        });
    });
}

// Initialize form validations on page load
function initializeFormValidations() {
    // Login form
    setupFormValidation('login-form', {
        'email': {
            validator: (value) => Validator.email(value),
            options: {}
        },
        'password': {
            validator: (value) => Validator.password(value, false),
            options: {}
        }
    });
    
    // Register form
    setupFormValidation('register-form', {
        'register-displayname': {
            validator: (value) => Validator.displayName(value),
            options: {}
        },
        'register-email': {
            validator: (value) => Validator.email(value),
            options: {}
        },
        'register-password': {
            validator: (value) => Validator.password(value, true),
            options: {}
        }
    });
    
    // Add link form
    setupFormValidation('add-link-form-container', {
        'link-title': {
            validator: (value) => Validator.title(value),
            options: {}
        },
        'link-url': {
            validator: (value) => Validator.url(value),
            options: {}
        }
    });
    
    // User settings form
    setupFormValidation('user-details-form', {
        'user-displayname': {
            validator: (value) => Validator.displayName(value),
            options: {}
        },
        'user-password': {
            validator: (value) => {
                if (!value || !value.trim()) {
                    return { valid: true }; // Optional field
                }
                return Validator.password(value, true);
            },
            options: {}
        }
    });
}

// Resource cleanup manager
class ResourceManager {
    constructor() {
        this.resources = new Map();
        this.cleanupFunctions = new Set();
    }
    
    registerResource(id, resource, cleanupFn) {
        this.resources.set(id, resource);
        if (cleanupFn) {
            this.cleanupFunctions.add(cleanupFn);
        }
    }
    
    cleanupResource(id) {
        const resource = this.resources.get(id);
        if (resource && resource.cleanup) {
            resource.cleanup();
        }
        this.resources.delete(id);
    }
    
    cleanupAll() {
        this.cleanupFunctions.forEach(cleanup => {
            try {
                cleanup();
            } catch (error) {
                logError(error, 'Resource Cleanup');
            }
        });
        this.cleanupFunctions.clear();
        this.resources.clear();
    }
}

