function toMillis(value) {
    if (!value) return 0;
    if (typeof value === 'number') return value;
    if (typeof value?.toMillis === 'function') return value.toMillis();
    if (typeof value?.toDate === 'function') return value.toDate().getTime();
    const parsed = new Date(value).getTime();
    return Number.isFinite(parsed) ? parsed : 0;
}

function setFlashcardsStatus(message, tone = 'info') {
    const statusEl = document.getElementById('tools-flashcards-sync-status');
    if (!statusEl) return;
    statusEl.textContent = message;
    statusEl.dataset.tone = tone;
}

function setButtonBusy(button, isBusy, busyLabel = 'Working...') {
    if (!button) return;
    if (isBusy) {
        if (!button.dataset.originalLabel) button.dataset.originalLabel = button.innerHTML;
        button.disabled = true;
        button.setAttribute('aria-busy', 'true');
        button.innerHTML = `<span class="inline-flex items-center gap-2"><span class="loading-orb" style="width: 1rem; height: 1rem; border-width: 2px;"></span><span>${escapeHTML(busyLabel)}</span></span>`;
        return;
    }

    button.disabled = false;
    button.removeAttribute('aria-busy');
    if (button.dataset.originalLabel) {
        button.innerHTML = button.dataset.originalLabel;
        delete button.dataset.originalLabel;
    }
}

function getElementActivityLabel(target) {
    if (!target) return 'unknown';
    const labelled = target.closest('[data-page], [data-tools-planner-id], [data-grade-delete-id], button, input, select, textarea, a');
    if (!labelled) return target.tagName?.toLowerCase() || 'unknown';
    return labelled.id || labelled.name || labelled.dataset.page || labelled.dataset.toolsPlannerId || labelled.dataset.gradeDeleteId || labelled.getAttribute('aria-label') || labelled.textContent?.trim()?.slice(0, 60) || labelled.tagName?.toLowerCase() || 'unknown';
}

function shouldIgnoreMiddleAutoScrollTarget(target) {
    if (!target) return false;
    return !!target.closest('button, a, input, textarea, select, label, summary, details, [role="button"], [contenteditable="true"], iframe, canvas, video');
}

function getMiddleAutoScrollHostFromTarget(target) {
    const fallbackHost = document.getElementById('page-content');
    let node = target instanceof Element ? target : null;

    while (node && node !== document.body) {
        const style = window.getComputedStyle(node);
        const canScrollY = /(auto|scroll|overlay)/.test(String(style.overflowY || ''))
            && (node.scrollHeight > node.clientHeight + 2);
        if (canScrollY) return node;
        node = node.parentElement;
    }

    return fallbackHost;
}

function removeMiddleAutoScrollIndicator() {
    const indicator = middleAutoScrollState.indicatorEl;
    if (!indicator) return;
    middleAutoScrollState.indicatorEl = null;
    indicator.remove();
}

function mountMiddleAutoScrollIndicator(x, y) {
    let indicator = middleAutoScrollState.indicatorEl;
    if (!indicator) {
        indicator = document.createElement('div');
        indicator.className = 'middle-autoscroll-indicator';
        document.body.appendChild(indicator);
        middleAutoScrollState.indicatorEl = indicator;
    }
    indicator.style.left = `${Math.round(x)}px`;
    indicator.style.top = `${Math.round(y)}px`;
    indicator.classList.toggle('is-active', middleAutoScrollState.active);
}

function runMiddleAutoScrollFrame() {
    const state = middleAutoScrollState;
    if (!state.active || !state.scrollHost) return;

    const deltaY = state.pointerY - state.anchorY;
    const deadZone = 10;
    let velocity = 0;
    if (Math.abs(deltaY) > deadZone) {
        const direction = deltaY > 0 ? 1 : -1;
        const intensity = Math.min(34, (Math.abs(deltaY) - deadZone) / 5);
        velocity = direction * intensity;
    }

    if (velocity !== 0) {
        state.scrollHost.scrollTop += velocity;
    }

    state.rafId = requestAnimationFrame(runMiddleAutoScrollFrame);
}

function stopMiddleAutoScroll() {
    const state = middleAutoScrollState;
    if (state.rafId) {
        cancelAnimationFrame(state.rafId);
        state.rafId = null;
    }
    state.active = false;
    state.scrollHost = null;

    window.removeEventListener('mousemove', handleMiddleAutoScrollMove, true);
    window.removeEventListener('mousedown', handleMiddleAutoScrollCancel, true);
    window.removeEventListener('auxclick', handleMiddleAutoScrollCancel, true);
    window.removeEventListener('wheel', handleMiddleAutoScrollCancel, true);
    window.removeEventListener('keydown', handleMiddleAutoScrollKeydown, true);
    window.removeEventListener('blur', stopMiddleAutoScroll, true);

    removeMiddleAutoScrollIndicator();
}

function handleMiddleAutoScrollMove(event) {
    if (!middleAutoScrollState.active) return;
    middleAutoScrollState.pointerX = event.clientX;
    middleAutoScrollState.pointerY = event.clientY;
}

function handleMiddleAutoScrollCancel(event) {
    if (!middleAutoScrollState.active) return;

    if (event.type === 'mousedown' || event.type === 'auxclick') {
        const button = Number(event.button);
        if (![0, 1, 2].includes(button)) return;
        if (button === 1) {
            const elapsedMs = Date.now() - Number(middleAutoScrollState.activatedAtMs || 0);
            if (elapsedMs < 90) return;
            event.preventDefault();
        }
    }

    stopMiddleAutoScroll();
}

function handleMiddleAutoScrollKeydown(event) {
    if (!middleAutoScrollState.active) return;
    if (event.key === 'Escape') stopMiddleAutoScroll();
}

function startMiddleAutoScroll(event, scrollHost) {
    const state = middleAutoScrollState;
    stopMiddleAutoScroll();

    state.active = true;
    state.anchorX = event.clientX;
    state.anchorY = event.clientY;
    state.pointerX = event.clientX;
    state.pointerY = event.clientY;
    state.scrollHost = scrollHost;
    state.activatedAtMs = Date.now();

    mountMiddleAutoScrollIndicator(state.anchorX, state.anchorY);

    window.addEventListener('mousemove', handleMiddleAutoScrollMove, true);
    window.addEventListener('mousedown', handleMiddleAutoScrollCancel, true);
    window.addEventListener('auxclick', handleMiddleAutoScrollCancel, true);
    window.addEventListener('wheel', handleMiddleAutoScrollCancel, true);
    window.addEventListener('keydown', handleMiddleAutoScrollKeydown, true);
    window.addEventListener('blur', stopMiddleAutoScroll, true);

    state.rafId = requestAnimationFrame(runMiddleAutoScrollFrame);
}

function handlePageMiddleMouseDown(event) {
    if (event.button !== 1) return;

    const scrollHost = getMiddleAutoScrollHostFromTarget(event.target);
    if (!scrollHost) return;
    if (scrollHost.scrollHeight <= scrollHost.clientHeight + 2) return;
    if (shouldIgnoreMiddleAutoScrollTarget(event.target)) return;

    event.preventDefault();
    startMiddleAutoScroll(event, scrollHost);
}

function initializeMiddleAutoScroll() {
    const scrollHost = document.getElementById('page-content');
    if (!scrollHost || scrollHost.dataset.middleAutoscrollBound === 'true') return;

    scrollHost.addEventListener('mousedown', handlePageMiddleMouseDown);
    scrollHost.dataset.middleAutoscrollBound = 'true';
}

function flushInteractionBatch({ immediate = false } = {}) {
    if (!currentUser) return Promise.resolve();
    const countEntries = Object.entries(interactionBatch.counts || {});
    if (!countEntries.length) return Promise.resolve();

    const payload = {
        pageId: interactionBatch.pageId || pageVisitState.currentPageId || 'unknown',
        counts: { ...interactionBatch.counts },
        contexts: Object.fromEntries(
            Object.entries(interactionBatch.contexts || {}).map(([key, value]) => [key, Array.from(value).slice(0, 8)])
        ),
        startedAtMs: interactionBatch.startedAt,
        endedAtMs: Date.now(),
        lastInteractionAtMs: interactionBatch.lastInteractionAt || Date.now()
    };

    interactionBatch = {
        counts: {},
        contexts: {},
        startedAt: Date.now(),
        lastInteractionAt: 0,
        pageId: pageVisitState.currentPageId || 'unknown'
    };

    if (interactionFlushTimeout) {
        clearTimeout(interactionFlushTimeout);
        interactionFlushTimeout = null;
    }

    return logUserActivity('interaction_batch', payload);
}

function recordUserInteraction(type, metadata = {}) {
    if (!currentUser || !type) return;
    const pageId = metadata.pageId || pageVisitState.currentPageId || 'unknown';
    interactionBatch.pageId = pageId;
    interactionBatch.lastInteractionAt = Date.now();
    interactionBatch.counts[type] = (interactionBatch.counts[type] || 0) + 1;

    const targetLabel = metadata.target || metadata.tool || metadata.subject || metadata.fileName;
    if (targetLabel) {
        if (!interactionBatch.contexts[type]) interactionBatch.contexts[type] = new Set();
        interactionBatch.contexts[type].add(String(targetLabel).slice(0, 80));
    }

    if (interactionFlushTimeout) clearTimeout(interactionFlushTimeout);
    const shouldFlushNow = metadata.important || Object.values(interactionBatch.counts).reduce((sum, value) => sum + value, 0) >= 12;
    if (shouldFlushNow) {
        flushInteractionBatch({ immediate: true });
        return;
    }

    interactionFlushTimeout = setTimeout(() => {
        flushInteractionBatch();
    }, 15000);
}

function initializeMicroInteractionTracking() {
    if (interactionTrackingInitialized) return;
    interactionTrackingInitialized = true;

    const throttledScroll = throttle(() => {
        recordUserInteraction('scroll', { target: pageVisitState.currentPageId });
    }, 12000);
    const throttledInput = throttle((target) => {
        recordUserInteraction('input', { target });
    }, 5000);
    const throttledFocus = throttle((target) => {
        recordUserInteraction('focus', { target });
    }, 4000);

    document.addEventListener('click', (event) => {
        recordUserInteraction('click', { target: getElementActivityLabel(event.target) });
    }, { passive: true });

    document.addEventListener('change', (event) => {
        recordUserInteraction('change', { target: getElementActivityLabel(event.target), important: event.target?.matches?.('input[type="checkbox"], select') });
    }, { passive: true });

    document.addEventListener('input', (event) => {
        throttledInput(getElementActivityLabel(event.target));
    }, { passive: true });

    document.addEventListener('focusin', (event) => {
        throttledFocus(getElementActivityLabel(event.target));
    });

    document.addEventListener('keydown', (event) => {
        if (event.metaKey || event.ctrlKey || event.altKey) {
            recordUserInteraction('shortcut', { target: `${event.key}`, important: true });
            return;
        }
        recordUserInteraction('key', { target: event.key });
    });

    document.addEventListener('submit', (event) => {
        recordUserInteraction('submit', { target: getElementActivityLabel(event.target), important: true });
    });

    const pageContent = document.getElementById('page-content');
    if (pageContent) pageContent.addEventListener('scroll', throttledScroll, { passive: true });
}

function trackPageVisit(pageId) {
    if (!pageId || !currentUser) {
        pageVisitState.currentPageId = pageId || pageVisitState.currentPageId;
        pageVisitState.currentStartedAt = Date.now();
        currentPageStart = pageVisitState.currentStartedAt;
        return;
    }

    const previousPageId = pageVisitState.currentPageId;
    const now = Date.now();
    const dwellMs = Math.max(0, now - (pageVisitState.currentStartedAt || now));

    if (previousPageId && pageVisitState.lastLoggedPageId !== `${previousPageId}:${pageId}:${dwellMs}`) {
        logUserActivity('page_view', {
            fromPageId: previousPageId,
            toPageId: pageId,
            dwellMs,
            dwellSeconds: Math.round(dwellMs / 1000),
            currentSubject: userActivityTracker.currentSubject || null,
            currentFile: userActivityTracker.currentFile || null
        });
        pageVisitState.lastLoggedPageId = `${previousPageId}:${pageId}:${dwellMs}`;
    }

    pageVisitState.currentPageId = pageId;
    pageVisitState.currentStartedAt = now;
    currentPageStart = now;
    interactionBatch.pageId = pageId;
    recordUserInteraction('page', { target: pageId, important: true });
}

// Enhanced IP detection with IPv4 preference and location data
async function fetchJsonWithTimeout(url, timeoutMs = 4000) {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), timeoutMs);
    try {
        const response = await fetch(url, {
            signal: controller.signal,
            cache: 'no-store'
        });
        if (!response.ok) {
            throw new Error(`HTTP ${response.status}`);
        }
        return await response.json();
    } finally {
        clearTimeout(timeoutId);
    }
}

async function getUserIPWithLocation() {
    try {
        // Try lightweight free services without API keys
        const ipServices = [
            'https://api.ipify.org?format=json',
            'https://api64.ipify.org?format=json',
            'https://ipapi.co/json/'
        ];
        
        for (const service of ipServices) {
            try {
                const data = await fetchJsonWithTimeout(service, 4000);
                
                let ip = data.ip || data.query;
                if (!ip) continue;
                
                // Convert IPv6 to IPv4 or hide if not possible
                if (ip && isIPv6(ip)) {
                    const ipv4 = await convertIPv6ToIPv4(ip);
                    if (ipv4) {
                        ip = ipv4;
                    } else {
                        // Hide IPv6 addresses that can't be converted
                        ip = 'IPv6_Hidden';
                    }
                }
                
                // Get location data
                const locationData = await getLocationFromIP(ip);
                
                return {
                    ip: ip,
                    location: locationData,
                    timestamp: new Date().toISOString()
                };
            } catch (_) {
                continue;
            }
        }
        
        // Fallback to basic IP detection
        const data = await fetchJsonWithTimeout('https://api.ipify.org?format=json', 3000);
        return {
            ip: data.ip || 'Unknown',
            location: null,
            timestamp: new Date().toISOString()
        };
    } catch (_) {
        return {
            ip: 'Unknown',
            location: null,
            timestamp: new Date().toISOString()
        };
    }
}

// Check if IP is IPv6
function isIPv6(ip) {
    return ip.includes(':') && !ip.includes('.');
}

// Attempt to convert IPv6 to IPv4 (simplified approach)
async function convertIPv6ToIPv4(ipv6) {
    try {
        // Try to get IPv4 from a different service
        const data = await fetchJsonWithTimeout('https://api.ipify.org?format=json', 3000);
        return data.ip && !isIPv6(data.ip) ? data.ip : null;
    } catch (_) {
        return null;
    }
}

// Get location data from IP
async function getLocationFromIP(ip) {
    if (!ip || ip === 'Unknown' || ip === 'IPv6_Hidden') {
        return null;
    }

    const onHostedProd = /(^|\.)gcsemate\.com$/i.test(window.location.hostname || '');
    if (onHostedProd) return null;
    
    try {
        const data = await fetchJsonWithTimeout(`https://ipapi.co/${ip}/json/`, 3500);
        
        return {
            country: data.country_name || 'Unknown',
            countryCode: data.country_code || 'Unknown',
            region: data.region || 'Unknown',
            city: data.city || 'Unknown',
            latitude: data.latitude || null,
            longitude: data.longitude || null,
            timezone: data.timezone || 'Unknown',
            isp: data.org || 'Unknown',
            asn: data.asn || 'Unknown'
        };
    } catch (_) {
        return null;
    }
}

// Initialize user tracking
async function initializeUserTracking() {
    if (!currentUser) return;
    
    return safeExecuteAsync(async () => {
        // Reset per-session trackers on new login to avoid stale durations
        userActivityTracker.loginTime = Date.now();
        userActivityTracker.logoutTime = null;
        userActivityTracker.sessionStart = Date.now();
        userActivityTracker.totalSubjectTime = {};
        userActivityTracker.totalFileTime = {};
        userActivityTracker.openedFiles = new Set();
        userActivityTracker.activities = [];
        hasTrackedLogout = false;
        userSessionStart = Date.now();
        currentPageStart = Date.now();
        sessionId = null;
        interactionBatch = {
            counts: {},
            contexts: {},
            startedAt: Date.now(),
            lastInteractionAt: 0,
            pageId: pageVisitState.currentPageId || 'subject-dashboard-page'
        };
        
        // Get user's IP address with IPv4 preference and location data
        const ipData = await getUserIPWithLocation();
        userIP = ipData.ip;
        userLocation = ipData.location;
        
        // Generate unique session ID
        sessionId = `${currentUser.uid}_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
        
        // Initialize activity tracker
        userActivityTracker.sessionStart = Date.now();
        
        // Check for concurrent sessions (account sharing detection)
        await checkConcurrentSessions();
        
        // Log session start with enhanced data
        await logUserActivity('session_start', {
            sessionId: sessionId,
            ip: userIP,
            location: userLocation,
            userAgent: navigator.userAgent,
            loginTime: userActivityTracker.loginTime,
            timestamp: firebase.firestore.FieldValue.serverTimestamp()
        });

        // Persist last login info for admin visibility
        try {
            await db.collection('users').doc(currentUser.uid).set({
                lastLoginAt: firebase.firestore.FieldValue.serverTimestamp(),
                lastLoginSessionId: sessionId,
                lastLoginIp: userIP || null,
                lastLoginLocation: userLocation || null,
                isOnline: true,
                currentSessionId: sessionId
            }, { merge: true });
        } catch (_) {}
        
        // Update daily stats
        const streakState = await syncUserStreakState('login');
        userActivityTracker.dailyStats.studyStreak = Number(streakState?.current || 0);
        renderDashboardStreakLeaderboard();
        userActivityTracker.dailyStats.loginCount++;
        await updateDailyStats();
        
        // Start periodic activity logging
        const intervalId = setInterval(logPeriodicActivity, 30000); // Every 30 seconds
        resourceManager.registerResource('periodicActivity', { intervalId }, () => clearInterval(intervalId));
        
        // Initialize real-time tracking
        initializeRealtimeTracking();
        initializeMicroInteractionTracking();
        trackPageVisit(pageVisitState.currentPageId || 'subject-dashboard-page');
        
        // Initialize admin diagnostics if user is admin
        initializeAdminDiagnostics();
        
    }, 'User Tracking Initialization');
}

const ACCOUNT_SHARING_ENFORCEMENT_TIERS = new Set(['paid', 'pro', 'family', 'friend']);

function isSharingEnforcementTier(tierValue) {
    const normalizedTier = String(tierValue || '').trim().toLowerCase();
    return ACCOUNT_SHARING_ENFORCEMENT_TIERS.has(normalizedTier);
}

// Check for concurrent sessions (account sharing detection)
async function checkConcurrentSessions() {
    return safeExecuteAsync(async () => {
        const sessionsSnapshot = await db.collection('userSessions')
            .where('userId', '==', currentUser.uid)
            .where('isActive', '==', true)
            .get();
        
        const activeSessions = [];
        sessionsSnapshot.forEach(doc => {
            const session = doc.data();
            if (session.ip !== userIP) {
                activeSessions.push(session);
            }
        });
        
        const isAdmin = (currentUser.role || '').toLowerCase() === 'admin';
        const enforceSharingRules = isSharingEnforcementTier(currentUser?.tier);

        if (activeSessions.length > 0) {
            if (isAdmin) {
                await handleAdminNewIPChallenge(activeSessions);
            } else if (enforceSharingRules) {
                // Account sharing detected
                await handleAccountSharing(activeSessions);
            } else {
                // Free tier users are excluded from automated sharing bans.
                console.info('Concurrent sessions detected for free-tier user; enforcement skipped.', currentUser?.uid);
            }
        }
        
    }, 'Concurrent Session Check');
}

// Handle account sharing detection
async function handleAccountSharing(concurrentSessions) {
    return safeExecuteAsync(async () => {
        if (!isSharingEnforcementTier(currentUser?.tier)) return;

        const tierBeforeViolation = currentUser?.tier || 'free';

        // Remove paid access
        await db.collection('users').doc(currentUser.uid).update({
            tier: 'free',
            accountSharingDetected: true,
            accountSharingDetectedAt: firebase.firestore.FieldValue.serverTimestamp(),
            accountSharingInstances: firebase.firestore.FieldValue.increment(1),
            accountSharingRestoredAt: null,
            accountSharingRestoredBy: null,
            tierBeforeSharingViolation: tierBeforeViolation,
            concurrentSessions: concurrentSessions.map(s => ({
                ip: s.ip,
                userAgent: s.userAgent,
                lastSeen: s.lastSeen
            }))
        });
        
        // Log the violation
        await db.collection('accountViolations').add({
            userId: currentUser.uid,
            userEmail: currentUser.email,
            violationType: 'account_sharing',
            detectedAt: firebase.firestore.FieldValue.serverTimestamp(),
            concurrentSessions: concurrentSessions,
            currentIP: userIP,
            currentUserAgent: navigator.userAgent,
            resolved: false
        });
        
        // Show warning to user
        showAccountSharingWarning();
        
        // Force logout after warning
        setTimeout(() => {
            handleLogout();
        }, 10000);
        
    }, 'Account Sharing Handling');
}

// Admin-only challenge for new IPs to avoid account sharing enforcement
async function handleAdminNewIPChallenge(concurrentSessions) {
    return safeExecuteAsync(async () => {
        // Retired the manual security question to keep login friction-free.
        const answer = null;
        const isCorrect = true;

        try {
            await db.collection('adminIpChallenges').add({
                userId: currentUser.uid,
                userEmail: currentUser.email,
                detectedAt: firebase.firestore.FieldValue.serverTimestamp(),
                concurrentSessions: concurrentSessions,
                currentIP: userIP,
                providedAnswer: answer,
                status: 'skipped_prompt'
            });
        } catch (_) {}

        return;
    }, 'Admin IP Challenge');
}

async function permanentlyBanAdmin(concurrentSessions, providedAnswer) {
    return safeExecuteAsync(async () => {
        try {
            await db.collection('users').doc(currentUser.uid).set({
                role: 'banned',
                isBanned: true,
                bannedAt: firebase.firestore.FieldValue.serverTimestamp(),
                bannedReason: 'failed_admin_ip_challenge',
                bannedIp: userIP || null,
                bannedAnswer: providedAnswer || null
            }, { merge: true });
        } catch (_) {}

        try {
            await db.collection('accountViolations').add({
                userId: currentUser.uid,
                userEmail: currentUser.email,
                violationType: 'admin_failed_ip_challenge',
                detectedAt: firebase.firestore.FieldValue.serverTimestamp(),
                concurrentSessions: concurrentSessions,
                currentIP: userIP,
                currentUserAgent: navigator.userAgent,
                providedAnswer: providedAnswer || null
            });
        } catch (_) {}

        handleLogout();
    }, 'Admin Permanent Ban');
}

// Show account sharing warning
function showAccountSharingWarning() {
    const modal = document.createElement('div');
    modal.className = 'fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-[20000]';
    modal.innerHTML = `
        <div class="bg-white rounded-xl p-8 max-w-md mx-4 shadow-2xl">
            <div class="text-center">
                <div class="w-16 h-16 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4">
                    <svg class="w-8 h-8 text-red-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-2.5L13.732 4c-.77-.833-1.964-.833-2.732 0L3.732 16.5c-.77.833.192 2.5 1.732 2.5z"></path>
                    </svg>
                </div>
                <h2 class="text-2xl font-bold text-gray-900 mb-4">Account Sharing Detected</h2>
                <p class="text-gray-600 mb-6">
                    Your paid account has been detected being used from multiple locations simultaneously.
                    This violates our terms of service.
                </p>
                <div class="bg-red-50 border border-red-200 rounded-lg p-4 mb-6">
                    <h3 class="font-semibold text-red-800 mb-2">Actions Taken:</h3>
                    <ul class="text-sm text-red-700 space-y-1">
                        <li>• Paid-plan access has been removed</li>
                        <li>• Account downgraded to free tier</li>
                        <li>• You will be logged out in 10 seconds</li>
                    </ul>
                </div>
                <p class="text-sm text-gray-500">
                    To restore access, please contact an administrator and explain the situation.
                </p>
            </div>
        </div>
    `;
    document.body.appendChild(modal);
}

// Log user activity
async function logUserActivity(activityType, additionalData = {}) {
    if (!currentUser) return;
    
    return safeExecuteAsync(async () => {
        const activityData = {
            userId: currentUser.uid,
            userEmail: currentUser.email,
            activityType: activityType,
            sessionId: sessionId,
            ip: userIP,
            location: userLocation,
            userAgent: navigator.userAgent,
            timestamp: firebase.firestore.FieldValue.serverTimestamp(),
            additionalData: (additionalData && typeof additionalData === 'object') ? additionalData : {}
        };
        
        await db.collection('userActivities').add(activityData);
        
        // Update session activity (respect session end)
        if (sessionId) {
            const sessionActive = activityType !== 'session_end';
            const sessionUpdate = {
                userId: currentUser.uid,
                sessionId: sessionId,
                ip: userIP,
                userAgent: navigator.userAgent,
                isActive: sessionActive,
                lastSeen: firebase.firestore.FieldValue.serverTimestamp(),
                lastActivity: activityType
            };

            if (!sessionActive) {
                sessionUpdate.endedAt = firebase.firestore.FieldValue.serverTimestamp();
            }

            await db.collection('userSessions').doc(sessionId).set(sessionUpdate, { merge: true });
        }
        
    }, 'User Activity Logging');
}

function getLocalDateKey(date = new Date()) {
    const safeDate = date instanceof Date ? date : new Date(date);
    if (Number.isNaN(safeDate.getTime())) return '';
    const year = safeDate.getFullYear();
    const month = String(safeDate.getMonth() + 1).padStart(2, '0');
    const day = String(safeDate.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
}

function getPreviousLocalDateKey(dateKey) {
    if (!dateKey) return '';
    const parsed = new Date(`${dateKey}T00:00:00`);
    if (Number.isNaN(parsed.getTime())) return '';
    parsed.setDate(parsed.getDate() - 1);
    return getLocalDateKey(parsed);
}

function sanitizeAvatarEmojiInput(value) {
    if (typeof value !== 'string') return '';
    const compact = value.replace(/\s+/g, '').trim();
    if (!compact) return '';
    return Array.from(compact).slice(0, 4).join('');
}

function getUserAvatarEmoji(user = currentUser) {
    return sanitizeAvatarEmojiInput(user?.avatarEmoji || '');
}

function hasUserProfilePicture(user = currentUser) {
    return !!String(user?.profilePictureURL || '').trim();
}

function currentUserHasAvatar(user = currentUser) {
    return !!(getUserAvatarEmoji(user) || hasUserProfilePicture(user));
}

function shouldShowDashboardStreakNewTag(now = Date.now()) {
    return Number(now) < STREAK_NEW_TAG_END_DATE_UTC;
}

function getAvatarSlotOption(index = 0) {
    const total = AVATAR_SLOT_OPTIONS.length;
    if (!total) return '🙂';
    const normalized = ((Math.floor(index) % total) + total) % total;
    return AVATAR_SLOT_OPTIONS[normalized];
}

function getAvatarSlotWindow(index = 0) {
    return {
        upper: getAvatarSlotOption(index - 1),
        current: getAvatarSlotOption(index),
        lower: getAvatarSlotOption(index + 1)
    };
}

function getAvatarSlotIndexForEmoji(emoji = '') {
    const normalized = sanitizeAvatarEmojiInput(emoji);
    if (!normalized) return -1;
    return AVATAR_SLOT_OPTIONS.findIndex((option) => option === normalized);
}

function getAvatarOnboardingSnoozeKey(uid = currentUser?.uid) {
    const safeUid = String(uid || 'anonymous').trim() || 'anonymous';
    return `${AVATAR_ONBOARDING_SNOOZE_KEY_PREFIX}${safeUid}`;
}

function getAvatarOnboardingSnoozeUntil(uid = currentUser?.uid) {
    const memoryUntil = Number(avatarOnboardingState.snoozedUntilMs || 0);
    try {
        const raw = localStorage.getItem(getAvatarOnboardingSnoozeKey(uid));
        const value = Number(raw || 0);
        const localUntil = Number.isFinite(value) && value > 0 ? value : 0;
        return Math.max(localUntil, memoryUntil);
    } catch (_) {
        return memoryUntil;
    }
}

function isAvatarOnboardingSnoozed(uid = currentUser?.uid) {
    return Date.now() < getAvatarOnboardingSnoozeUntil(uid);
}

function setAvatarOnboardingSnooze(ms = AVATAR_ONBOARDING_DEFAULT_SNOOZE_MS, uid = currentUser?.uid) {
    try {
        const durationMs = Math.max(60 * 1000, Number(ms || 0));
        const until = Date.now() + durationMs;
        avatarOnboardingState.snoozedUntilMs = until;
        localStorage.setItem(getAvatarOnboardingSnoozeKey(uid), String(until));
    } catch (_) {}
}

function clearAvatarOnboardingSnooze(uid = currentUser?.uid) {
    avatarOnboardingState.snoozedUntilMs = 0;
    try {
        localStorage.removeItem(getAvatarOnboardingSnoozeKey(uid));
    } catch (_) {}
}

function clearAvatarOnboardingTimers() {
    if (avatarOnboardingState.luckyIntervalId) {
        clearInterval(avatarOnboardingState.luckyIntervalId);
        avatarOnboardingState.luckyIntervalId = null;
    }
    if (avatarOnboardingState.luckyTimeoutId) {
        clearTimeout(avatarOnboardingState.luckyTimeoutId);
        avatarOnboardingState.luckyTimeoutId = null;
    }
}

function setAvatarOnboardingVisible(visible) {
    const overlay = document.getElementById('avatar-onboarding-overlay');
    if (!overlay) return;
    const shouldShow = !!visible;
    overlay.classList.toggle('hidden', !shouldShow);
    overlay.style.display = shouldShow ? 'flex' : 'none';
    overlay.setAttribute('aria-hidden', shouldShow ? 'false' : 'true');
    document.body.classList.toggle('avatar-onboarding-active', shouldShow);
    if (!shouldShow) {
        overlay.classList.remove('is-visible');
    } else {
        overlay.classList.add('is-visible');
        setTimeout(() => {
            document.getElementById('avatar-slot-window')?.focus();
        }, 0);
    }
    avatarOnboardingState.visible = shouldShow;
}

function setAvatarOnboardingMessage(message = '', tone = 'muted') {
    const messageEl = document.getElementById('avatar-onboarding-message');
    if (!messageEl) return;
    messageEl.textContent = message || '';
    messageEl.dataset.tone = tone;
}

function renderAvatarOnboardingSlotWindow(index = avatarOnboardingState.selectedIndex, { animate = false } = {}) {
    const total = Math.max(1, AVATAR_SLOT_OPTIONS.length);
    const normalizedIndex = ((Math.floor(Number(index || 0)) % total) + total) % total;
    avatarOnboardingState.selectedIndex = normalizedIndex;
    const slotWindow = document.getElementById('avatar-slot-window');
    const upperEl = document.getElementById('avatar-slot-upper');
    const currentEl = document.getElementById('avatar-slot-current');
    const lowerEl = document.getElementById('avatar-slot-lower');
    const slot = getAvatarSlotWindow(normalizedIndex);

    if (upperEl) upperEl.textContent = slot.upper;
    if (currentEl) currentEl.textContent = slot.current;
    if (lowerEl) lowerEl.textContent = slot.lower;

    document.querySelectorAll('[data-avatar-slot-index]').forEach((button) => {
        const buttonIndex = Number(button.getAttribute('data-avatar-slot-index'));
        const isActive = Number.isFinite(buttonIndex) && buttonIndex === normalizedIndex;
        button.classList.toggle('is-active', isActive);
        button.setAttribute('aria-pressed', isActive ? 'true' : 'false');
    });

    if (slotWindow && animate) {
        slotWindow.classList.remove('is-spinning');
        // Force reflow so repeated spins retrigger smoothly.
        void slotWindow.offsetHeight;
        slotWindow.classList.add('is-spinning');
    }
}

function selectAvatarOnboardingOption(index = 0) {
    stopAvatarOnboardingLuckySpin();
    renderAvatarOnboardingSlotWindow(index, { animate: true });
}

function stepAvatarOnboardingSlot(step = 1, { animate = true } = {}) {
    const delta = Number(step || 0);
    avatarOnboardingState.selectedIndex += delta;
    renderAvatarOnboardingSlotWindow(avatarOnboardingState.selectedIndex, { animate });
}

function stopAvatarOnboardingLuckySpin() {
    clearAvatarOnboardingTimers();
    const slotWindow = document.getElementById('avatar-slot-window');
    if (slotWindow) slotWindow.classList.remove('is-spinning');
}

function dismissAvatarOnboarding({
    snoozeMs = AVATAR_ONBOARDING_DEFAULT_SNOOZE_MS,
    feedback = 'Avatar picker closed for now. You can set one later in Account Settings.'
} = {}) {
    stopAvatarOnboardingLuckySpin();
    avatarOnboardingState.dismissedForSession = true;
    avatarOnboardingState.syncing = false;
    setAvatarOnboardingVisible(false);
    if (snoozeMs > 0 && currentUser?.uid) {
        setAvatarOnboardingSnooze(snoozeMs, currentUser.uid);
    }
    setAvatarOnboardingMessage(feedback, 'muted');
}

function startAvatarOnboardingLuckySpin() {
    if (!avatarOnboardingState.visible || avatarOnboardingState.syncing) return;
    stopAvatarOnboardingLuckySpin();

    setAvatarOnboardingMessage('Feeling lucky...', 'info');
    avatarOnboardingState.luckyIntervalId = setInterval(() => {
        stepAvatarOnboardingSlot(1, { animate: true });
    }, 90);

    avatarOnboardingState.luckyTimeoutId = setTimeout(() => {
        stopAvatarOnboardingLuckySpin();
        const randomOffset = 1 + Math.floor(Math.random() * Math.max(1, AVATAR_SLOT_OPTIONS.length));
        stepAvatarOnboardingSlot(randomOffset, { animate: true });
        setAvatarOnboardingMessage('Nice pick. Save to continue.', 'muted');
    }, 1500);
}

async function saveAvatarFromOnboarding() {
    if (!currentUser?.uid || avatarOnboardingState.syncing) return;

    const emoji = sanitizeAvatarEmojiInput(getAvatarSlotOption(avatarOnboardingState.selectedIndex));
    if (!emoji) {
        setAvatarOnboardingMessage('Pick an avatar first.', 'error');
        return;
    }

    avatarOnboardingState.syncing = true;
    setAvatarOnboardingMessage('Saving avatar...', 'info');

    try {
        await db.collection('users').doc(currentUser.uid).set({
            avatarEmoji: emoji,
            avatarUpdatedAt: firebase.firestore.FieldValue.serverTimestamp(),
            avatarOnboardingCompletedAt: firebase.firestore.FieldValue.serverTimestamp()
        }, { merge: true });

        currentUser.avatarEmoji = emoji;
        const userEmojiInput = document.getElementById('user-avatar-emoji');
        if (userEmojiInput) userEmojiInput.value = emoji;
        const adminEmojiInput = document.getElementById('admin-avatar-emoji');
        if (adminEmojiInput) adminEmojiInput.value = emoji;

        clearAvatarOnboardingSnooze(currentUser.uid);
        avatarOnboardingState.dismissedForSession = false;
        updateWelcomeMessage();
        try { await upsertStreakLeaderboardEntry(); } catch (_) {}
        renderDashboardStreakLeaderboard();
        setAvatarOnboardingVisible(false);
        setAvatarOnboardingMessage('');
    } catch (error) {
        console.error('Failed to save avatar from onboarding:', error);
        setAvatarOnboardingMessage('Could not save avatar. Try again.', 'error');
    } finally {
        avatarOnboardingState.syncing = false;
    }
}

function initializeAvatarOnboardingControls() {
    if (avatarOnboardingState.initialized) return true;

    const upBtn = document.getElementById('avatar-slot-up');
    const downBtn = document.getElementById('avatar-slot-down');
    const closeBtn = document.getElementById('avatar-onboarding-close');
    const skipBtn = document.getElementById('avatar-slot-skip');
    const luckyBtn = document.getElementById('avatar-slot-lucky');
    const saveBtn = document.getElementById('avatar-slot-save');
    const slotWindow = document.getElementById('avatar-slot-window');
    const overlay = document.getElementById('avatar-onboarding-overlay');

    if (!upBtn || !downBtn || !luckyBtn || !saveBtn || !slotWindow || !overlay) {
        return false;
    }

    upBtn.addEventListener('click', () => {
        stopAvatarOnboardingLuckySpin();
        stepAvatarOnboardingSlot(-1, { animate: true });
    });

    downBtn.addEventListener('click', () => {
        stopAvatarOnboardingLuckySpin();
        stepAvatarOnboardingSlot(1, { animate: true });
    });

    closeBtn?.addEventListener('click', () => {
        dismissAvatarOnboarding();
    });

    skipBtn?.addEventListener('click', () => {
        dismissAvatarOnboarding();
    });

    luckyBtn.addEventListener('click', () => {
        startAvatarOnboardingLuckySpin();
    });

    saveBtn.addEventListener('click', () => {
        saveAvatarFromOnboarding();
    });

    slotWindow.addEventListener('wheel', (event) => {
        event.preventDefault();
        stopAvatarOnboardingLuckySpin();
        stepAvatarOnboardingSlot(event.deltaY > 0 ? 1 : -1, { animate: true });
    }, { passive: false });

    slotWindow.addEventListener('click', (event) => {
        if (event.target.closest('button')) return;
        stopAvatarOnboardingLuckySpin();
        const rect = slotWindow.getBoundingClientRect();
        const midpoint = rect.top + (rect.height / 2);
        stepAvatarOnboardingSlot(event.clientY < midpoint ? -1 : 1, { animate: true });
    });

    slotWindow.addEventListener('keydown', (event) => {
        if (event.key === 'ArrowUp' || event.key === 'ArrowLeft') {
            event.preventDefault();
            stopAvatarOnboardingLuckySpin();
            stepAvatarOnboardingSlot(-1, { animate: true });
            return;
        }
        if (event.key === 'ArrowDown' || event.key === 'ArrowRight') {
            event.preventDefault();
            stopAvatarOnboardingLuckySpin();
            stepAvatarOnboardingSlot(1, { animate: true });
            return;
        }
        if (event.key === 'Enter') {
            event.preventDefault();
            saveAvatarFromOnboarding();
        }
    });

    if (slotWindow && !slotWindow.hasAttribute('tabindex')) {
        slotWindow.setAttribute('tabindex', '0');
    }

    overlay.addEventListener('click', (event) => {
        if (event.target === overlay) {
            dismissAvatarOnboarding();
        }
    });

    document.querySelectorAll('[data-avatar-slot-index]').forEach((button) => {
        button.addEventListener('click', () => {
            const buttonIndex = Number(button.getAttribute('data-avatar-slot-index'));
            if (!Number.isFinite(buttonIndex)) return;
            selectAvatarOnboardingOption(buttonIndex);
        });
    });

    if (!avatarOnboardingState.escapeBound) {
        document.addEventListener('keydown', (event) => {
            if (event.key !== 'Escape') return;
            if (!avatarOnboardingState.visible) return;
            dismissAvatarOnboarding();
        });
        avatarOnboardingState.escapeBound = true;
    }

    avatarOnboardingState.initialized = true;
    return true;
}

function syncAvatarOnboardingPrompt() {
    if (!currentUser) {
        avatarOnboardingState.lastUid = null;
        avatarOnboardingState.dismissedForSession = false;
        stopAvatarOnboardingLuckySpin();
        setAvatarOnboardingVisible(false);
        setAvatarOnboardingMessage('');
        return;
    }

    if (avatarOnboardingState.lastUid !== currentUser.uid) {
        avatarOnboardingState.lastUid = currentUser.uid;
        avatarOnboardingState.dismissedForSession = false;
    }

    if (currentUserHasAvatar(currentUser)) {
        clearAvatarOnboardingSnooze(currentUser.uid);
        avatarOnboardingState.dismissedForSession = false;
        stopAvatarOnboardingLuckySpin();
        setAvatarOnboardingVisible(false);
        setAvatarOnboardingMessage('');
        return;
    }

    if (avatarOnboardingState.dismissedForSession) {
        setAvatarOnboardingVisible(false);
        return;
    }

    if (isAvatarOnboardingSnoozed(currentUser.uid)) {
        setAvatarOnboardingVisible(false);
        return;
    }

    const controlsReady = initializeAvatarOnboardingControls();
    if (!controlsReady) return;

    const currentAvatarIndex = getAvatarSlotIndexForEmoji(getUserAvatarEmoji(currentUser));
    if (currentAvatarIndex >= 0) {
        avatarOnboardingState.selectedIndex = currentAvatarIndex;
    } else if (!avatarOnboardingState.visible) {
        avatarOnboardingState.selectedIndex = Math.floor(Math.random() * Math.max(1, AVATAR_SLOT_OPTIONS.length));
    }

    renderAvatarOnboardingSlotWindow(avatarOnboardingState.selectedIndex, { animate: false });
    setAvatarOnboardingMessage('Choose an avatar to continue.', 'muted');
    setAvatarOnboardingVisible(true);
}

async function upsertStreakLeaderboardEntry({
    studyStreak = Number(currentUser?.studyStreakCurrent || 0),
    bestStudyStreak = Number(currentUser?.studyStreakBest || 0),
    streakLastActiveDate = currentUser?.studyStreakLastActiveDate || getLocalDateKey()
} = {}) {
    if (!currentUser?.uid) return;

    const safeStudyStreak = Math.max(0, Number(studyStreak || 0));
    const safeBestStudyStreak = Math.max(safeStudyStreak, Number(bestStudyStreak || 0));
    const safeDateKey = typeof streakLastActiveDate === 'string' && streakLastActiveDate
        ? streakLastActiveDate
        : getLocalDateKey();

    await db.collection('streakLeaderboard').doc(currentUser.uid).set({
        userId: currentUser.uid,
        displayName: String(currentUser.displayName || currentUser.email || 'User').trim(),
        avatarEmoji: getUserAvatarEmoji(currentUser) || null,
        profilePictureURL: currentUser.profilePictureURL || null,
        studyStreak: safeStudyStreak,
        bestStudyStreak: safeBestStudyStreak,
        streakLastActiveDate: safeDateKey,
        updatedAt: firebase.firestore.FieldValue.serverTimestamp()
    }, { merge: true });
}

async function syncUserStreakState(trigger = 'activity') {
    if (!currentUser?.uid) {
        return { current: 0, best: 0, dateKey: getLocalDateKey() };
    }
    if (streakStateSyncPromise) return streakStateSyncPromise;

    streakStateSyncPromise = (async () => {
        const todayKey = getLocalDateKey();
        const yesterdayKey = getPreviousLocalDateKey(todayKey);
        let userData = { ...(currentUser || {}) };

        try {
            const userDoc = await db.collection('users').doc(currentUser.uid).get();
            if (userDoc.exists) {
                userData = { ...userData, ...(userDoc.data() || {}) };
            }
        } catch (error) {
            console.warn('Could not read user streak state, falling back to local profile:', error);
        }

        const previousCurrent = Math.max(0, Number(userData.studyStreakCurrent || 0));
        const previousBest = Math.max(previousCurrent, Number(userData.studyStreakBest || 0));
        const previousDateKey = typeof userData.studyStreakLastActiveDate === 'string'
            ? userData.studyStreakLastActiveDate
            : '';

        let nextCurrent = previousCurrent;
        if (previousDateKey === todayKey) {
            nextCurrent = Math.max(previousCurrent, 1);
        } else if (previousDateKey === yesterdayKey) {
            nextCurrent = Math.max(previousCurrent + 1, 1);
        } else {
            nextCurrent = 1;
        }

        const nextBest = Math.max(previousBest, nextCurrent);
        const shouldPersistUserState = previousDateKey !== todayKey || previousCurrent !== nextCurrent || previousBest !== nextBest;

        if (shouldPersistUserState) {
            await db.collection('users').doc(currentUser.uid).set({
                studyStreakCurrent: nextCurrent,
                studyStreakBest: nextBest,
                studyStreakLastActiveDate: todayKey,
                studyStreakUpdatedAt: firebase.firestore.FieldValue.serverTimestamp()
            }, { merge: true });
        }

        currentUser.studyStreakCurrent = nextCurrent;
        currentUser.studyStreakBest = nextBest;
        currentUser.studyStreakLastActiveDate = todayKey;
        userActivityTracker.dailyStats.studyStreak = nextCurrent;

        try {
            await upsertStreakLeaderboardEntry({
                studyStreak: nextCurrent,
                bestStudyStreak: nextBest,
                streakLastActiveDate: todayKey
            });
        } catch (error) {
            console.warn(`Unable to sync streak leaderboard (${trigger}):`, error);
        }

        return {
            current: nextCurrent,
            best: nextBest,
            dateKey: todayKey
        };
    })().finally(() => {
        streakStateSyncPromise = null;
    });

    return streakStateSyncPromise;
}

// Update daily statistics
async function updateDailyStats() {
    if (!currentUser) return;
    
    const today = new Date().toDateString();
    const dailyStatsRef = db.collection('userDailyStats').doc(`${currentUser.uid}_${today}`);
    
    try {
        await dailyStatsRef.set({
            userId: currentUser.uid,
            date: today,
            loginCount: userActivityTracker.dailyStats.loginCount,
            totalSessionTime: userActivityTracker.dailyStats.totalSessionTime,
            subjectsStudied: Array.from(userActivityTracker.dailyStats.subjectsStudied),
            filesAccessed: Array.from(userActivityTracker.dailyStats.filesAccessed),
            studyStreak: Number(userActivityTracker.dailyStats.studyStreak || currentUser?.studyStreakCurrent || 0),
            lastUpdated: firebase.firestore.FieldValue.serverTimestamp()
        }, { merge: true });
    } catch (error) {
        console.error('Failed to update daily stats:', error);
    }
}

// Track logout
async function trackLogout() {
    if (!currentUser) return;

    // Prevent double-logging (e.g., logout button + beforeunload)
    if (hasTrackedLogout) return;
    hasTrackedLogout = true;
    try { await flushInteractionBatch({ immediate: true }); } catch (_) {}
    
    userActivityTracker.logoutTime = Date.now();
    const sessionDuration = userActivityTracker.logoutTime - userActivityTracker.loginTime;
    userActivityTracker.dailyStats.totalSessionTime += sessionDuration;
    
    await logUserActivity('session_end', {
        sessionId: sessionId,
        ip: userIP,
        location: userLocation,
        loginTime: userActivityTracker.loginTime,
        logoutTime: userActivityTracker.logoutTime,
        sessionDuration: sessionDuration,
        totalSubjectTime: userActivityTracker.totalSubjectTime,
        totalFileTime: userActivityTracker.totalFileTime,
        openedFiles: Array.from(userActivityTracker.openedFiles),
        timestamp: firebase.firestore.FieldValue.serverTimestamp()
    });

    // Persist last logout/session summary for admin visibility
    try {
        await db.collection('users').doc(currentUser.uid).set({
            lastLogoutAt: firebase.firestore.FieldValue.serverTimestamp(),
            lastLogoutSessionId: sessionId || null,
            lastSessionDurationMs: sessionDuration,
            lastSessionTotalSubjectTime: userActivityTracker.totalSubjectTime || {},
            lastSessionTotalFileTime: userActivityTracker.totalFileTime || {},
            lastSessionOpenedFiles: Array.from(userActivityTracker.openedFiles),
            isOnline: false,
            currentSessionId: firebase.firestore.FieldValue.delete()
        }, { merge: true });
    } catch (_) {}
    
    await updateDailyStats();
    
    // Cleanup real-time tracking
    cleanupRealtimeTracking();
}

// Enhanced Real-time Tracking System
let realtimeTracker = {
    isOnline: true,
    lastHeartbeat: Date.now(),
    heartbeatInterval: null,
    analyticsInterval: null,
    connectionStatus: 'connected',
    failedRequests: 0,
    maxFailedRequests: 3
};

// Initialize real-time tracking
function initializeRealtimeTracking() {
    if (!currentUser) return;

    // Start heartbeat system
    startHeartbeatSystem();
    
    // Start real-time analytics updates
    if (isAdminUser() || currentUser?.role === 'admin') {
        startRealtimeAnalytics();
    } else if (realtimeTracker.analyticsInterval) {
        clearInterval(realtimeTracker.analyticsInterval);
        realtimeTracker.analyticsInterval = null;
    }
    
    // Monitor connection status
    monitorConnectionStatus();
    
    // Track page visibility changes
    trackPageVisibility();
    
    console.log('Real-time tracking initialized');
}

// Heartbeat system for real-time status
function startHeartbeatSystem() {
    if (realtimeTracker.heartbeatInterval) {
        clearInterval(realtimeTracker.heartbeatInterval);
    }

    realtimeTracker.heartbeatInterval = setInterval(async () => {
        if (document.hidden || !navigator.onLine) {
            return;
        }
        try {
            await sendHeartbeat();
            realtimeTracker.failedRequests = 0;
            updateConnectionStatus('connected');
        } catch (error) {
            realtimeTracker.failedRequests++;
            console.warn(`Heartbeat failed (${realtimeTracker.failedRequests}/${realtimeTracker.maxFailedRequests}):`, error);
            
            if (realtimeTracker.failedRequests >= realtimeTracker.maxFailedRequests) {
                updateConnectionStatus('disconnected');
            }
        }
    }, 30000); // Every 30 seconds
}

// Send heartbeat to maintain active session
async function sendHeartbeat() {
    if (!currentUser || !sessionId) return;
    if (isFirestoreTransportUnstable()) return;

    const heartbeatData = {
        userId: currentUser.uid,
        sessionId: sessionId,
        timestamp: firebase.firestore.FieldValue.serverTimestamp(),
        isActive: true,
        currentSubject: userActivityTracker.currentSubject || 'none',
        currentFile: userActivityTracker.currentFile || 'none',
        pageUrl: window.location.href,
        userAgent: navigator.userAgent,
        screenResolution: `${screen.width}x${screen.height}`,
        timezone: Intl.DateTimeFormat().resolvedOptions().timeZone
    };

    try {
        // Update session document
        await db.collection('userSessions').doc(sessionId).set(heartbeatData, { merge: true });
        
        // Update user's last seen
        await db.collection('users').doc(currentUser.uid).update({
            lastSeen: firebase.firestore.FieldValue.serverTimestamp(),
            isOnline: true,
            currentSessionId: sessionId
        });
    } catch (error) {
        if (typeof error?.message === 'string' && error.message.includes('INTERNAL ASSERTION FAILED')) {
            console.warn('Firestore assertion during heartbeat; pausing heartbeats and triggering recovery.');
            clearInterval(realtimeTracker.heartbeatInterval);
            realtimeTracker.heartbeatInterval = null;
            recoverFirestoreSession();
            return;
        }
        throw error;
    }

    realtimeTracker.lastHeartbeat = Date.now();
}

// Real-time analytics updates
function startRealtimeAnalytics() {
    if (realtimeTracker.analyticsInterval) {
        clearInterval(realtimeTracker.analyticsInterval);
    }

    realtimeTracker.analyticsInterval = setInterval(async () => {
        try {
            if (currentUser && currentUser.role === 'admin') {
                await updateAnalyticsRealtime();
            }
        } catch (error) {
            logError(error, 'Realtime Analytics Interval');
        }
    }, 20000); // Every 20 seconds for admin users
}

// Enhanced real-time analytics  
// Copyright © 2025 Mayukhjit Chakraborty. All rights reserved.
async function updateAnalyticsRealtime() {
    try {
        // Get active sessions in real-time
        const activeSessionsSnapshot = await db.collection('userSessions')
            .where('isActive', '==', true)
            .where('timestamp', '>', firebase.firestore.Timestamp.fromDate(new Date(Date.now() - 300000))) // Last 5 minutes
            .get();

        const activeSessions = activeSessionsSnapshot.docs.map(doc => ({
            id: doc.id,
            ...doc.data()
        }));

        // Update active sessions count
        const activeSessionsCountEl = document.getElementById('active-sessions-count');
        if (activeSessionsCountEl) {
            activeSessionsCountEl.textContent = activeSessions.length;
        }

        // Update active today count
        const today = new Date();
        today.setHours(0, 0, 0, 0);
        
        const todaySessionsSnapshot = await db.collection('userSessions')
            .where('timestamp', '>=', firebase.firestore.Timestamp.fromDate(today))
            .get();

        const activeTodayCountEl = document.getElementById('active-today-count');
        if (activeTodayCountEl) {
            activeTodayCountEl.textContent = todaySessionsSnapshot.size;
        }

        // Update real-time activity feed
        await updateRealtimeActivityFeed(activeSessions);

        // Update system health metrics
        await updateSystemHealthRealtime();

    } catch (error) {
        if (typeof error?.message === 'string' && error.message.includes('INTERNAL ASSERTION FAILED')) {
            console.warn('Firestore assertion during realtime analytics; pausing analytics updates and triggering recovery.');
            clearInterval(realtimeTracker.analyticsInterval);
            realtimeTracker.analyticsInterval = null;
            recoverFirestoreSession();
            return;
        }
        console.error('Real-time analytics update failed:', error);
    }
}

// Update real-time activity feed
async function updateRealtimeActivityFeed(activeSessions) {
    const activityFeedEl = document.getElementById('realtime-activity-feed');
    if (!activityFeedEl) return;

    const activities = [];
    
    for (const session of activeSessions.slice(0, 10)) { // Show last 10 activities
        const userDoc = await db.collection('users').doc(session.userId).get();
        const userData = userDoc.exists ? userDoc.data() : null;
        
        if (userData) {
            activities.push({
                user: userData.displayName || userData.email,
                subject: session.currentSubject || 'Dashboard',
                file: session.currentFile || 'None',
                lastSeen: session.timestamp?.toDate() || new Date(),
                ip: session.ip || 'Unknown'
            });
        }
    }

    // Sort by last seen (most recent first)
    activities.sort((a, b) => b.lastSeen - a.lastSeen);

    // Update the feed
    activityFeedEl.innerHTML = activities.map(activity => `
        <div class="flex items-center justify-between p-3 bg-white/50 rounded-lg border border-white/30">
            <div class="flex items-center space-x-3">
                <div class="w-8 h-8 bg-blue-100 rounded-full flex items-center justify-center">
                    <span class="text-blue-600 font-semibold text-sm">${activity.user.charAt(0).toUpperCase()}</span>
                </div>
                <div>
                    <p class="font-semibold text-gray-800">${activity.user}</p>
                    <p class="text-sm text-gray-600">${activity.subject} • ${activity.file}</p>
                </div>
            </div>
            <div class="text-right">
                <p class="text-xs text-gray-500">${formatTimeAgo(activity.lastSeen)}</p>
                <p class="text-xs text-gray-400">${activity.ip}</p>
            </div>
        </div>
    `).join('');
}

// Monitor connection status
function monitorConnectionStatus() {
    // Listen for online/offline events
    window.addEventListener('online', () => {
        updateConnectionStatus('connected');
        realtimeTracker.failedRequests = 0;
    });

    window.addEventListener('offline', () => {
        updateConnectionStatus('disconnected');
    });

    // Monitor Firebase connection
    db.enableNetwork().catch(() => {
        updateConnectionStatus('disconnected');
    });
    
    // Periodic connection check every 15 seconds
    if (connectionCheckInterval) {
        clearInterval(connectionCheckInterval);
    }
    connectionCheckInterval = setInterval(async () => {
        try {
            // Check if navigator says we're online
            if (!navigator.onLine) {
                updateConnectionStatus('disconnected');
                return;
            }
            
            // Try a lightweight Firebase operation to verify connection
            await db.collection('settings').doc('maintenance').get();
            updateConnectionStatus('connected');
            realtimeTracker.failedRequests = 0;
        } catch (error) {
            // If Firebase operation fails, we're likely disconnected
            updateConnectionStatus('disconnected');
        }
    }, 30000); // Check every 30 seconds
    
    // Initial check
    setTimeout(async () => {
        try {
            if (navigator.onLine) {
                await db.collection('settings').doc('maintenance').get();
                updateConnectionStatus('connected');
            } else {
                updateConnectionStatus('disconnected');
            }
        } catch (error) {
            updateConnectionStatus('disconnected');
        }
    }, 1000);
}

// Update connection status UI
function updateConnectionStatus(status) {
    realtimeTracker.connectionStatus = status;
    const statusElements = document.querySelectorAll('.online-status');
    
    statusElements.forEach(element => {
        if (status === 'connected') {
            element.className = 'w-2 h-2 bg-green-400 rounded-full animate-pulse';
        } else {
            element.className = 'w-2 h-2 bg-red-500 rounded-full';
        }
    });

    // Update status text
    const statusTextElements = document.querySelectorAll('.online-text');
    statusTextElements.forEach(element => {
        element.textContent = status === 'connected' ? 'Online' : 'Offline';
    });
}

// Track page visibility changes
