// Admin Diagnostic Tools
let adminDiagnostics = {
    testResults: [],
    systemHealth: {},
    trackingStatus: {},
    errorLogs: [],
    trackingInterval: null,
    errorCollectionInterval: null,
    firebaseMonitorInterval: null
};

// Initialize admin diagnostics
