function renderLandingSubjectExplorer() {
    const grid = document.getElementById('landing-subject-menu');
    const filters = document.getElementById('landing-subject-board-filters');
    if (!grid || !filters) return;

    const subjects = SUBJECTS
        .map((subject) => {
            const board = SUBJECT_EXAM_BOARD_MAP[(subject || '').toLowerCase()] || 'General';
            return { subject, board };
        })
        .sort((a, b) => a.subject.localeCompare(b.subject));

    const boardOrder = ['All', 'AQA', 'Edexcel', 'OCR', 'Eduqas', 'General'];
    const availableBoards = Array.from(new Set(subjects.map((entry) => entry.board)));
    const filterBoards = boardOrder.filter((board) => board === 'All' || availableBoards.includes(board));
    let activeBoard = 'All';

    const renderCards = () => {
        const visible = subjects.filter((entry) => activeBoard === 'All' || entry.board === activeBoard);
        if (visible.length === 0) {
            grid.innerHTML = '<p class="text-sm text-slate-600">No subjects match this board.</p>';
            return;
        }
        grid.innerHTML = visible.map((entry) => {
            const safeSubject = escapeHTML(entry.subject);
            const safeBoard = escapeHTML(entry.board);
            return `
                <button type="button" class="landing-subject-item" data-board="${safeBoard}" onclick="showAuthPage(false)">
                    <span class="landing-subject-name">${safeSubject}</span>
                    <span class="landing-subject-board">${safeBoard}</span>
                </button>`;
        }).join('');
    };

    filters.innerHTML = filterBoards.map((board) => {
        const isActive = board === activeBoard ? ' is-active' : '';
        const safeBoard = escapeHTML(board);
        return `<button type="button" class="landing-board-filter${isActive}" data-board="${safeBoard}">${safeBoard}</button>`;
    }).join('');

    filters.querySelectorAll('.landing-board-filter').forEach((button) => {
        button.addEventListener('click', () => {
            activeBoard = button.dataset.board || 'All';
            filters.querySelectorAll('.landing-board-filter').forEach((el) => {
                el.classList.toggle('is-active', el === button);
            });
            renderCards();
        });
    });

    renderCards();
}
// =================================================================================
// CORE INITIALIZATION & AUTHENTICATION
// =================================================================================
let appLoadingFailsafePrimary;
let appLoadingFailsafeSecondary;

function ensureInitialView() {
    try {
        if (isResolvingAuthenticatedSession) return;
        const landing = document.getElementById('landing-page');
        const app = document.getElementById('main-app');
        const login = document.getElementById('login-page');
        const verify = document.getElementById('email-verify-page');
        const isVisible = (el) => el && !el.classList.contains('hidden');
        const anyVisible = [app, login, verify, landing].some(isVisible);
        if (!anyVisible && landing) landing.classList.remove('hidden');
    } catch (_) {}
}

function clearAppLoadingFailsafes() {
    if (appLoadingFailsafePrimary) clearTimeout(appLoadingFailsafePrimary);
    if (appLoadingFailsafeSecondary) clearTimeout(appLoadingFailsafeSecondary);
    appLoadingFailsafePrimary = null;
    appLoadingFailsafeSecondary = null;
}

function scheduleAppLoadingFailsafe() {
    clearAppLoadingFailsafes();

    const attemptHide = (force = false) => {
        // Avoid revealing landing/login while Firebase auth is still resolving.
        if (!force && !hasResolvedInitialAuthState) return;
        try { ensureInitialView(); } catch (_) {}
        hideAppLoading();
    };

    // Primary hide waits for resolved auth; secondary is a hard fallback.
    appLoadingFailsafePrimary = setTimeout(() => attemptHide(false), 4000);
    appLoadingFailsafeSecondary = setTimeout(() => attemptHide(true), 12000);
}

function hideAppLoading() {
    const overlay = document.getElementById('app-loading');
    if (!overlay) return;
    if (overlay.dataset.state === 'hidden') return;

    overlay.dataset.state = 'hidden';
    clearAppLoadingFailsafes();
    
    const logo = overlay.querySelector('.animate-logo');
    if (logo) { 
        logo.style.opacity = '1'; 
        logo.style.transform = 'translateY(0)'; 
    }
    
    ensureInitialView();
    
    // Smooth fade out with better timing
    overlay.style.opacity = '0';
    overlay.style.transition = 'opacity 300ms ease-out';
    
    setTimeout(() => { 
        overlay.style.display = 'none';
        // Ensure body scroll is restored
        document.body.style.overflow = '';
    }, 320);
}

function showAppLoading() {
    const overlay = document.getElementById('app-loading');
    if (!overlay) return;
    
    overlay.dataset.state = 'visible';
    overlay.style.display = 'flex';
    overlay.style.opacity = '1';
    document.body.style.overflow = 'hidden';

    scheduleAppLoadingFailsafe();
}

// Fallback: ensure hide after window load
// Security features to prevent unauthorized copying and distribution
function initializeSecurityFeatures() {
    // Right-click context menu is enabled for all areas
    // Users can right-click anywhere to access browser context menu and dev tools
    
    // All keyboard shortcuts are enabled
    // Users can use Ctrl+C, Ctrl+A, Ctrl+S, Ctrl+P, F12, Ctrl+Shift+I, etc. freely
    
    // Text selection is enabled for all areas
    // Users can freely select and copy text anywhere on the page
    
    // Add visible watermark to content areas
    const style = document.createElement('style');
    style.textContent = `
        /* Watermark overlay for content protection */
        .page::after {
            content: 'GCSEMate.com';
            position: fixed;
            bottom: 20px;
            right: 20px;
            font-size: 12px;
            color: rgba(0, 0, 0, 0.1);
            pointer-events: none;
            z-index: 9999;
            font-family: Arial, sans-serif;
            user-select: none;
        }
        
        /* Enable text selection everywhere */
        * {
            -webkit-user-select: text;
            -moz-user-select: text;
            -ms-user-select: text;
            user-select: text;
        }
        
        } catch (error) {
            if (typeof error?.message === 'string' && error.message.includes('INTERNAL ASSERTION FAILED')) {
                console.warn('Firestore assertion during realtime analytics; pausing analytics updates and triggering recovery.');
                clearInterval(realtimeTracker.analyticsInterval);
                realtimeTracker.analyticsInterval = null;
                recoverFirestoreSession();
                return;
            }
            logError(error, 'Realtime Analytics');
            -webkit-user-drag: none;
            -khtml-user-drag: none;
            -moz-user-drag: none;
            -o-user-drag: none;
            user-drag: none;
            pointer-events: auto;
        }
    `;
    document.head.appendChild(style);
    
    // Track suspicious activity
    let suspiciousActivityCount = 0;
    const trackSuspiciousActivity = (action) => {
        suspiciousActivityCount++;
        if (suspiciousActivityCount > 10) {
            console.warn('Multiple suspicious activities detected:', action);
            // Could log to Firestore for admin review
            if (currentUser) {
                logUserActivity('suspicious_activity', {
                    action: action,
                    count: suspiciousActivityCount,
                    timestamp: new Date().toISOString()
                }).catch(() => {}); // Don't block on logging errors
            }
        }
    };
    
    // Developer tools detection is disabled
    // Users can freely use browser dev tools without restrictions
    
    // Detect iframe embedding (unauthorized embedding)
    if (window.self !== window.top) {
        trackSuspiciousActivity('iframe_embedding');
        // Could redirect or show warning
    }
}

// Early slide-in on DOM ready
document.addEventListener('DOMContentLoaded', () => {
    scheduleAppLoadingFailsafe();
    renderLandingSubjectExplorer();

    // Initialize security features
    initializeSecurityFeatures();
    
    // Initialize form validations
    initializeFormValidations();

    // Best-effort: derive brand palette from the local logo (same-origin only)
    try {
        const run = () => extractAndApplyBrandPaletteFromLogo();
        if ('requestIdleCallback' in window) {
            requestIdleCallback(run, { timeout: 1200 });
        } else {
            setTimeout(run, 0);
        }
    } catch (_) {}

    // Ensure all modals close reliably (Escape, backdrop click, close buttons)
    try {
        setupGlobalModalCloseHandlers();
    } catch (_) {}
    
    // Use requestIdleCallback for better performance
    if ('requestIdleCallback' in window) {
        requestIdleCallback(() => {
            const overlay = document.getElementById('app-loading');
            const logo = overlay?.querySelector?.('.animate-logo');
            if (logo) { 
                requestAnimationFrame(() => { 
                    logo.style.opacity = '1'; 
                    logo.style.transform = 'translateY(0)'; 
                }); 
            }
        }, { timeout: 1000 });
    } else {
        setTimeout(() => {
            const overlay = document.getElementById('app-loading');
            const logo = overlay?.querySelector?.('.animate-logo');
            if (logo) { 
                requestAnimationFrame(() => { 
                    logo.style.opacity = '1'; 
                    logo.style.transform = 'translateY(0)'; 
                }); 
            }
        }, 0);
    }
}, { once: true });

function setupGlobalModalCloseHandlers() {
    if (window.__gcsemateModalCloseSetup) return;
    window.__gcsemateModalCloseSetup = true;

    const dynamicModalIdsToClear = new Set([
        'preview-modal',
        'blog-viewer-modal',
        'lesson-viewer-modal',
        'legal-modal',
        'dmca-modal',
        'edit-user-modal',
        'event-modal',
        'confirmation-modal',
        'specification-pdf-modal'
    ]);

    function isVisible(el) {
        if (!el) return false;
        const style = window.getComputedStyle(el);
        return style && style.display !== 'none' && style.visibility !== 'hidden' && style.opacity !== '0';
    }

    function closeModalElement(modalEl) {
        if (!modalEl) return;

        // Special-case mobile menu backdrop cleanup
        if (modalEl.id === 'mobile-menu') {
            if (typeof window.closeMobileMenu === 'function') {
                window.closeMobileMenu({ restoreFocus: false });
                return;
            }
            const backdrop = document.getElementById('mobile-menu-backdrop');
            if (backdrop) backdrop.remove();
            modalEl.classList.remove('menu-open');
        }

        modalEl.style.display = 'none';
        modalEl.classList.add('hidden');

        if (dynamicModalIdsToClear.has(modalEl.id)) {
            modalEl.innerHTML = '';
        }

        document.body.style.overflow = '';
    }

    function getTopmostOpenModal() {
        const candidates = Array.from(document.querySelectorAll('div[id$="-modal"], #tutorial-overlay, #mobile-menu'));
        const open = candidates.filter(isVisible);
        if (open.length === 0) return null;
        open.sort((a, b) => {
            const za = parseInt(window.getComputedStyle(a).zIndex || '0', 10) || 0;
            const zb = parseInt(window.getComputedStyle(b).zIndex || '0', 10) || 0;
            return zb - za;
        });
        return open[0];
    }

    // Backdrop click closes
    const modals = Array.from(document.querySelectorAll('div[id$="-modal"], #tutorial-overlay'));
    modals.forEach(modal => {
        modal.addEventListener('click', (e) => {
            if (e.target === modal) {
                closeModalElement(modal);
            }
        });
    });

    // Close button (delegated): fixes cases where inline handlers only toggle `hidden`
    document.addEventListener('click', (e) => {
        const closeBtn = e.target.closest(
            '[data-modal-close], [aria-label="Close"], [aria-label="Close modal"], [aria-label="Close navigation menu"], .modal-close'
        );
        if (!closeBtn) return;

        const modal = closeBtn.closest('div[id$="-modal"], #tutorial-overlay, #mobile-menu');
        if (!modal) return;

        closeModalElement(modal);
    });

    // Escape closes top-most open modal
    document.addEventListener('keydown', (e) => {
        if (e.key !== 'Escape') return;
        const top = getTopmostOpenModal();
        if (!top) return;
        closeModalElement(top);
    });
}

function extractAndApplyBrandPaletteFromLogo() {
    try {
        const root = document.documentElement;
        const logoEl = document.querySelector('img[src*="gcsemate"], img[alt*="GCSEMate"]');
        const src = logoEl ? (logoEl.getAttribute('src') || '') : 'gcsemate%20new.png';
        const url = new URL(src, window.location.href);

        // Avoid tainted canvas from cross-origin fallback images
        if (url.origin !== window.location.origin) return;

        const img = new Image();
        img.decoding = 'async';
        img.loading = 'eager';
        img.src = url.href;

        img.onload = () => {
            try {
                const canvas = document.createElement('canvas');
                const ctx = canvas.getContext('2d', { willReadFrequently: true });
                if (!ctx) return;

                // Downsample aggressively
                const w = Math.max(24, Math.min(96, img.naturalWidth || 96));
                const h = Math.max(24, Math.min(96, img.naturalHeight || 96));
                canvas.width = w;
                canvas.height = h;
                ctx.drawImage(img, 0, 0, w, h);

                const { data } = ctx.getImageData(0, 0, w, h);

                // Simple hue-bin histogram for saturated colors
                const bins = Array.from({ length: 12 }, () => ({ count: 0, r: 0, g: 0, b: 0 }));
                for (let i = 0; i < data.length; i += 4 * 3) {
                    const r = data[i];
                    const g = data[i + 1];
                    const b = data[i + 2];
                    const a = data[i + 3];
                    if (a < 200) continue;

                    const max = Math.max(r, g, b);
                    const min = Math.min(r, g, b);
                    const l = (max + min) / 2 / 255;
                    const delta = (max - min) / 255;
                    if (l > 0.95 || l < 0.12) continue; // ignore near-white/near-black
                    if (delta < 0.08) continue; // ignore near-gray

                    let hVal = 0;
                    if (max === min) {
                        hVal = 0;
                    } else if (max === r) {
                        hVal = ((g - b) / (max - min)) % 6;
                    } else if (max === g) {
                        hVal = (b - r) / (max - min) + 2;
                    } else {
                        hVal = (r - g) / (max - min) + 4;
                    }
                    hVal = (hVal * 60 + 360) % 360;
                    const bin = Math.floor(hVal / 30);
                    const slot = bins[bin];
                    slot.count++;
                    slot.r += r;
                    slot.g += g;
                    slot.b += b;
                }

                const sorted = bins
                    .filter(b => b.count > 0)
                    .sort((a, b) => b.count - a.count);

                if (sorted.length === 0) return;

                const primary = sorted[0];
                const p = {
                    r: Math.round(primary.r / primary.count),
                    g: Math.round(primary.g / primary.count),
                    b: Math.round(primary.b / primary.count)
                };

                function mix(c1, c2, t) {
                    return {
                        r: Math.round(c1.r + (c2.r - c1.r) * t),
                        g: Math.round(c1.g + (c2.g - c1.g) * t),
                        b: Math.round(c1.b + (c2.b - c1.b) * t)
                    };
                }
                const white = { r: 255, g: 255, b: 255 };
                const black = { r: 0, g: 0, b: 0 };

                const brand50 = mix(p, white, 0.90);
                const brand100 = mix(p, white, 0.80);
                const brand300 = mix(p, white, 0.55);
                const brand400 = mix(p, white, 0.35);
                const brand500 = p;
                const brand600 = mix(p, black, 0.12);
                const brand700 = mix(p, black, 0.24);

                function setTriplet(name, c) {
                    root.style.setProperty(name, `${c.r} ${c.g} ${c.b}`);
                }

                setTriplet('--brand-50', brand50);
                setTriplet('--brand-100', brand100);
                setTriplet('--brand-300', brand300);
                setTriplet('--brand-400', brand400);
                setTriplet('--brand-500', brand500);
                setTriplet('--brand-600', brand600);
                setTriplet('--brand-700', brand700);
            } catch (_) {
                // Best-effort only
            }
        };
    } catch (_) {
        // Best-effort only
    }
}

