function showPage(pageId) {
    const pages = document.querySelectorAll('.page');
    let current = null;
    let currentId = null;
    pages.forEach(page => {
        if (!page.classList.contains('hidden')) {
            current = page;
            currentId = page.id;
        }
    });
    const newPage = document.getElementById(pageId);
    if (!newPage) return;

    if (!isAdminUser() && isSectionUnderMaintenance(pageId)) {
        showSectionMaintenanceNotice(pageId);
        return;
    }

    const leavingToolsPage = currentId === 'tools-page' && pageId !== 'tools-page';
    const enteringToolsPage = currentId !== 'tools-page' && pageId === 'tools-page';

    if (leavingToolsPage && toolsTimerState?.isRunning) {
        try {
            initializeToolsTimerPip();
            setToolsTimerPipVisible(true);
        } catch (_) {}
    }

    if (enteringToolsPage && toolsTimerState?.pipVisible) {
        try {
            setToolsTimerPipVisible(false);
        } catch (_) {}
    }

    ensureDeferredAssetsForPage(pageId);

    // Setup paste handler when blog page is shown
    if (pageId === 'blog-page') {
        setTimeout(() => {
            setupBlogPasteHandler();
            setupBlogEditorEnhancements();
        }, 100);
    }

    if (pageId === 'lessons-page') {
        setTimeout(() => {
            setupLessonsImagePasteHandler();
            setupLessonFontControls();
            populateLessonSubjectOptions();
            syncLessonSubjectCustomVisibility();
            renderLessonQuestionBuilder(parseLessonQuestions(document.getElementById('lesson-questions')?.value || ''));
            setupLessonsFilters();
            renderLessonsPage(allLessons);
        }, 100);
    }
    
    // Re-render useful links when page is shown (to ensure search/filter work)
    if (pageId === 'useful-links-page' && Object.keys(allUsefulLinks).length > 0) {
        setTimeout(() => filterAndRenderLinks(), 100);
    }

    if (pageId === 'tools-page') {
        setTimeout(() => {
            initializeToolsTimerPip();
            updateToolsTimerUI();
        }, 50);
    }

    if (pageId === 'account-settings-page') {
        setTimeout(() => {
            renderSubscriptionStatusPanel(currentUser);
            renderNavTabCustomizer();
        }, 50);
    }
    
    // AI Tutor initialization removed (feature disabled)

    if (current && current !== newPage) {
        // Modern iOS-like leave
        current.classList.add('page-leave-modern');
        setTimeout(() => {
            current.classList.add('hidden');
            current.classList.remove('page-leave-modern');
        }, 340);
    }

    // Enter animation with slight delay to avoid overlap
    // Prevent layout jank by measuring and pre-setting height
    const container = document.getElementById('page-container') || newPage.parentElement;
    const prevHeight = current ? current.offsetHeight : 0;
    const nextHeight = newPage.offsetHeight;
    if (container && prevHeight) container.style.minHeight = prevHeight + 'px';

    requestAnimationFrame(() => {
        newPage.classList.remove('hidden');
        newPage.classList.add('page-enter-modern');
        // Smooth container height morph
        if (container) {
            const h = newPage.offsetHeight || nextHeight || prevHeight;
            container.style.transition = 'min-height 360ms cubic-bezier(0.22,1,0.36,1)';
            container.style.minHeight = h + 'px';
            setTimeout(() => { container.style.minHeight = ''; container.style.transition = ''; }, 380);
        }
        setTimeout(() => newPage.classList.remove('page-enter-modern'), 540);
    });

    // Update nav active state
    document.querySelectorAll('.nav-link').forEach(l => {
        l.classList.remove('active');
        if (l.dataset.page === pageId) l.classList.add('active');
    });
    // Update document title
    try { if (pageTitles[pageId]) document.title = pageTitles[pageId]; } catch (_) {}
    // Lessons removed
    // Close mobile menu on navigation (ensure we also clean up backdrop/inline styles)
    try {
        if (typeof window.closeMobileMenu === 'function') {
            window.closeMobileMenu({ restoreFocus: false });
        } else {
            const mobileMenu = document.getElementById('mobile-menu');
            if (mobileMenu && !mobileMenu.classList.contains('hidden')) {
                const backdrop = document.getElementById('mobile-menu-backdrop');
                if (backdrop) backdrop.remove();
                mobileMenu.classList.add('hidden');
                mobileMenu.classList.remove('menu-open');
                mobileMenu.style.display = 'none';
                document.body.style.overflow = '';
            }
        }
    } catch (_) {}

    try {
        if (currentId !== pageId) {
            pageVisitState.currentPageId = currentId || pageVisitState.currentPageId || pageId;
            trackPageVisit(pageId);
        }
    } catch (_) {}
    
}

// =================================================================================
// ROUTING (clean URLs per tab)
// =================================================================================
const ROUTE_BY_PAGE_ID = {
    'subject-dashboard-page': '/',
    'videos-page': '/videos',
    'blog-page': '/blog',
    'lessons-page': '/lessons',
    'calendar-page': '/calendar',
    'tools-page': '/tools',
    'useful-links-page': '/useful-links',
    'about-page': '/about',
    'features-page': '/features',
    'help-page': '/help',
    'account-settings-page': '/account',
    'checkout-page': '/checkout'
};

const PAGE_ID_BY_ROUTE = Object.keys(ROUTE_BY_PAGE_ID).reduce((acc, pageId) => {
    acc[ROUTE_BY_PAGE_ID[pageId]] = pageId;
    return acc;
}, {});

const PAGE_ID_BY_ROUTE_LOWER = Object.keys(PAGE_ID_BY_ROUTE).reduce((acc, route) => {
    acc[route.toLowerCase()] = PAGE_ID_BY_ROUTE[route];
    return acc;
}, {});

function normalizePathname(pathname) {
    try {
        let p = (pathname || '/').trim();
        if (!p.startsWith('/')) p = '/' + p;
        if (p.length > 1 && p.endsWith('/')) p = p.slice(0, -1);
        return p;
    } catch (_) {
        return '/';
    }
}

function resolvePageIdFromPath(pathname) {
    const normalizedPath = normalizePathname(pathname);
    return PAGE_ID_BY_ROUTE[normalizedPath] || PAGE_ID_BY_ROUTE_LOWER[normalizedPath.toLowerCase()] || null;
}

