window.openVideoSourceInNewTab = function(url) {
    const parsed = parsePlaylistSourceInput(url);
    const target = parsed?.watchUrl || url;
    window.open(target, '_blank', 'noopener,noreferrer');
};

function parseYoutubeUrl(url) {
    try {
        const urlObj = new URL(url);
        const host = (urlObj.hostname || '').toLowerCase();
        const isYouTubeHost = host.includes('youtube.com') || host.includes('youtu.be') || host.includes('youtube-nocookie.com');
        if (isYouTubeHost) {
            const playlistId = urlObj.searchParams.get('list');
            if (playlistId) {
                // Clean playlist ID (remove any extra characters)
                const cleanPlaylistId = playlistId.split('&')[0].split('?')[0];
                return { 
                    type: 'youtube_playlist', 
                    id: cleanPlaylistId, 
                    embedUrl: `https://www.youtube.com/embed/videoseries?list=${cleanPlaylistId}`,
                    watchUrl: `https://www.youtube.com/playlist?list=${cleanPlaylistId}`
                };
            }
            let videoId = urlObj.searchParams.get('v');
            if (!videoId && host.includes('youtu.be')) {
                videoId = urlObj.pathname.slice(1).split('?')[0].split('&')[0];
            }
            // Support common path-based formats
            if (!videoId) {
                const parts = (urlObj.pathname || '').split('/').filter(Boolean);
                // /embed/{id} , /shorts/{id} , /live/{id}
                if (parts[0] === 'embed' && parts[1] && parts[1] !== 'videoseries') {
                    videoId = parts[1];
                } else if ((parts[0] === 'shorts' || parts[0] === 'live') && parts[1]) {
                    videoId = parts[1];
                }
            }
            if (videoId) {
                // Clean video ID
                const cleanVideoId = videoId.split('&')[0].split('?')[0];
                return { 
                    type: 'youtube_video', 
                    id: cleanVideoId, 
                    embedUrl: `https://www.youtube.com/embed/${cleanVideoId}`,
                    watchUrl: `https://www.youtube.com/watch?v=${cleanVideoId}`
                };
            }
        }
    } catch (_) {
    }
    return null;
}

window.openYouTubeInNewTab = function(url) {
    const parsed = parseYoutubeUrl(url);
    const target = parsed?.watchUrl || url;
    window.open(target, '_blank', 'noopener,noreferrer');
};
async function handleAddLink() {
    if (currentUser.role !== 'admin') return;
    const titleInput = document.getElementById('link-title');
    const urlInput = document.getElementById('link-url');
    const messageEl = document.getElementById('add-link-message');
    const titleErrorEl = document.getElementById('link-title-error') || titleInput.nextElementSibling;
    const urlErrorEl = document.getElementById('link-url-error') || urlInput.nextElementSibling;
    
    const title = titleInput.value.trim();
    const url = urlInput.value.trim();
    
    // Clear previous errors
    messageEl.textContent = '';
    messageEl.className = 'text-sm mt-2 h-4';
    if (titleErrorEl) titleErrorEl.textContent = '';
    if (urlErrorEl) urlErrorEl.textContent = '';
    
    // Enhanced validation
    const titleValidation = Validator.title(title);
    if (!titleValidation.valid) {
        titleInput.classList.add('border-red-500', 'bg-red-50');
        if (titleErrorEl) {
            titleErrorEl.textContent = titleValidation.error;
            titleErrorEl.className = 'text-red-600 text-sm mt-1 h-4';
        }
        titleInput.focus();
        return;
    }
    
    const urlValidation = Validator.url(url);
    if (!urlValidation.valid) {
        urlInput.classList.add('border-red-500', 'bg-red-50');
        if (urlErrorEl) {
            urlErrorEl.textContent = urlValidation.error;
            urlErrorEl.className = 'text-red-600 text-sm mt-1 h-4';
        }
        urlInput.focus();
        return;
    }
    
    try {
        const youtubeData = parseYoutubeUrl(url);
        const linkData = {
            title,
            url,
            type: youtubeData ? youtubeData.type : 'link',
            embedUrl: youtubeData ? youtubeData.embedUrl : null,
            createdAt: firebase.firestore.FieldValue.serverTimestamp()
        };
        await db.collection('usefulLinks').add(linkData);
        messageEl.textContent = 'Link added successfully!';
        messageEl.className = 'text-green-600 text-sm mt-2 h-4';
        titleInput.value = '';
        urlInput.value = '';
        titleInput.classList.remove('border-red-500', 'bg-red-50');
        urlInput.classList.remove('border-red-500', 'bg-red-50');
        setTimeout(() => messageEl.textContent = '', 3000);
    } catch (error) {
        console.error("Error adding link:", error);
        messageEl.textContent = 'Failed to add link. Please try again.';
        messageEl.className = 'text-red-600 text-sm mt-2 h-4';
    }
}
async function handleRemoveLink(id) {
    if (currentUser.role !== 'admin') return;
     showConfirmationModal('Are you sure you want to delete this link?', async () => {
        try {
            await db.collection('usefulLinks').doc(id).delete();
            showToast('Link removed.', 'success');
        } catch (error) {
            console.error("Error removing link:", error);
            showToast("Could not remove the link.", 'error');
        }
    });
}
let allUsefulLinks = {};
let linksSearchDebounce = null;

function renderUsefulLinks(usefulLinks) {
    allUsefulLinks = usefulLinks;
    filterAndRenderLinks();
}

function filterAndRenderLinks() {
    const linksContainer = document.getElementById('links-container');
    const emptyState = document.getElementById('links-empty-state');
    const searchInput = document.getElementById('links-search-input');
    const filterSelect = document.getElementById('links-filter-type');
    
    if (!linksContainer) return;
    
    const searchTerm = (searchInput?.value || '').toLowerCase().trim();
    const filterType = filterSelect?.value || 'all';
    
    linksContainer.innerHTML = '';
    
    // Filter links
    const filteredLinks = Object.entries(allUsefulLinks).filter(([id, link]) => {
        const matchesSearch = !searchTerm || 
            link.title.toLowerCase().includes(searchTerm) ||
            (link.url && link.url.toLowerCase().includes(searchTerm));
        const matchesFilter = filterType === 'all' || 
            link.type === filterType ||
            (filterType === 'link' && link.type !== 'youtube_video' && link.type !== 'youtube_playlist');
        return matchesSearch && matchesFilter;
    });
    
    if (filteredLinks.length === 0) {
        linksContainer.classList.add('hidden');
        if (emptyState) emptyState.classList.remove('hidden');
        return;
    }
    
    linksContainer.classList.remove('hidden');
    if (emptyState) emptyState.classList.add('hidden');
    
    // Group by type
    const videos = filteredLinks.filter(([id, link]) => link.type === 'youtube_video' || link.type === 'youtube_playlist');
    const regularLinks = filteredLinks.filter(([id, link]) => link.type !== 'youtube_video' && link.type !== 'youtube_playlist');
    
    // Render videos section
    if (videos.length > 0) {
        const videosSection = document.createElement('div');
        videosSection.className = 'mb-8';
        videosSection.innerHTML = `<h3 class="text-xl font-semibold text-gray-800 mb-4 flex items-center gap-2"><i class="fas fa-video text-red-600 flex items-center"></i> Videos & Playlists</h3>`;
        const videosGrid = document.createElement('div');
        videosGrid.className = 'grid grid-cols-1 lg:grid-cols-2 gap-6';
        
        videos.forEach(([id, link]) => {
            const card = createVideoCard(id, link);
            videosGrid.appendChild(card);
        });
        
        videosSection.appendChild(videosGrid);
        linksContainer.appendChild(videosSection);
    }
    
    // Render regular links section
    if (regularLinks.length > 0) {
        const linksSection = document.createElement('div');
        linksSection.className = videos.length > 0 ? 'mt-8' : '';
        linksSection.innerHTML = `<h3 class="text-xl font-semibold text-gray-800 mb-4 flex items-center gap-2"><i class="fas fa-link text-blue-600 flex items-center"></i> Links & Resources</h3>`;
        const linksGrid = document.createElement('div');
        linksGrid.className = 'grid grid-cols-1 md:grid-cols-2 gap-4';
        
        regularLinks.forEach(([id, link]) => {
            const card = createLinkCard(id, link);
            linksGrid.appendChild(card);
        });
        
        linksSection.appendChild(linksGrid);
        linksContainer.appendChild(linksSection);
    }
    
    initializeTooltips();
}

function createVideoCard(id, link) {
    const card = document.createElement('div');
    card.className = 'bg-white/70 backdrop-blur-lg rounded-xl shadow-md border border-white/30 overflow-hidden hover:shadow-lg transition-all duration-300 hover:scale-[1.02]';
    
    // Parse YouTube URL to get proper embed URL
    const youtubeData = parseYoutubeUrl(link.url);
    let embedUrl = link.embedUrl || '';
    let watchUrl = link.url;
    
    if (youtubeData) {
        embedUrl = youtubeData.embedUrl;
        watchUrl = youtubeData.watchUrl || link.url;
    }
    
    // Build safe embed URL
    const sep = embedUrl.includes('?') ? '&' : '?';
    const finalUrl = `${embedUrl}${sep}modestbranding=1&rel=0&playsinline=1`;
    const uniqueId = `video-card-${id}-${Date.now()}`;
    
    const removeBtn = currentUser.role === 'admin' ? 
        `<button onclick="handleRemoveLink('${id}')" class="absolute top-3 right-3 z-10 bg-white/90 hover:bg-white text-red-600 hover:text-red-700 p-2 rounded-full shadow-md transition-all hover:scale-110" data-tooltip="Remove link" aria-label="Remove link">
            <i class="fas fa-trash text-sm"></i>
        </button>` : '';
    
    const typeIcon = link.type === 'youtube_playlist' ? 'fa-list' : 'fa-play-circle';
    const typeLabel = link.type === 'youtube_playlist' ? 'Playlist' : 'Video';
    
    card.innerHTML = `
        <div class="relative">
            ${removeBtn}
            <div class="aspect-w-16 aspect-h-9 bg-gray-100 rounded-t-xl overflow-hidden video-brand-wrapper relative" id="${uniqueId}">
                <iframe 
                    id="iframe-${uniqueId}"
                    src="${finalUrl}" 
                    frameborder="0" 
                    allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" 
                    allowfullscreen
                    class="w-full h-full"
                    loading="lazy"
                    title="${escapeHTML(link.title)}"
                    onerror="handleVideoEmbedError('${uniqueId}', '${escapeHTML(watchUrl)}')"
                    onload="handleVideoEmbedLoad('${uniqueId}')">
                </iframe>
                <div class="video-brand-watermark"><img src="gcsemate%20new.png" alt="GCSEMate" class="h-6 w-auto opacity-80"></div>
                <div class="video-brand-controls">
                    <button onclick="handleVideoWrapperFullscreen(this)" class="px-2 py-1 rounded-md bg-white/20 hover:bg-white/30 text-white border border-white/20 transition-colors" aria-label="Fullscreen">
                        <i class="fas fa-expand text-sm"></i>
                    </button>
                </div>
                <div id="video-fallback-${uniqueId}" class="hidden absolute inset-0 bg-gray-900/95 flex flex-col items-center justify-center p-4 rounded-lg z-20">
                    <div class="text-center text-white">
                        <i class="fas fa-exclamation-triangle text-4xl mb-4 text-yellow-400"></i>
                        <p class="text-lg font-semibold mb-2">Video cannot be embedded</p>
                        <p class="text-sm text-gray-300 mb-4">Click below to watch on YouTube</p>
                        <a href="${escapeHTML(watchUrl)}" target="_blank" rel="noopener noreferrer" class="inline-flex items-center gap-2 px-6 py-3 bg-red-600 hover:bg-red-700 text-white font-semibold rounded-lg transition-colors shadow-lg">
                            <i class="fab fa-youtube text-xl"></i>
                            Watch on YouTube
                        </a>
                    </div>
                </div>
            </div>
        </div>
        <div class="p-4">
            <div class="flex items-start justify-between gap-2 mb-2">
                <h4 class="font-bold text-lg text-gray-800 flex-1">${escapeHTML(link.title)}</h4>
            </div>
            <div class="flex items-center justify-between">
                <div class="flex items-center gap-2 text-sm text-gray-500">
                    <i class="fas ${typeIcon} text-red-600"></i>
                    <span>${typeLabel}</span>
                </div>
                <a href="${escapeHTML(watchUrl)}" target="_blank" rel="noopener noreferrer" class="text-xs text-blue-600 hover:text-blue-700 flex items-center gap-1" data-tooltip="Open in YouTube">
                    <i class="fab fa-youtube"></i>
                    <span>Open</span>
                </a>
            </div>
        </div>
    `;
    
    return card;
}

function createLinkCard(id, link) {
    const card = document.createElement('div');
    card.className = 'bg-white/70 backdrop-blur-lg rounded-xl shadow-md border border-white/30 p-5 hover:shadow-lg transition-all duration-300 hover:scale-[1.02] group';
    
    const removeBtn = currentUser.role === 'admin' ? 
        `<button onclick="handleRemoveLink('${id}')" class="absolute top-3 right-3 opacity-0 group-hover:opacity-100 text-red-500 hover:text-red-700 p-2 rounded-full hover:bg-red-50 transition-all" data-tooltip="Remove link" aria-label="Remove link">
            <i class="fas fa-trash text-sm"></i>
        </button>` : '';
    
    // Extract domain for display
    let domain = '';
    try {
        const urlObj = new URL(link.url);
        domain = urlObj.hostname.replace('www.', '');
    } catch (e) {
        domain = link.url;
    }
    
    card.innerHTML = `
        <div class="relative">
            ${removeBtn}
            <a href="${escapeHTML(link.url)}" target="_blank" rel="noopener noreferrer" class="block">
                <div class="flex items-start gap-4">
                    <div class="flex-shrink-0 w-12 h-12 bg-gradient-to-br from-blue-500 to-blue-600 rounded-lg flex items-center justify-center text-white shadow-md group-hover:shadow-lg transition-shadow">
                        <i class="fas fa-external-link-alt text-xl"></i>
                    </div>
                    <div class="flex-1 min-w-0">
                        <h4 class="font-bold text-lg text-gray-800 mb-1 group-hover:text-blue-600 transition-colors truncate">${escapeHTML(link.title)}</h4>
                        <p class="text-sm text-gray-500 truncate" data-tooltip="${escapeHTML(link.url)}">${escapeHTML(domain)}</p>
                    </div>
                    <div class="flex-shrink-0 text-gray-400 group-hover:text-blue-600 transition-colors">
                        <i class="fas fa-chevron-right"></i>
                    </div>
                </div>
            </a>
        </div>
    `;
    
    return card;
}

// Setup search and filter handlers
document.addEventListener('DOMContentLoaded', () => {
    const searchInput = document.getElementById('links-search-input');
    const filterSelect = document.getElementById('links-filter-type');
    
    if (searchInput) {
        searchInput.addEventListener('input', () => {
            if (linksSearchDebounce) clearTimeout(linksSearchDebounce);
            linksSearchDebounce = setTimeout(() => {
                filterAndRenderLinks();
            }, 300);
        });
    }
    
    if (filterSelect) {
        filterSelect.addEventListener('change', () => {
            filterAndRenderLinks();
        });
    }
});
// =================================================================================
// CALENDAR LOGIC
// =================================================================================
let calendarUserEvents = {};
let calendarGlobalEvents = {};
function renderCalendar(userEvents, globalEvents) {
    if (userEvents) calendarUserEvents = userEvents;
    if (globalEvents) calendarGlobalEvents = globalEvents;
    const calendarGrid = document.getElementById('calendar-grid');
    const monthYearHeader = document.getElementById('month-year-header');
    const yearSelect = document.getElementById('calendar-year-select');
    if (!calendarGrid || !monthYearHeader) return;
    calendarGrid.innerHTML = '';
    const month = currentDate.getMonth();
    const year = currentDate.getFullYear();
    monthYearHeader.textContent = `${currentDate.toLocaleString('en-GB', { month: 'long', timeZone: UK_TZ })} ${year}`;
    // Populate year dropdown with wider range
    if (yearSelect && yearSelect.childElementCount === 0) {
        const base = new Date().getFullYear();
        // Include years from 2020 to 10 years in the future
        for (let y = 2020; y <= base + 10; y++) {
            const opt = document.createElement('option');
            opt.value = String(y);
            opt.textContent = String(y);
            yearSelect.appendChild(opt);
        }
        yearSelect.value = String(year);
        yearSelect.addEventListener('change', () => {
            const newYear = parseInt(yearSelect.value, 10);
            currentDate.setFullYear(newYear);
            renderCalendar(calendarUserEvents, calendarGlobalEvents);
            // Scroll calendar page to top to prevent footer covering
            const calendarPage = document.getElementById('calendar-page');
            if (calendarPage) {
                calendarPage.scrollIntoView({ behavior: 'smooth', block: 'start' });
            }
        });
    } else if (yearSelect) {
        yearSelect.value = String(year);
    }
    
    const dayHeaders = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
    dayHeaders.forEach(day => {
        const dayEl = document.createElement('div');
        dayEl.className = 'text-center font-bold text-gray-700 text-xs sm:text-sm py-3 bg-gray-50/80 rounded-t-lg border-b-2 border-gray-200';
        dayEl.textContent = day;
        calendarGrid.appendChild(dayEl);
    });
    const firstDayOfMonth = new Date(year, month, 1).getDay();
    const daysInMonth = new Date(year, month + 1, 0).getDate();
    for (let i = 0; i < firstDayOfMonth; i++) {
        const emptyCell = document.createElement('div');
        emptyCell.className = 'min-h-[80px] bg-gray-50/30 border border-gray-100 rounded';
        calendarGrid.appendChild(emptyCell);
    }
    for (let day = 1; day <= daysInMonth; day++) {
        const dayEl = document.createElement('div');
        const dateKey = `${year}-${String(month + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
        dayEl.className = 'calendar-day min-h-[80px] p-2 bg-white border-2 border-gray-200 rounded-lg cursor-pointer hover:bg-blue-50/70 hover:border-blue-400 hover:shadow-md transition-all duration-200 flex flex-col relative';
        dayEl.dataset.date = dateKey;
        
        const dayNumber = document.createElement('div');
        dayNumber.className = 'text-sm font-semibold text-gray-800 mb-1';
        dayNumber.textContent = day;
        dayEl.appendChild(dayNumber);
        
        const today = new Date();
        if (day === today.getDate() && month === today.getMonth() && year === today.getFullYear()) {
            dayEl.classList.add('today', 'ring-2', 'ring-blue-500', 'ring-offset-1', 'bg-blue-50');
            dayNumber.classList.add('text-blue-700');
        }
        
        const filterVal = document.getElementById('calendar-category-filter')?.value || 'all';
        
        // Get events for this day, including multi-day events that span this date
        const getEventsForDate = (eventsObj) => {
            const directEvents = eventsObj[dateKey] || [];
            const multiDayEvents = Object.entries(eventsObj).flatMap(([key, events]) => {
                return events.filter(ev => {
                    if (!ev.endDate || ev.endDate === ev.date) return false;
                    const start = new Date(ev.date + 'T00:00:00');
                    const end = new Date(ev.endDate + 'T00:00:00');
                    const current = new Date(dateKey + 'T00:00:00');
                    return current >= start && current <= end;
                });
            });
            return [...directEvents, ...multiDayEvents];
        };
        
        const userEventsForDay = getEventsForDate(calendarUserEvents);
        const globalEventsForDay = getEventsForDate(calendarGlobalEvents);
        
        const categoryMatches = (ev) => {
            if (filterVal === 'all') return true;
            const title = (ev.title||'').toLowerCase();
            const cat = (ev.category||'').toLowerCase();
            return title.includes(filterVal) || cat.includes(filterVal);
        };
        const userHas = userEventsForDay.some(categoryMatches);
        const globalHas = globalEventsForDay.some(categoryMatches);
        if (userHas || globalHas) {
            dayEl.classList.add('has-event');
            if (globalHas) dayEl.classList.add('has-global-event');
            
            // Create event indicators container
            const eventsContainer = document.createElement('div');
            eventsContainer.className = 'flex-1 flex flex-col gap-1 mt-1';
            
            // Show event titles (max 2-3 visible)
            const allEvents = [...userEventsForDay, ...globalEventsForDay].filter(categoryMatches);
            const visibleEvents = allEvents.slice(0, 2);
            visibleEvents.forEach(event => {
                const eventDot = document.createElement('div');
                eventDot.className = 'text-xs px-1.5 py-0.5 rounded truncate text-white font-medium';
                
                // Determine color based on event type
                const isGlobal = globalEventsForDay.includes(event);
                const category = (event.category || '').toLowerCase();
                
                if (event.color && /^#([0-9a-f]{3}){1,2}$/i.test(event.color)) {
                    // Use custom color if set
                    eventDot.style.backgroundColor = event.color;
                } else if (isGlobal) {
                    // Blue for global events
                    eventDot.className += ' bg-blue-500';
                } else if (category === 'exam' || category.includes('exam')) {
                    // Red for exam events
                    eventDot.className += ' bg-red-500';
                } else if (category === 'homework' || category === 'hw' || category.includes('homework')) {
                    // Purple for homework events
                    eventDot.className += ' bg-purple-500';
                } else {
                    // Default to blue for user events
                    eventDot.className += ' bg-blue-500';
                }
                
                eventDot.textContent = event.title || 'Event';
                eventDot.setAttribute('data-tooltip', `${event.title || 'Event'}${event.description ? ': ' + event.description : ''}`);
                eventsContainer.appendChild(eventDot);
            });
            
            if (allEvents.length > 2) {
                const moreEvents = document.createElement('div');
                moreEvents.className = 'text-xs text-gray-500 font-semibold mt-auto';
                moreEvents.textContent = `+${allEvents.length - 2} more`;
                eventsContainer.appendChild(moreEvents);
            }
            
            dayEl.appendChild(eventsContainer);
        }
        // Month grid drag target
        dayEl.ondragover = (ev)=> ev.preventDefault();
        dayEl.ondrop = (ev)=> onMonthDrop(ev, dateKey);
        
        dayEl.addEventListener('click', () => openEventModal(dateKey));
        calendarGrid.appendChild(dayEl);
    }
    updateCalendarInsights();
    renderDashboardExamCalendarCard();
    renderCalendarAgenda();
    updateCountdownBanner();
}

function updateCalendarInsights() {
    const upcomingEl = document.getElementById('calendar-upcoming-count');
    const importantEl = document.getElementById('calendar-important-count');
    const nextEventEl = document.getElementById('calendar-next-event');
    const nextEventMetaEl = document.getElementById('calendar-next-event-meta');

    const events = [];
    [calendarUserEvents, calendarGlobalEvents].forEach((eventMap, mapIndex) => {
        Object.entries(eventMap || {}).forEach(([fallbackDate, items]) => {
            (items || []).forEach((event) => {
                const dateText = event.date || fallbackDate;
                const startDate = new Date(`${dateText}T00:00:00`);
                events.push({
                    ...event,
                    isGlobal: mapIndex === 1,
                    startDate,
                    categoryText: `${event.category || ''} ${event.title || ''}`.toLowerCase()
                });
            });
        });
    });

    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const soon = new Date(today);
    soon.setDate(soon.getDate() + 14);
    const currentMonthKey = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`;

    const upcoming = events.filter(event => event.startDate >= today && event.startDate <= soon);
    const important = events.filter(event => {
        const monthKey = `${event.startDate.getFullYear()}-${String(event.startDate.getMonth() + 1).padStart(2, '0')}`;
        return monthKey === currentMonthKey && /(exam|homework|due)/i.test(event.categoryText || '');
    });
    const nextEvent = [...events].filter(event => event.startDate >= today).sort((a, b) => a.startDate - b.startDate)[0];

    if (upcomingEl) upcomingEl.textContent = String(upcoming.length);
    if (importantEl) importantEl.textContent = String(important.length);
    if (nextEventEl) nextEventEl.textContent = nextEvent ? (nextEvent.title || 'Untitled event') : 'No events yet';
    if (nextEventMetaEl) {
        nextEventMetaEl.textContent = nextEvent
            ? `${nextEvent.startDate.toLocaleDateString('en-GB', { weekday: 'short', day: 'numeric', month: 'short' })} • ${nextEvent.category || (nextEvent.isGlobal ? 'Global event' : 'Personal event')}`
            : 'Add a revision event or deadline to populate this space.';
    }
}

function getUpcomingExamEvents(limit = 3) {
    const events = [];
    const seen = new Set();
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    [calendarUserEvents, calendarGlobalEvents].forEach((eventMap, mapIndex) => {
        Object.entries(eventMap || {}).forEach(([fallbackDate, items]) => {
            (items || []).forEach((event) => {
                const dateText = event.date || fallbackDate;
                const dateObj = new Date(`${dateText}T00:00:00`);
                if (Number.isNaN(dateObj.getTime()) || dateObj < today) return;

                const categoryText = String(event.category || '').toLowerCase();
                const titleText = String(event.title || '').toLowerCase();
                const isExam = categoryText.includes('exam') || /\b(exam|mock|paper|assessment|test)\b/.test(titleText);
                if (!isExam) return;

                const sourcePrefix = mapIndex === 1 ? 'global' : 'user';
                const baseId = String(event.id || `${dateText}_${event.title || 'exam'}`).trim();
                const eventKey = `${sourcePrefix}:${baseId}:${dateText}`;
                if (seen.has(eventKey)) return;
                seen.add(eventKey);

                events.push({
                    ...event,
                    eventKey,
                    isGlobal: mapIndex === 1,
                    dateObj,
                    dateText
                });
            });
        });
    });

    return events.sort((a, b) => a.dateObj - b.dateObj).slice(0, Math.max(1, limit));
}

function renderDashboardExamCalendarCard() {
    const titleEl = document.getElementById('dashboard-next-exam-title');
    const metaEl = document.getElementById('dashboard-next-exam-meta');
    const listEl = document.getElementById('dashboard-next-exam-list');
    const pinEl = document.getElementById('dashboard-next-exam-pin');
    if (!titleEl || !metaEl || !listEl) return;

    const upcoming = getUpcomingExamEvents(12);
    const pinnedKey = getPinnedDashboardExamId();
    const ordered = [...upcoming];
    const pinnedIndex = pinnedKey ? ordered.findIndex((event) => event.eventKey === pinnedKey) : -1;

    if (pinnedKey && pinnedIndex === -1) {
        setPinnedDashboardExamId('');
    }

    if (pinnedIndex > 0) {
        const [pinnedEvent] = ordered.splice(pinnedIndex, 1);
        ordered.unshift(pinnedEvent);
    }

    const primary = ordered[0];
    const secondary = ordered.slice(1, 3);

    if (!primary) {
        titleEl.textContent = 'No upcoming exams yet';
        metaEl.textContent = 'Add exam events in Calendar to see your next deadline here.';
        listEl.innerHTML = '<p class="dashboard-exam-empty">No additional exams queued.</p>';
        if (pinEl) {
            pinEl.classList.add('hidden');
            pinEl.setAttribute('aria-pressed', 'false');
            pinEl.onclick = null;
        }
        return;
    }

    const now = new Date();
    now.setHours(0, 0, 0, 0);
    const days = Math.max(0, Math.ceil((primary.dateObj.getTime() - now.getTime()) / (1000 * 60 * 60 * 24)));
    const dayText = days === 0 ? 'Today' : `${days} day${days === 1 ? '' : 's'} away`;
    const isPrimaryPinned = getPinnedDashboardExamId() === primary.eventKey;

    titleEl.textContent = primary.title || 'Upcoming exam';
    metaEl.textContent = `${primary.dateObj.toLocaleDateString('en-GB', { weekday: 'short', day: 'numeric', month: 'short' })} • ${dayText}${primary.isGlobal ? ' • Global' : ''}${isPrimaryPinned ? ' • Pinned' : ''}`;

    if (pinEl) {
        pinEl.classList.remove('hidden');
        pinEl.classList.toggle('is-pinned', isPrimaryPinned);
        pinEl.setAttribute('aria-pressed', isPrimaryPinned ? 'true' : 'false');
        pinEl.textContent = isPrimaryPinned ? 'Pinned to dashboard' : 'Pin this exam';
        pinEl.onclick = () => toggleDashboardExamPinById(primary.eventKey);
    }

    if (!secondary.length) {
        listEl.innerHTML = '<p class="dashboard-exam-empty">No additional exams queued.</p>';
        return;
    }

    listEl.innerHTML = secondary.map((event) => {
        const diff = Math.max(0, Math.ceil((event.dateObj.getTime() - now.getTime()) / (1000 * 60 * 60 * 24)));
        const isPinned = getPinnedDashboardExamId() === event.eventKey;
        return `<div class="dashboard-exam-pill ${isPinned ? 'is-pinned' : ''}">
            <button type="button" class="dashboard-exam-pill-open" onclick="showPage('calendar-page')">
                <span class="dashboard-exam-pill-title">${escapeHTML(event.title || 'Exam')}</span>
                <span class="dashboard-exam-pill-meta">${event.dateObj.toLocaleDateString('en-GB', { day: 'numeric', month: 'short' })} • ${diff === 0 ? 'Today' : `${diff}d`}${isPinned ? ' • Pinned' : ''}</span>
            </button>
            <button type="button" class="dashboard-exam-pill-pin ${isPinned ? 'is-pinned' : ''}" onclick="event.stopPropagation(); toggleDashboardExamPinById('${escapeJS(event.eventKey)}')">${isPinned ? 'Pinned' : 'Pin'}</button>
        </div>`;
    }).join('');
}

// New: Support multiple view modes for calendar
const calendarViewSelect = document.getElementById('calendar-view-mode');
if (calendarViewSelect) {
    calendarViewSelect.addEventListener('change', () => {
        recordUserInteraction('calendar_view_change', { target: calendarViewSelect.value, important: true });
        renderCalendar(calendarUserEvents, calendarGlobalEvents);
        // Scroll calendar page to top to prevent footer covering
        const calendarPage = document.getElementById('calendar-page');
        if (calendarPage) {
            calendarPage.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }
    });
}
const calendarFilterSelect = document.getElementById('calendar-category-filter');
if (calendarFilterSelect) {
    calendarFilterSelect.addEventListener('change', () => {
        recordUserInteraction('calendar_filter_change', { target: calendarFilterSelect.value, important: true });
        renderCalendar(calendarUserEvents, calendarGlobalEvents);
        // Scroll calendar page to top to prevent footer covering
        const calendarPage = document.getElementById('calendar-page');
        if (calendarPage) {
            calendarPage.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }
    });
}
function renderCalendarAgenda() {
    const view = document.getElementById('calendar-view-mode')?.value || 'month';
    const grid = document.getElementById('calendar-grid');
    const agenda = document.getElementById('calendar-agenda');
    if (!grid || !agenda) return;
    if (view === 'agenda' || view === 'week') {
        grid.classList.add('hidden');
        agenda.classList.remove('hidden');
        const start = new Date(currentDate);
        if (view === 'week') {
            // set to first day of current week
            const day = start.getDay(); start.setDate(start.getDate() - day);
        } else {
            // agenda for next 30 days
        }
        const rangeDays = view === 'week' ? 7 : 30;
        const items = [];
        for (let i=0;i<rangeDays;i++) {
            const d = new Date(start); d.setDate(start.getDate()+i);
            const key = `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
            const globalEvents = (calendarGlobalEvents[key]||[]).map(e => ({ ...e, isGlobal: true }));
            const userEvents = (calendarUserEvents[key]||[]).map(e => ({ ...e, isGlobal: false }));
            const events = [...globalEvents, ...userEvents];
            events.forEach(e => items.push({ date: new Date(d), ...e }));
        }
        items.sort((a,b)=> a.date - b.date);
        agenda.innerHTML = items.length ? items.map(e => {
            // Determine color based on event type
            let eventColor = e.color;
            if (!eventColor || !/^#([0-9a-f]{3}){1,2}$/i.test(eventColor)) {
                const category = (e.category || '').toLowerCase();
                if (e.isGlobal) {
                    eventColor = 'rgb(var(--accent-500))';
                } else if (category === 'exam' || category.includes('exam')) {
                    eventColor = '#EF4444'; // Red for exam
                } else if (category === 'homework' || category === 'hw' || category.includes('homework')) {
                    eventColor = '#A855F7'; // Purple for homework
                } else {
                    eventColor = 'rgb(var(--accent-500))';
                }
            }
            return `
            <div class="calendar-agenda-item flex items-start gap-3 py-3 px-4" draggable="true" ondragstart="onAgendaDragStart(event, '${e.id||''}', '${e.date.toISOString()}')" ondrop="onAgendaDrop(event, '${e.id||''}')" ondragover="event.preventDefault()">
                <div class="w-28 text-sm text-gray-600">${e.date.toLocaleDateString('en-GB')}</div>
                <div class="flex-1">
                    <div class="font-semibold text-gray-800 flex items-center gap-2">
                        <span class="inline-block w-2.5 h-2.5 rounded" style="background:${eventColor}"></span>
                        <span>${e.title||'Event'}</span>
                        ${e.category ? `<span class=\"text-xs px-2 py-0.5 rounded bg-gray-100 text-gray-700\">${e.category}</span>` : ''}
                    </div>
                    ${e.description ? `<div class="text-sm text-gray-600">${e.description}</div>` : ''}
                </div>
                <div class="flex items-center gap-2">
                    <span class="text-xs px-2 py-1 rounded bg-gray-100 text-gray-700">Drag to reschedule</span>
                    ${e.enableCountdown ? '<span class="text-xs px-2 py-1 rounded bg-yellow-100 text-yellow-800">Countdown</span>' : ''}
                </div>
            </div>
        `;
        }).join('') : '<div class="text-center text-gray-500 py-6">No events</div>';
    } else {
        agenda.classList.add('hidden');
        grid.classList.remove('hidden');
    }
}

// Drag-to-reschedule handlers (agenda/week)
function onAgendaDragStart(ev, eventId, isoDate) {
    ev.dataTransfer.setData('text/plain', JSON.stringify({ eventId, isoDate }));
}
async function onMonthDrop(ev, newDateKey) {
    try {
        const payload = JSON.parse(ev.dataTransfer.getData('text/plain'));
        if (!payload || !payload.eventId) return;
        await rescheduleEvent(payload.eventId, newDateKey);
        renderCalendar(calendarUserEvents, calendarGlobalEvents);
        showToast('Event rescheduled', 'success');
    } catch (_) {}
}
async function onAgendaDrop(ev, eventId) {
    try {
        const payload = JSON.parse(ev.dataTransfer.getData('text/plain'));
        if (!payload || !payload.isoDate) return;
        const newDate = new Date(payload.isoDate);
        const delta = (ev.offsetY > 20) ? 1 : -1;
        newDate.setDate(newDate.getDate() + delta);
        const newKey = `${newDate.getFullYear()}-${String(newDate.getMonth()+1).padStart(2,'0')}-${String(newDate.getDate()).padStart(2,'0')}`;
        await rescheduleEvent(eventId || payload.eventId, newKey);
        renderCalendar(calendarUserEvents, calendarGlobalEvents);
        showToast('Event rescheduled', 'success');
    } catch (_) {}
}
async function rescheduleEvent(eventId, newDateKey) {
    if (!eventId) return;
    for (const [dateKey, list] of Object.entries(calendarUserEvents)) {
        const idx = (list||[]).findIndex(e => e.id === eventId);
        if (idx >= 0) {
            const e = list[idx];
            await db.collection('users').doc(currentUser.uid).collection('events').doc(e.id).update({ date: newDateKey });
            calendarUserEvents[dateKey].splice(idx,1);
            (calendarUserEvents[newDateKey] = calendarUserEvents[newDateKey] || []).push({ ...e, date: newDateKey });
            return;
        }
    }
    if (currentUser.role === 'admin') {
        for (const [dateKey, list] of Object.entries(calendarGlobalEvents)) {
            const idx = (list||[]).findIndex(e => e.id === eventId);
            if (idx >= 0) {
                const e = list[idx];
                await db.collection('globalEvents').doc(e.id).update({ date: newDateKey });
                calendarGlobalEvents[dateKey].splice(idx,1);
                (calendarGlobalEvents[newDateKey] = calendarGlobalEvents[newDateKey] || []).push({ ...e, date: newDateKey });
                return;
            }
        }
    }
}

// =================================================================================
// BLOG LOGIC
// =================================================================================
function setBlogStatusMessage(message) {
    const el = document.getElementById('blog-status-message');
    if (!el) return;
    if (!message) {
        el.textContent = '';
        el.classList.add('hidden');
        return;
    }
    el.textContent = message;
    el.classList.remove('hidden');
}

function normalizeBlogToken(value) {
    return String(value || '').trim().toLowerCase();
}

function parseBlogTags(value) {
    if (Array.isArray(value)) {
        return [...new Set(value.map(tag => String(tag || '').trim()).filter(Boolean))];
    }
    return [...new Set(String(value || '')
        .split(',')
        .map(tag => tag.trim())
        .filter(Boolean))];
}

function getBlogPostDate(post) {
    const direct = post?.createdAt?.toDate ? post.createdAt.toDate() : new Date(post?.createdAt || post?.updatedAt || Date.now());
    return Number.isNaN(direct.getTime()) ? new Date() : direct;
}

function getBlogPostSearchBlob(post) {
    return [
        post?.title,
        post?.subject,
        ...(Array.isArray(post?.tags) ? post.tags : []),
        String(post?.content || '').replace(/<[^>]+>/g, ' ')
    ].join(' ').toLowerCase();
}

function getProcessedBlogPosts(posts = []) {
    const processed = posts.map(post => ({
        ...post,
        subject: String(post?.subject || '').trim(),
        tags: parseBlogTags(post?.tags),
        safeDate: getBlogPostDate(post)
    }));

    const query = normalizeBlogToken(BLOG_VIEW_STATE.search);
    const tagQuery = normalizeBlogToken(BLOG_VIEW_STATE.tag);
    const subjectQuery = normalizeBlogToken(BLOG_VIEW_STATE.subject);

    const filtered = processed.filter(post => {
        const blob = getBlogPostSearchBlob(post);
        const tags = post.tags.map(normalizeBlogToken);
        const subject = normalizeBlogToken(post.subject);
        const matchesSearch = !query || blob.includes(query);
        const matchesTag = !tagQuery || tags.some(tag => tag.includes(tagQuery));
        const matchesSubject = !subjectQuery || subjectQuery === 'all' || subject === subjectQuery;
        return matchesSearch && matchesTag && matchesSubject;
    });

    const sorter = BLOG_VIEW_STATE.sort;
    filtered.sort((a, b) => {
        if (sorter === 'title') return (a.title || '').localeCompare(b.title || '');
        if (sorter === 'oldest') return a.safeDate - b.safeDate;
        return b.safeDate - a.safeDate;
    });

    return { processed, filtered };
}

function updateBlogFilterControls(posts = []) {
    const subjectSelect = document.getElementById('blog-subject-filter');
    if (!subjectSelect) return;

    const current = BLOG_VIEW_STATE.subject || 'all';
    const subjects = [...new Set(posts.map(post => String(post?.subject || '').trim()).filter(Boolean))]
        .sort((a, b) => a.localeCompare(b));

    subjectSelect.innerHTML = `<option value="all">All Subjects</option>${subjects.map(subject => `<option value="${escapeHTML(subject)}">${escapeHTML(subject)}</option>`).join('')}`;
    subjectSelect.value = subjects.some(subject => normalizeBlogToken(subject) === normalizeBlogToken(current)) ? current : 'all';
    BLOG_VIEW_STATE.subject = subjectSelect.value;
}

function renderBlogFeaturedPost(posts = []) {
    const featuredEl = document.getElementById('blog-featured-post');
    const totalPostsEl = document.getElementById('blog-total-posts');
    const totalSubjectsEl = document.getElementById('blog-total-subjects');
    const latestDateEl = document.getElementById('blog-latest-date');
    if (!featuredEl) return;

    const subjectCount = new Set(posts.map(post => normalizeBlogToken(post.subject)).filter(Boolean)).size;
    const latestPost = [...posts].sort((a, b) => b.safeDate - a.safeDate)[0];
    if (totalPostsEl) totalPostsEl.textContent = String(posts.length);
    if (totalSubjectsEl) totalSubjectsEl.textContent = String(subjectCount);
    if (latestDateEl) latestDateEl.textContent = latestPost ? latestPost.safeDate.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }) : 'Not yet';

    const featuredPost = posts[0] || latestPost;
    if (!featuredPost) {
        featuredEl.innerHTML = `
            <div class="blog-featured-card">
                <div>
                    <span class="blog-featured-pill">Coming soon</span>
                    <h3 class="mt-4 text-2xl font-black">Fresh study tips will appear here.</h3>
                    <p class="mt-3 text-sm text-blue-100/85">As soon as the first post is published, this featured panel will spotlight it automatically.</p>
                </div>
            </div>`;
        return;
    }

    const featuredSummary = escapeHTML(String(featuredPost.content || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 220));
    const tags = featuredPost.tags.slice(0, 3).map(tag => `<span class="blog-featured-pill">#${escapeHTML(tag)}</span>`).join('');
    featuredEl.innerHTML = `
        <article class="blog-featured-card">
            <div>
                <div class="flex flex-wrap items-center gap-2">
                    <span class="blog-featured-pill"><i class="fas fa-sparkles"></i> Featured post</span>
                    ${featuredPost.subject ? `<span class="blog-featured-pill">${escapeHTML(featuredPost.subject)}</span>` : ''}
                </div>
                <h3 class="mt-4 text-2xl font-black leading-tight">${escapeHTML(featuredPost.title || 'Untitled post')}</h3>
                <p class="mt-3 text-sm text-blue-100/90">${featuredSummary || 'Open this post to read the latest revision guidance and GCSEMate updates.'}</p>
                <div class="mt-4 flex flex-wrap gap-2">${tags}</div>
            </div>
            <div class="mt-6 flex items-center justify-between gap-3 flex-wrap">
                <div class="text-sm text-blue-100/80">Updated ${featuredPost.safeDate.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' })}</div>
                <button class="inline-flex items-center gap-2 rounded-xl bg-white text-slate-900 px-4 py-2 font-bold hover:bg-blue-50 transition-colors" onclick="showBlogPostViewer('${escapeJS(featuredPost.id)}')">
                    Read featured post
                    <i class="fas fa-arrow-right"></i>
                </button>
            </div>
        </article>`;
}

function renderBlogResultsSummary(visibleCount, totalCount) {
    const summaryEl = document.getElementById('blog-results-summary');
    if (!summaryEl) return;
    const filtersActive = !!(BLOG_VIEW_STATE.search || BLOG_VIEW_STATE.tag || (BLOG_VIEW_STATE.subject && BLOG_VIEW_STATE.subject !== 'all'));
    if (!totalCount) {
        summaryEl.textContent = 'No posts yet';
        return;
    }
    if (!filtersActive) {
        summaryEl.textContent = `${visibleCount} post${visibleCount === 1 ? '' : 's'} available`;
        return;
    }
    summaryEl.textContent = `${visibleCount} of ${totalCount} post${totalCount === 1 ? '' : 's'} match your filters`;
}

function setupBlogFilters() {
    if (window.__gcsemateBlogFiltersBound) return;
    window.__gcsemateBlogFiltersBound = true;

    const searchInput = document.getElementById('blog-search');
    const tagInput = document.getElementById('blog-tag-filter');
    const subjectSelect = document.getElementById('blog-subject-filter');
    const sortSelect = document.getElementById('blog-sort');
    const clearBtn = document.getElementById('blog-clear-filters');

    if (searchInput) {
        searchInput.addEventListener('input', () => {
            BLOG_VIEW_STATE.search = searchInput.value.trim();
            renderBlogPage(allBlogPosts);
        });
    }
    if (tagInput) {
        tagInput.addEventListener('input', () => {
            BLOG_VIEW_STATE.tag = tagInput.value.trim();
            renderBlogPage(allBlogPosts);
        });
    }
    if (subjectSelect) {
        subjectSelect.addEventListener('change', () => {
            BLOG_VIEW_STATE.subject = subjectSelect.value;
            renderBlogPage(allBlogPosts);
        });
    }
    if (sortSelect) {
        sortSelect.addEventListener('change', () => {
            BLOG_VIEW_STATE.sort = sortSelect.value;
            renderBlogPage(allBlogPosts);
        });
    }
    if (clearBtn) {
        clearBtn.addEventListener('click', () => {
            BLOG_VIEW_STATE.search = '';
            BLOG_VIEW_STATE.tag = '';
            BLOG_VIEW_STATE.subject = 'all';
            BLOG_VIEW_STATE.sort = 'newest';
            if (searchInput) searchInput.value = '';
            if (tagInput) tagInput.value = '';
            if (subjectSelect) subjectSelect.value = 'all';
            if (sortSelect) sortSelect.value = 'newest';
            renderBlogPage(allBlogPosts);
        });
    }
}

function renderBlogPage(posts) {
    const grid = document.getElementById('blog-post-grid');
    if (!grid) return;
    setupBlogFilters();
    setBlogStatusMessage('');
    grid.innerHTML = '';
    const { processed, filtered } = getProcessedBlogPosts(posts || []);
    updateBlogFilterControls(processed);
    renderBlogFeaturedPost(filtered.length > 0 ? filtered : processed);
    renderBlogResultsSummary(filtered.length, processed.length);

    // Inject page-level JSON-LD for Blog with BlogPosting list
    try {
        const ldId = 'jsonld-blog';
        const existing = document.getElementById(ldId);
        const blogLd = {
            "@context": "https://schema.org",
            "@type": "Blog",
            "name": "GCSEMate Blog",
            "url": "https://gcsemate.com/blog",
            "blogPost": (processed||[]).slice(0, 25).map(p => ({
                "@type": "BlogPosting",
                "headline": p.title,
                "image": p.image || undefined,
                "author": { "@type": "Person", "name": p.authorName || 'GCSEMate' },
                "datePublished": p.createdAt?.toDate ? p.createdAt.toDate().toISOString() : undefined,
                "dateModified": p.updatedAt?.toDate ? p.updatedAt.toDate().toISOString() : undefined,
                "url": `https://gcsemate.com/blog#${p.id}`
            }))
        };
        const node = document.createElement('script');
        node.type = 'application/ld+json';
        node.id = ldId;
        node.textContent = JSON.stringify(blogLd);
        if (existing) { existing.replaceWith(node); } else { document.head.appendChild(node); }
    } catch(_){}

    if (!processed.length) {
        grid.innerHTML = `<div class="col-span-full blog-empty-state"><div class="mx-auto flex h-14 w-14 items-center justify-center rounded-2xl bg-blue-50 text-blue-600"><i class="fas fa-feather-pointed text-xl"></i></div><h3 class="mt-4 text-lg font-bold text-gray-800">No blog posts yet</h3><p class="mt-2 text-sm text-gray-500">Check back later for new revision tips, release notes, and study updates.</p></div>`;
        return;
    }

    if (!filtered.length) {
        grid.innerHTML = `<div class="col-span-full blog-empty-state"><div class="mx-auto flex h-14 w-14 items-center justify-center rounded-2xl bg-amber-50 text-amber-600"><i class="fas fa-filter-circle-xmark text-xl"></i></div><h3 class="mt-4 text-lg font-bold text-gray-800">No posts match those filters</h3><p class="mt-2 text-sm text-gray-500">Try a different keyword, remove the tag filter, or reset back to all subjects.</p></div>`;
        return;
    }

    filtered.forEach(post => {
        const card = document.createElement('div');
        card.className = 'blog-card flex flex-col overflow-hidden';
        const contentPreview = escapeHTML((post.content || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().substring(0, 160));
        const postDate = post.safeDate.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });
        let adminButtons = '';
        if(currentUser && currentUser.role === 'admin') {
            adminButtons = `
                <div class="absolute top-2 right-2 flex gap-1">
                    <button onclick="event.stopPropagation(); editBlogPost('${escapeJS(post.id)}')" class="p-1.5 bg-blue-500/80 text-white rounded-full hover:bg-blue-600 transition-colors" data-tooltip="Edit Post">
                        <svg xmlns="http://www.w3.org/2000/svg" class="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.536L16.732 3.732z" /></svg>
                    </button>
                    <button onclick="event.stopPropagation(); deleteBlogPost('${escapeJS(post.id)}')" class="p-1.5 bg-red-500/80 text-white rounded-full hover:bg-red-600 transition-colors" data-tooltip="Delete Post">
                        <svg xmlns="http://www.w3.org/2000/svg" class="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                    </button>
                </div>
            `;
        }
        const tags = post.tags.slice(0, 3).map(tag => `<span class="blog-tag-chip">#${escapeHTML(tag)}</span>`).join('');
        const safeImage = escapeHTML(post.image || BLOG_DEFAULT_IMAGE);
        card.innerHTML = `
            <div class="relative cursor-pointer" onclick="showBlogPostViewer('${escapeJS(post.id)}')">
                <img src="${safeImage}" alt="${escapeHTML(post.title || 'Blog post')}" class="blog-card-image" loading="lazy" decoding="async">
                <div class="p-6 flex-grow flex flex-col">
                    <div class="blog-meta-row mb-3">
                        <div class="flex flex-wrap items-center gap-2">
                            ${post.subject ? `<span class="blog-tag-chip">${escapeHTML(post.subject)}</span>` : '<span class="blog-tag-chip">General</span>'}
                            ${tags}
                        </div>
                        <span class="comment-badge text-xs bg-blue-100 text-blue-700 font-semibold px-2 py-1 rounded-full whitespace-nowrap" data-post-id="${post.id}">0 comments</span>
                    </div>
                    <h3 class="text-xl font-bold text-gray-900 leading-tight">${escapeHTML(post.title || 'Untitled post')}</h3>
                    <p class="blog-card-summary text-gray-600 text-sm flex-grow mt-3">${contentPreview || 'Open this post to read the full revision note and update.'}${contentPreview ? '…' : ''}</p>
                    <div class="blog-meta-row mt-5">
                        <p class="text-xs text-gray-500">${postDate}</p>
                        <p class="text-xs font-semibold text-gray-500">${escapeHTML(post.authorName || 'GCSEMate')}</p>
                    </div>
                </div>
                ${adminButtons}
            </div>
        `;
        grid.appendChild(card);
    });
    // Fetch comment counts (lightweight) and animate badges
    try {
        if (isFirestoreAvailable()) {
            filtered.forEach(async (p, i) => {
                try {
                    const cached = BLOG_COMMENT_COUNTS.get(p.id);
                    const badge = grid.querySelector(`.comment-badge[data-post-id="${p.id}"]`);
                    if (Number.isFinite(cached)) {
                        if (badge) badge.textContent = cached === 1 ? '1 comment' : `${cached} comments`;
                        return;
                    }
                    const snap = await db.collection('blogPosts').doc(p.id).collection('comments').get();
                    const n = snap.size || 0;
                    BLOG_COMMENT_COUNTS.set(p.id, n);
                    if (badge) {
                        badge.textContent = n === 1 ? '1 comment' : `${n} comments`;
                        badge.style.transform = 'scale(0.9)';
                        badge.style.transition = 'transform 200ms ease';
                        setTimeout(() => { badge.style.transform = 'scale(1)'; }, 20 + i * 15);
                    }
                } catch (error) {
                    BLOG_COMMENT_COUNTS.set(p.id, 0);
                    if (isDevelopment) console.warn('Comment count load failed', error);
                }
            });
        }
    } catch (_) {}
    initializeTooltips();
}

async function handleSaveBlogPost() {
    if (!isAdminUser()) return;
    if (!isFirestoreAvailable()) {
        const messageEl = document.getElementById('add-blog-post-message');
        const friendly = getFirebaseFriendlyMessage(getFirebaseBootstrapError(), 'Blog publishing is temporarily unavailable. Please try again shortly.');
        if (messageEl) {
            messageEl.textContent = friendly;
            messageEl.className = 'text-red-600 text-sm mt-2 h-4';
        }
        showToast(friendly, 'error');
        return;
    }
    
    const postId = document.getElementById('blog-post-id').value;
    const title = document.getElementById('blog-post-title').value.trim();
    const contentEl = document.getElementById('blog-post-content');
    const content = contentEl ? sanitizeHTML(contentEl.innerHTML.trim()) : '';
    const image = document.getElementById('blog-post-image').value.trim();
    const subject = document.getElementById('blog-post-subject').value.trim();
    const tags = parseBlogTags(document.getElementById('blog-post-tags').value.trim());
    const messageEl = document.getElementById('add-blog-post-message');
    if (!title || !content) {
        messageEl.textContent = "Title and content are required.";
        messageEl.className = 'text-red-600 text-sm mt-2 h-4';
        showToast('Title and content are required.', 'error');
        return;
    }
    // Extract Cloudinary image public IDs from content for cleanup tracking
    const imagePublicIds = extractCloudinaryImageIds(content);
    
    const postData = {
        title,
        content,
        image: image || null,
        subject: subject || null,
        tags,
        createdBy: currentUser.uid,
        authorId: currentUser.uid,
        authorName: currentUser.displayName || currentUser.email || 'GCSEMate',
        imagePublicIds,
        updatedAt: firebase.firestore.FieldValue.serverTimestamp(),
    };
    try {
        if (postId) { // Update existing post
            // Get old post to find images that were removed
            const oldPost = await db.collection('blogPosts').doc(postId).get();
            if (oldPost.exists) {
                const oldData = oldPost.data();
                const oldImageIds = oldData.imagePublicIds || [];
                // Find images that were removed
                const removedImageIds = oldImageIds.filter(id => !imagePublicIds.includes(id));
                // Delete removed images from Cloudinary
                for (const publicId of removedImageIds) {
                    await deleteCloudinaryImage(publicId);
                }
            }
            await db.collection('blogPosts').doc(postId).update(postData);
        } else { // Create new post
            postData.createdAt = firebase.firestore.FieldValue.serverTimestamp();
            await db.collection('blogPosts').add(postData);
        }
        resetBlogPostForm();
        messageEl.textContent = "Blog post saved successfully!";
        messageEl.className = 'text-green-600 text-sm mt-2 h-4';
        setTimeout(() => messageEl.textContent = '', 3000);
    } catch (error) {
        console.error("Error saving blog post:", error);
        const friendly = getFirebaseFriendlyMessage(error, 'Could not save blog post. Please try again.');
        messageEl.textContent = friendly;
        messageEl.className = 'text-red-600 text-sm mt-2 h-4';
        showToast(friendly, 'error');
    }
}
