// =================================================================================
// LESSONS LOGIC
// =================================================================================
function setLessonsStatusMessage(message) {
    const el = document.getElementById('lessons-status-message');
    if (!el) return;
    if (!message) {
        el.textContent = '';
        el.classList.add('hidden');
        return;
    }
    el.textContent = message;
    el.classList.remove('hidden');
}

function parseMultilineValues(value) {
    return [...new Set(String(value || '')
        .split(/\r?\n/)
        .map(item => item.trim())
        .filter(Boolean))];
}

function normalizeLessonNumber(value) {
    const n = Number(value);
    return Number.isFinite(n) ? n : null;
}

function getLessonPublishDate(lesson) {
    const candidate = lesson?.publishedAt?.toDate
        ? lesson.publishedAt.toDate()
        : (lesson?.publishDate?.toDate
            ? lesson.publishDate.toDate()
            : new Date(lesson?.publishDate || lesson?.publishedAt || lesson?.updatedAt || lesson?.createdAt || Date.now()));
    return Number.isNaN(candidate.getTime()) ? new Date() : candidate;
}

function getLessonStatus(lesson = {}) {
    const status = String(lesson.status || '').trim().toLowerCase();
    return status === 'draft' ? 'draft' : 'published';
}

function canUserReadLesson(lesson = {}) {
    if (isAdminUser()) return true;
    return getLessonStatus(lesson) === 'published';
}

function normalizeLesson(lesson = {}) {
    return {
        ...lesson,
        status: getLessonStatus(lesson),
        subject: String(lesson.subject || '').trim(),
        topic: String(lesson.topic || '').trim(),
        subtopic: String(lesson.subtopic || '').trim(),
        category: String(lesson.category || '').trim(),
        title: String(lesson.title || '').trim(),
        summary: String(lesson.summary || '').trim(),
        tags: parseBlogTags(lesson.tags),
        links: Array.isArray(lesson.links) ? lesson.links.filter(Boolean) : parseMultilineValues(lesson.links),
        videoUrls: Array.isArray(lesson.videoUrls) ? lesson.videoUrls.filter(Boolean) : parseMultilineValues(lesson.videoUrls),
        iframeUrls: Array.isArray(lesson.iframeUrls) ? lesson.iframeUrls.filter(Boolean) : parseMultilineValues(lesson.iframeUrls),
        imageUrls: Array.isArray(lesson.imageUrls) ? lesson.imageUrls.filter(Boolean) : parseMultilineValues(lesson.imageUrls),
        attachments: Array.isArray(lesson.attachments) ? lesson.attachments.filter(Boolean) : parseMultilineValues(lesson.attachments),
        questions: Array.isArray(lesson.questions)
            ? lesson.questions.map((item, index) => normalizeLessonQuestionItem(item, index)).filter(item => item.question)
            : parseLessonQuestions(lesson.questions),
        lessonNumber: normalizeLessonNumber(lesson.lessonNumber),
        sortOrder: normalizeLessonNumber(lesson.sortOrder),
        safeDate: getLessonPublishDate(lesson)
    };
}

function getLessonSearchBlob(lesson) {
    return [
        lesson.title,
        lesson.summary,
        lesson.subject,
        lesson.topic,
        lesson.subtopic,
        lesson.category,
        ...(lesson.tags || []),
        ...(lesson.iframeUrls || []),
        ...(lesson.questions || []).map(item => `${item.question || ''} ${item.answer || ''} ${item.correctAnswer || ''} ${(item.options || []).join(' ')} ${item.explanation || ''}`),
        String(lesson.content || '').replace(/<[^>]+>/g, ' ')
    ].join(' ').toLowerCase();
}

function getLessonTodayKey() {
    const now = new Date();
    const year = now.getFullYear();
    const month = String(now.getMonth() + 1).padStart(2, '0');
    const day = String(now.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
}

function getFreeLessonAccessRecord() {
    try {
        const raw = localStorage.getItem(LESSON_FREE_DAILY_KEY);
        if (!raw) return null;
        const parsed = JSON.parse(raw);
        if (!parsed || typeof parsed !== 'object') return null;
        if (parsed.date !== getLessonTodayKey()) return null;
        return parsed;
    } catch (_) {
        return null;
    }
}

function setFreeLessonAccessRecord(lessonId) {
    try {
        localStorage.setItem(LESSON_FREE_DAILY_KEY, JSON.stringify({
            date: getLessonTodayKey(),
            lessonId
        }));
    } catch (_) {}
}

function getLessonAccessState(lessonId) {
    if (!currentUser) return { allowed: false, reason: 'Please sign in to access lessons.' };
    if (isAdminUser() || currentUser.tier === 'paid') return { allowed: true, reason: '' };

    const record = getFreeLessonAccessRecord();
    if (!record) return { allowed: true, reason: '' };
    if (record.lessonId === lessonId) return { allowed: true, reason: '' };

    return {
        allowed: false,
        reason: 'Free accounts can open one lesson per day. This resets at midnight.'
    };
}

function getLessonMetrics(lessonId) {
    if (!lessonId) return { views: 0, completions: 0 };
    const metrics = LESSON_METRICS_MAP.get(lessonId) || {};
    return {
        views: Number(metrics.views || 0),
        completions: Number(metrics.completions || 0)
    };
}

function getLessonProgress(lessonId) {
    if (!lessonId || !currentUser?.uid) return null;
    return LESSON_PROGRESS_MAP.get(lessonId) || null;
}

function isLessonViewed(lessonId) {
    const progress = getLessonProgress(lessonId);
    return !!(progress?.viewedAt || progress?.lastOpenedAt);
}

function isLessonCompleted(lessonId) {
    const progress = getLessonProgress(lessonId);
    return !!progress?.completedAt;
}

async function recordLessonView(lesson) {
    if (!isFirestoreAvailable() || !currentUser?.uid || !lesson?.id) return;
    const lessonId = lesson.id;
    const uid = currentUser.uid;
    try {
        await db.collection('users').doc(uid).collection('lessonProgress').doc(lessonId).set({
            lessonId,
            viewedAt: firebase.firestore.FieldValue.serverTimestamp(),
            lastOpenedAt: firebase.firestore.FieldValue.serverTimestamp(),
            openCount: firebase.firestore.FieldValue.increment(1),
            updatedAt: firebase.firestore.FieldValue.serverTimestamp(),
            title: lesson.title || ''
        }, { merge: true });

        await db.collection('lessonMetrics').doc(lessonId).set({
            lessonId,
            title: lesson.title || '',
            views: firebase.firestore.FieldValue.increment(1),
            updatedAt: firebase.firestore.FieldValue.serverTimestamp(),
            lastViewedAt: firebase.firestore.FieldValue.serverTimestamp()
        }, { merge: true });
    } catch (error) {
        logError(error, 'Lesson View Tracking');
    }
}

async function markLessonComplete(lessonId, source = 'manual') {
    if (!isFirestoreAvailable() || !currentUser?.uid || !lessonId) return;
    const lesson = allLessons.find(item => item.id === lessonId);
    if (!lesson) return;

    try {
        await db.collection('users').doc(currentUser.uid).collection('lessonProgress').doc(lessonId).set({
            lessonId,
            completedAt: firebase.firestore.FieldValue.serverTimestamp(),
            completedBy: source,
            updatedAt: firebase.firestore.FieldValue.serverTimestamp(),
            title: lesson.title || ''
        }, { merge: true });

        await db.collection('lessonMetrics').doc(lessonId).set({
            lessonId,
            title: lesson.title || '',
            completions: firebase.firestore.FieldValue.increment(1),
            updatedAt: firebase.firestore.FieldValue.serverTimestamp(),
            lastCompletedAt: firebase.firestore.FieldValue.serverTimestamp()
        }, { merge: true });

        if (source === 'manual') {
            showToast('Lesson marked as complete.', 'success');
        }
        renderLessonsPage(allLessons);
    } catch (error) {
        logError(error, 'Lesson Completion Tracking');
    }
}

function updateLessonCoverPreview() {
    const coverInput = document.getElementById('lesson-cover-image');
    const previewWrap = document.getElementById('lesson-cover-preview');
    const previewImage = document.getElementById('lesson-cover-preview-image');
    if (!coverInput || !previewWrap || !previewImage) return;
    const url = String(coverInput.value || '').trim();
    if (!url) {
        previewWrap.classList.add('hidden');
        previewImage.removeAttribute('src');
        return;
    }
    previewImage.src = url;
    previewWrap.classList.remove('hidden');
}

function normalizeSubjectToken(value) {
    return String(value || '').trim().toLowerCase();
}

function getLessonSubjectChoices() {
    const fromLessons = allLessons
        .map(item => normalizeLesson(item).subject)
        .map(item => String(item || '').trim())
        .filter(Boolean);
    const base = Array.isArray(SUBJECTS) ? SUBJECTS.slice() : [];
    const unique = [...new Set([...base, ...fromLessons])];
    return unique.sort((a, b) => a.localeCompare(b));
}

function populateLessonSubjectOptions(preferredSubject = '') {
    const subjectSelect = document.getElementById('lesson-subject');
    if (!subjectSelect) return;
    const customOption = '<option value="__custom__">Custom subject...</option>';
    const subjects = getLessonSubjectChoices();
    const normalizedPreferred = normalizeSubjectToken(preferredSubject);
    const hasPreferred = subjects.some(subject => normalizeSubjectToken(subject) === normalizedPreferred);
    subjectSelect.innerHTML = `<option value="">Select subject...</option>${subjects.map(subject => `<option value="${escapeHTML(subject)}">${escapeHTML(subject)}</option>`).join('')}${customOption}`;

    const stored = (() => {
        try { return localStorage.getItem(LESSON_LAST_SUBJECT_KEY) || ''; } catch (_) { return ''; }
    })();
    const desired = preferredSubject || stored;
    if (!desired) {
        subjectSelect.value = '';
        return;
    }

    if (hasPreferred) {
        subjectSelect.value = subjects.find(subject => normalizeSubjectToken(subject) === normalizedPreferred) || '';
        return;
    }

    subjectSelect.value = '__custom__';
    const customInput = document.getElementById('lesson-subject-custom');
    if (customInput) customInput.value = desired;
}

function syncLessonSubjectCustomVisibility() {
    const subjectSelect = document.getElementById('lesson-subject');
    const customInput = document.getElementById('lesson-subject-custom');
    if (!subjectSelect || !customInput) return;
    const customMode = subjectSelect.value === '__custom__';
    customInput.classList.toggle('hidden', !customMode);
    if (customMode) {
        customInput.required = true;
        customInput.focus();
    } else {
        customInput.required = false;
    }
}

function getSelectedLessonSubjectValue() {
    const subjectSelect = document.getElementById('lesson-subject');
    const customInput = document.getElementById('lesson-subject-custom');
    if (!subjectSelect) return '';
    if (subjectSelect.value === '__custom__') {
        return String(customInput?.value || '').trim();
    }
    return String(subjectSelect.value || '').trim();
}

function createLessonQuestionTemplate(type = 'short') {
    const normalizedType = ['short', 'mcq', 'truefalse'].includes(type) ? type : 'short';
    return {
        type: normalizedType,
        question: '',
        options: normalizedType === 'mcq' ? ['Option A', 'Option B'] : (normalizedType === 'truefalse' ? ['True', 'False'] : []),
        correctAnswer: normalizedType === 'truefalse' ? 'True' : '',
        required: true,
        points: 1,
        placeholder: normalizedType === 'short' ? 'Type your answer...' : '',
        explanation: ''
    };
}

function normalizeLessonQuestionItem(raw = {}, index = 0) {
    if (typeof raw === 'string') {
        const parsed = parseLessonQuestions(raw)[0] || {};
        raw = parsed;
    }

    const fallback = createLessonQuestionTemplate(raw?.type || 'short');
    const type = ['short', 'mcq', 'truefalse'].includes(String(raw?.type || '').toLowerCase())
        ? String(raw.type).toLowerCase()
        : fallback.type;
    const question = String(raw?.question || '').trim();
    const options = type === 'mcq'
        ? (Array.isArray(raw?.options) ? raw.options : String(raw?.options || '').split('\n'))
            .map(item => String(item || '').trim())
            .filter(Boolean)
        : (type === 'truefalse' ? ['True', 'False'] : []);
    const points = Number(raw?.points);

    return {
        id: String(raw?.id || `lesson-q-${Date.now()}-${index}-${Math.random().toString(36).slice(2, 7)}`),
        type,
        question,
        options,
        correctAnswer: String(raw?.correctAnswer ?? raw?.answer ?? '').trim(),
        required: raw?.required === undefined ? true : !!raw.required,
        points: Number.isFinite(points) && points > 0 ? points : 1,
        placeholder: String(raw?.placeholder || '').trim(),
        explanation: String(raw?.explanation || '').trim()
    };
}

function parseLegacyLessonQuestions(raw = '') {
    return String(raw || '')
        .split('\n')
        .map(line => String(line || '').trim())
        .filter(Boolean)
        .map(line => {
            const dividerIndex = line.indexOf('|');
            if (dividerIndex < 0) return { question: line, answer: '' };
            return {
                question: line.slice(0, dividerIndex).trim(),
                answer: line.slice(dividerIndex + 1).trim()
            };
        })
        .filter(item => item.question);
}

function parseLessonQuestions(raw = '') {
    if (Array.isArray(raw)) {
        return raw.map((item, index) => normalizeLessonQuestionItem(item, index)).filter(item => item.question);
    }

    const text = String(raw || '').trim();
    if (!text) return [];

    if ((text.startsWith('[') && text.endsWith(']')) || (text.startsWith('{') && text.endsWith('}'))) {
        try {
            const parsed = JSON.parse(text);
            if (Array.isArray(parsed)) {
                return parsed.map((item, index) => normalizeLessonQuestionItem(item, index)).filter(item => item.question);
            }
        } catch (_) {}
    }

    return parseLegacyLessonQuestions(text)
        .map((item, index) => normalizeLessonQuestionItem({
            type: 'short',
            question: item.question,
            correctAnswer: item.answer,
            required: true,
            points: 1
        }, index))
        .filter(item => item.question);
}

function serializeLessonQuestions(questions = []) {
    return (questions || [])
        .map(item => {
            const question = String(item?.question || '').trim();
            const answer = String((item?.answer ?? item?.correctAnswer) || '').trim();
            if (!question) return '';
            return answer ? `${question}|${answer}` : question;
        })
        .filter(Boolean)
        .join('\n');
}

function collectLessonQuestionsFromBuilder() {
    const host = document.getElementById('lesson-question-builder-list');
    if (!host) return [];
    const cards = Array.from(host.querySelectorAll('.lesson-question-item'));
    const normalized = cards.map((card, index) => {
        const type = String(card.getAttribute('data-type') || 'short').toLowerCase();
        const question = String(card.querySelector('[data-field="question"]')?.value || '').trim();
        const correctAnswer = String(card.querySelector('[data-field="correctAnswer"]')?.value || '').trim();
        const pointsRaw = Number(card.querySelector('[data-field="points"]')?.value || 1);
        const required = !!card.querySelector('[data-field="required"]')?.checked;
        const placeholder = String(card.querySelector('[data-field="placeholder"]')?.value || '').trim();
        const explanation = String(card.querySelector('[data-field="explanation"]')?.value || '').trim();
        const optionsText = String(card.querySelector('[data-field="options"]')?.value || '').trim();
        const options = type === 'mcq'
            ? optionsText.split('\n').map(item => String(item || '').trim()).filter(Boolean)
            : (type === 'truefalse' ? ['True', 'False'] : []);

        return normalizeLessonQuestionItem({
            id: card.getAttribute('data-id') || `lesson-q-${index}`,
            type,
            question,
            options,
            correctAnswer,
            points: Number.isFinite(pointsRaw) && pointsRaw > 0 ? pointsRaw : 1,
            required,
            placeholder,
            explanation
        }, index);
    }).filter(item => item.question);

    lessonQuestionBuilderState = normalized;
    const hidden = document.getElementById('lesson-questions');
    if (hidden) {
        hidden.value = JSON.stringify(normalized);
    }
    return normalized;
}

function renderLessonQuestionBuilder(questions = []) {
    const host = document.getElementById('lesson-question-builder-list');
    if (!host) return;
    const normalizedQuestions = (questions || [])
        .map((item, index) => normalizeLessonQuestionItem(item, index))
        .filter(item => item.question || item.correctAnswer || (item.options && item.options.length));
    lessonQuestionBuilderState = normalizedQuestions;

    if (!normalizedQuestions.length) {
        host.innerHTML = '<div class="rounded-lg border border-dashed border-indigo-200 bg-white px-4 py-5 text-sm text-slate-500">No form questions yet. Use the buttons above to add short answer, multiple-choice, or true/false questions.</div>';
        const hidden = document.getElementById('lesson-questions');
        if (hidden) hidden.value = '[]';
        return;
    }

    host.innerHTML = normalizedQuestions.map((item, index) => {
        const optionsValue = (item.options || []).join('\n');
        const typeLabel = item.type === 'mcq' ? 'Multiple choice' : (item.type === 'truefalse' ? 'True/false' : 'Short answer');
        return `
            <article class="lesson-question-item rounded-xl border border-indigo-200 bg-white p-4" data-id="${escapeHTML(item.id)}" data-type="${escapeHTML(item.type)}">
                <div class="flex flex-wrap items-center justify-between gap-2 mb-3">
                    <p class="text-xs font-bold uppercase tracking-[0.14em] text-indigo-700">Question ${index + 1} · ${escapeHTML(typeLabel)}</p>
                    <button type="button" onclick="removeLessonQuestionItem(${index})" class="px-2.5 py-1.5 rounded-lg bg-rose-50 border border-rose-200 text-rose-700 text-xs font-semibold hover:bg-rose-100">Remove</button>
                </div>
                <div class="grid grid-cols-1 md:grid-cols-2 gap-3">
                    <input type="text" data-field="question" placeholder="Question prompt" value="${escapeHTML(item.question)}" class="w-full p-3 rounded-lg border border-gray-300/70 bg-white focus:outline-none focus:ring-2 focus:ring-indigo-500">
                    <input type="text" data-field="correctAnswer" placeholder="Correct answer (or option text)" value="${escapeHTML(item.correctAnswer)}" class="w-full p-3 rounded-lg border border-gray-300/70 bg-white focus:outline-none focus:ring-2 focus:ring-indigo-500">
                    <input type="number" min="1" step="1" data-field="points" value="${escapeHTML(String(item.points || 1))}" class="w-full p-3 rounded-lg border border-gray-300/70 bg-white focus:outline-none focus:ring-2 focus:ring-indigo-500" placeholder="Points">
                    <input type="text" data-field="placeholder" placeholder="Input placeholder (short answer only)" value="${escapeHTML(item.placeholder || '')}" class="w-full p-3 rounded-lg border border-gray-300/70 bg-white focus:outline-none focus:ring-2 focus:ring-indigo-500">
                </div>
                ${item.type === 'mcq' ? `<textarea data-field="options" rows="4" placeholder="MCQ options (one per line)" class="mt-3 w-full p-3 rounded-lg border border-gray-300/70 bg-white focus:outline-none focus:ring-2 focus:ring-indigo-500">${escapeHTML(optionsValue)}</textarea>` : ''}
                <textarea data-field="explanation" rows="2" placeholder="Optional explanation shown after submit" class="mt-3 w-full p-3 rounded-lg border border-gray-300/70 bg-white focus:outline-none focus:ring-2 focus:ring-indigo-500">${escapeHTML(item.explanation || '')}</textarea>
                <label class="mt-2 inline-flex items-center gap-2 text-sm font-semibold text-slate-700">
                    <input type="checkbox" data-field="required" ${item.required ? 'checked' : ''} class="rounded border-gray-300 text-indigo-600 focus:ring-indigo-500">
                    Required question
                </label>
            </article>
        `;
    }).join('');

    const hidden = document.getElementById('lesson-questions');
    if (hidden) {
        hidden.value = JSON.stringify(normalizedQuestions);
    }
}

function addLessonQuestionItem(type = 'short') {
    const current = collectLessonQuestionsFromBuilder();
    current.push(createLessonQuestionTemplate(type));
    renderLessonQuestionBuilder(current);
}

function removeLessonQuestionItem(index) {
    const current = collectLessonQuestionsFromBuilder();
    current.splice(index, 1);
    renderLessonQuestionBuilder(current);
}

function autoArrangeLessonDraft() {
    const lessonNumberEl = document.getElementById('lesson-number');
    const sortOrderEl = document.getElementById('lesson-sort-order');
    const publishEl = document.getElementById('lesson-publish-date');
    const lessonId = document.getElementById('lesson-id')?.value;

    if (!lessonId) {
        const subject = normalizeSubjectToken(getSelectedLessonSubjectValue());
        const topic = String(document.getElementById('lesson-topic')?.value || '').trim().toLowerCase();
        const subtopic = String(document.getElementById('lesson-subtopic')?.value || '').trim().toLowerCase();
        const bucket = allLessons
            .map(normalizeLesson)
            .filter(item =>
                String(item.subject || '').trim().toLowerCase() === subject &&
                String(item.topic || '').trim().toLowerCase() === topic &&
                String(item.subtopic || '').trim().toLowerCase() === subtopic
            )
            .sort((a, b) => (a.lessonNumber || 0) - (b.lessonNumber || 0));
        const nextNumber = (bucket[bucket.length - 1]?.lessonNumber || 0) + 1;
        if (lessonNumberEl && !lessonNumberEl.value) lessonNumberEl.value = String(nextNumber);
        if (sortOrderEl && !sortOrderEl.value) sortOrderEl.value = String(nextNumber * 10);
    }

    if (publishEl && !publishEl.value) {
        const now = new Date();
        publishEl.value = new Date(now.getTime() - now.getTimezoneOffset() * 60000).toISOString().slice(0, 16);
    }

    const titleInput = document.getElementById('lesson-title');
    const topicInput = document.getElementById('lesson-topic');
    if (titleInput && !String(titleInput.value || '').trim()) {
        const subject = String(getSelectedLessonSubjectValue() || 'General').trim() || 'General';
        const topic = String(topicInput?.value || 'Topic').trim() || 'Topic';
        const lessonNumber = String(lessonNumberEl?.value || '').trim();
        titleInput.value = lessonNumber ? `${subject} ${topic} - Lesson ${lessonNumber}` : `${subject} ${topic} lesson`;
    }

    showToast('Lesson draft auto-arranged.', 'info');
}

function showLessonTemplateOverrideModal(onReplace, onKeep) {
    const modal = document.getElementById('confirmation-modal');
    if (!modal) {
        if (typeof onKeep === 'function') onKeep();
        return;
    }
    modal.innerHTML = `
        <div class="bg-white/95 backdrop-blur-lg rounded-xl shadow-xl w-full max-w-md p-6 fade-in">
            <h4 class="text-lg font-bold text-slate-900">Template and Existing Content</h4>
            <p class="mt-2 text-sm text-slate-600">Your lesson editor already has text. Replace the current content with the template or keep your text and only fill empty fields.</p>
            <div class="mt-5 flex flex-wrap justify-end gap-2">
                <button id="lesson-template-cancel" class="px-4 py-2 rounded-lg border border-gray-300 bg-white text-gray-700 font-semibold hover:bg-gray-50">Cancel</button>
                <button id="lesson-template-keep" class="px-4 py-2 rounded-lg bg-slate-100 text-slate-700 font-semibold hover:bg-slate-200">Keep text</button>
                <button id="lesson-template-replace" class="px-4 py-2 rounded-lg bg-indigo-600 text-white font-semibold hover:bg-indigo-700">Replace text</button>
            </div>
        </div>
    `;
    modal.style.display = 'flex';

    const close = () => { modal.style.display = 'none'; };
    document.getElementById('lesson-template-cancel')?.addEventListener('click', close);
    document.getElementById('lesson-template-keep')?.addEventListener('click', () => {
        if (typeof onKeep === 'function') onKeep();
        close();
    });
    document.getElementById('lesson-template-replace')?.addEventListener('click', () => {
        if (typeof onReplace === 'function') onReplace();
        close();
    });
}

function applyLessonTemplate() {
    const templateSelect = document.getElementById('lesson-template-select');
    const key = templateSelect?.value;
    if (!key || !LESSON_TEMPLATES[key]) {
        showToast('Choose a lesson template first.', 'warning');
        return;
    }
    const template = LESSON_TEMPLATES[key];
    const titleInput = document.getElementById('lesson-title');
    const summaryInput = document.getElementById('lesson-summary');
    const contentEditor = document.getElementById('lesson-content');

    const applyScaffold = (replaceContent) => {
        if (titleInput && !titleInput.value.trim()) {
            titleInput.value = `${template.titlePrefix}Untitled`;
        }
        if (summaryInput && !summaryInput.value.trim()) {
            summaryInput.value = template.summary;
        }
        if (contentEditor) {
            const hasExisting = !!String(contentEditor.innerHTML || '').replace(/<[^>]+>/g, '').trim();
            if (replaceContent || !hasExisting) {
                contentEditor.innerHTML = template.content;
            }
        }
        autoArrangeLessonDraft();
        showToast('Template applied.', 'success');
    };

    const hasEditorContent = !!String(contentEditor?.innerHTML || '').replace(/<[^>]+>/g, '').trim();
    if (hasEditorContent) {
        showLessonTemplateOverrideModal(
            () => applyScaffold(true),
            () => applyScaffold(false)
        );
        return;
    }

    applyScaffold(false);
}

function syncLessonFilterSelect(selectId, values, currentValue, allLabel) {
    const select = document.getElementById(selectId);
    if (!select) return;
    const options = [...new Set(values.map(v => String(v || '').trim()).filter(Boolean))].sort((a, b) => a.localeCompare(b));
    select.innerHTML = `<option value="all">${allLabel}</option>${options.map(v => `<option value="${escapeHTML(v)}">${escapeHTML(v)}</option>`).join('')}`;
    select.value = options.some(v => normalizeBlogToken(v) === normalizeBlogToken(currentValue)) ? currentValue : 'all';
}

function getFilteredLessons(lessons = []) {
    const processed = lessons.map(normalizeLesson);
    const readableLessons = isAdminUser() ? processed : processed.filter(canUserReadLesson);
    const query = normalizeBlogToken(LESSON_VIEW_STATE.search);
    const subjectFilter = normalizeBlogToken(LESSON_VIEW_STATE.subject);
    const topicFilter = normalizeBlogToken(LESSON_VIEW_STATE.topic);
    const subtopicFilter = normalizeBlogToken(LESSON_VIEW_STATE.subtopic);
    const categoryFilter = normalizeBlogToken(LESSON_VIEW_STATE.category);

    const filtered = readableLessons.filter(lesson => {
        const blob = getLessonSearchBlob(lesson);
        const subject = normalizeBlogToken(lesson.subject);
        const topic = normalizeBlogToken(lesson.topic);
        const subtopic = normalizeBlogToken(lesson.subtopic);
        const category = normalizeBlogToken(lesson.category);
        const matchesSearch = !query || blob.includes(query);
        const matchesSubject = !subjectFilter || subjectFilter === 'all' || subject === subjectFilter;
        const matchesTopic = !topicFilter || topicFilter === 'all' || topic === topicFilter;
        const matchesSubtopic = !subtopicFilter || subtopicFilter === 'all' || subtopic === subtopicFilter;
        const matchesCategory = !categoryFilter || categoryFilter === 'all' || category === categoryFilter;
        return matchesSearch && matchesSubject && matchesTopic && matchesSubtopic && matchesCategory;
    });

    const sortBy = LESSON_VIEW_STATE.sort;
    filtered.sort((a, b) => {
        if (sortBy === 'title') return (a.title || '').localeCompare(b.title || '');
        if (sortBy === 'newest') return b.safeDate - a.safeDate;
        if (sortBy === 'oldest') return a.safeDate - b.safeDate;

        const pathCompare = (a.subject || '').localeCompare(b.subject || '')
            || (a.topic || '').localeCompare(b.topic || '')
            || (a.subtopic || '').localeCompare(b.subtopic || '');
        if (pathCompare !== 0) return pathCompare;

        const lessonNumberA = a.lessonNumber ?? Number.MAX_SAFE_INTEGER;
        const lessonNumberB = b.lessonNumber ?? Number.MAX_SAFE_INTEGER;
        if (lessonNumberA !== lessonNumberB) return lessonNumberA - lessonNumberB;

        const sortOrderA = a.sortOrder ?? Number.MAX_SAFE_INTEGER;
        const sortOrderB = b.sortOrder ?? Number.MAX_SAFE_INTEGER;
        if (sortOrderA !== sortOrderB) return sortOrderA - sortOrderB;

        return b.safeDate - a.safeDate;
    });

    return { processed: readableLessons, filtered };
}

function renderLessonsHierarchyTree(lessons = []) {
    const host = document.getElementById('lessons-tree');
    if (!host) return;

    const tree = {};
    lessons.forEach(lesson => {
        const subject = lesson.subject || 'Unassigned subject';
        const topic = lesson.topic || 'General topic';
        const subtopic = lesson.subtopic || 'General subtopic';

        if (!tree[subject]) tree[subject] = {};
        if (!tree[subject][topic]) tree[subject][topic] = {};
        if (!tree[subject][topic][subtopic]) tree[subject][topic][subtopic] = 0;
        tree[subject][topic][subtopic] += 1;
    });

    const subjects = Object.keys(tree).sort((a, b) => a.localeCompare(b));
    if (!subjects.length) {
        host.innerHTML = '<p class="text-sm text-slate-500">No lessons available yet.</p>';
        return;
    }

    const rows = [];
    rows.push('<button class="lessons-tree-node" type="button" onclick="setLessonTreeFilter(\'all\')">All lessons</button>');

    subjects.forEach(subject => {
        rows.push(`<button class="lessons-tree-node" type="button" onclick="setLessonTreeFilter('subject', '${escapeJS(subject)}')">${escapeHTML(subject)}</button>`);
        Object.keys(tree[subject]).sort((a, b) => a.localeCompare(b)).forEach(topic => {
            rows.push(`<button class="lessons-tree-node lessons-tree-node-level-1" type="button" onclick="setLessonTreeFilter('topic', '${escapeJS(subject)}', '${escapeJS(topic)}')">${escapeHTML(topic)}</button>`);
            Object.keys(tree[subject][topic]).sort((a, b) => a.localeCompare(b)).forEach(subtopic => {
                const count = tree[subject][topic][subtopic];
                rows.push(`<button class="lessons-tree-node lessons-tree-node-level-2" type="button" onclick="setLessonTreeFilter('subtopic', '${escapeJS(subject)}', '${escapeJS(topic)}', '${escapeJS(subtopic)}')">${escapeHTML(subtopic)} <span class="lessons-tree-count">${count}</span></button>`);
            });
        });
    });

    host.innerHTML = rows.join('');
}

function updateLessonInsightCards(lessons = []) {
    const totalEl = document.getElementById('lesson-total-count');
    const subjectEl = document.getElementById('lesson-subject-count');
    const latestEl = document.getElementById('lesson-latest-date');
    const completedEl = document.getElementById('lesson-completed-count');
    if (totalEl) totalEl.textContent = String(lessons.length);
    if (subjectEl) {
        const subjectCount = new Set(lessons.map(lesson => normalizeBlogToken(lesson.subject)).filter(Boolean)).size;
        subjectEl.textContent = String(subjectCount);
    }
    if (latestEl) {
        const latest = [...lessons].sort((a, b) => b.safeDate - a.safeDate)[0];
        latestEl.textContent = latest ? latest.safeDate.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }) : 'Not yet';
    }
    if (completedEl) {
        const completedCount = lessons.filter(lesson => isLessonCompleted(lesson.id)).length;
        completedEl.textContent = String(completedCount);
    }
}

function renderLessonResultsSummary(visible, total) {
    const summary = document.getElementById('lessons-results-summary');
    if (!summary) return;
    const filtersActive = !!(LESSON_VIEW_STATE.search || LESSON_VIEW_STATE.subject !== 'all' || LESSON_VIEW_STATE.topic !== 'all' || LESSON_VIEW_STATE.subtopic !== 'all' || LESSON_VIEW_STATE.category !== 'all');
    if (!total) {
        summary.textContent = 'No lessons yet';
        return;
    }
    summary.textContent = filtersActive
        ? `${visible} of ${total} lessons match your filters`
        : `${visible} lesson${visible === 1 ? '' : 's'} available`;
}

function getLessonLeaderboardDisplayName(uid) {
    const user = allUsers?.[uid] || {};
    return user.displayName || user.name || user.fullName || user.email || uid || 'Unknown user';
}

function renderLessonAnalyticsList(containerId, rows, valueLabel, emptyMessage) {
    const host = document.getElementById(containerId);
    if (!host) return;
    if (!rows.length) {
        host.innerHTML = `<p class="text-sm text-slate-500">${escapeHTML(emptyMessage)}</p>`;
        return;
    }
    host.innerHTML = rows.map((row, index) => `
        <div class="lesson-analytics-row">
            <span class="lesson-analytics-rank">${index + 1}</span>
            <span class="lesson-analytics-name">${escapeHTML(row.name || 'Untitled')}</span>
            <span class="lesson-analytics-value">${escapeHTML(String(row.value))} ${escapeHTML(valueLabel)}</span>
        </div>
    `).join('');
}

function renderLessonAdminAnalyticsPanel(lessons = []) {
    const panel = document.getElementById('lesson-admin-analytics');
    if (!panel) return;
    if (!isAdminUser()) {
        panel.classList.add('hidden');
        return;
    }

    panel.classList.remove('hidden');

    const lessonNameById = new Map(lessons.map(lesson => [lesson.id, lesson.title || 'Untitled lesson']));
    const metricsRows = Array.from(LESSON_METRICS_MAP.entries()).map(([lessonId, metrics]) => ({
        lessonId,
        name: lessonNameById.get(lessonId) || metrics.title || 'Untitled lesson',
        views: Number(metrics?.views || 0),
        completions: Number(metrics?.completions || 0)
    }));

    const topViewed = metricsRows
        .filter(item => item.views > 0)
        .sort((a, b) => b.views - a.views)
        .slice(0, 8)
        .map(item => ({ name: item.name, value: item.views }));

    const topCompleted = metricsRows
        .filter(item => item.completions > 0)
        .sort((a, b) => b.completions - a.completions)
        .slice(0, 8)
        .map(item => ({ name: item.name, value: item.completions }));

    const leaderboard = Array.from(LESSON_USER_COMPLETION_MAP.entries())
        .map(([uid, count]) => ({ name: getLessonLeaderboardDisplayName(uid), value: Number(count || 0) }))
        .filter(item => item.value > 0)
        .sort((a, b) => b.value - a.value)
        .slice(0, 10);

    renderLessonAnalyticsList('lesson-analytics-top-viewed', topViewed, 'views', 'No views tracked yet.');
    renderLessonAnalyticsList('lesson-analytics-top-completed', topCompleted, 'completions', 'No completions tracked yet.');
    renderLessonAnalyticsList('lesson-analytics-user-leaderboard', leaderboard, 'completed', 'No user completions yet.');
}

function getLessonAccessBadge(lessonId) {
    if (!currentUser) return { label: 'Sign in required', classes: 'bg-gray-100 text-gray-700 border-gray-200', locked: true };
    if (isAdminUser()) return { label: 'Admin access', classes: 'bg-emerald-100 text-emerald-700 border-emerald-200', locked: false };
    if (currentUser.tier === 'paid') return { label: 'Pro access', classes: 'bg-blue-100 text-blue-700 border-blue-200', locked: false };
    const state = getLessonAccessState(lessonId);
    if (state.allowed) return { label: 'Free daily lesson', classes: 'bg-amber-100 text-amber-700 border-amber-200', locked: false };
    return { label: 'Locked for today', classes: 'bg-rose-100 text-rose-700 border-rose-200', locked: true };
}

function renderLessonsPage(lessons = []) {
    const list = document.getElementById('lesson-list');
    if (!list) return;

    setupLessonsFilters();
    if (isAdminUser()) {
        const currentSubject = getSelectedLessonSubjectValue();
        populateLessonSubjectOptions(currentSubject);
        syncLessonSubjectCustomVisibility();
    }
    setLessonsStatusMessage('');

    const { processed, filtered } = getFilteredLessons(lessons);

    syncLessonFilterSelect('lesson-subject-filter', processed.map(item => item.subject), LESSON_VIEW_STATE.subject, 'All subjects');
    syncLessonFilterSelect('lesson-topic-filter', processed.map(item => item.topic), LESSON_VIEW_STATE.topic, 'All topics');
    syncLessonFilterSelect('lesson-subtopic-filter', processed.map(item => item.subtopic), LESSON_VIEW_STATE.subtopic, 'All subtopics');
    syncLessonFilterSelect('lesson-category-filter', processed.map(item => item.category), LESSON_VIEW_STATE.category, 'All categories');

    renderLessonsHierarchyTree(processed);
    updateLessonInsightCards(processed);
    renderLessonResultsSummary(filtered.length, processed.length);
    renderLessonAdminAnalyticsPanel(processed);

    list.innerHTML = '';
    if (!processed.length) {
        list.innerHTML = '<div class="col-span-full blog-empty-state"><div class="mx-auto flex h-14 w-14 items-center justify-center rounded-2xl bg-blue-50 text-blue-600"><i class="fas fa-book-open text-xl"></i></div><h3 class="mt-4 text-lg font-bold text-gray-800">No lessons yet</h3><p class="mt-2 text-sm text-gray-500">Admins can create the first lesson using the editor above.</p></div>';
        return;
    }

    if (!filtered.length) {
        list.innerHTML = '<div class="col-span-full blog-empty-state"><div class="mx-auto flex h-14 w-14 items-center justify-center rounded-2xl bg-amber-50 text-amber-600"><i class="fas fa-filter-circle-xmark text-xl"></i></div><h3 class="mt-4 text-lg font-bold text-gray-800">No lessons match those filters</h3><p class="mt-2 text-sm text-gray-500">Try changing the hierarchy filters or reset to all lessons.</p></div>';
        return;
    }

    filtered.forEach(lesson => {
        const card = document.createElement('article');
        const accessBadge = getLessonAccessBadge(lesson.id);
        const metrics = getLessonMetrics(lesson.id);
        const viewed = isLessonViewed(lesson.id);
        const completed = isLessonCompleted(lesson.id);
        const contentPreview = escapeHTML(String(lesson.summary || lesson.content || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 150));
        const tagChips = (lesson.tags || []).slice(0, 3).map(tag => `<span class="blog-tag-chip">#${escapeHTML(tag)}</span>`).join('');
        const lessonPath = [lesson.subject, lesson.topic, lesson.subtopic].filter(Boolean).join(' • ') || 'General';
        const publishText = lesson.safeDate.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });
        const lessonNumberText = Number.isFinite(lesson.lessonNumber) ? `Lesson ${lesson.lessonNumber}` : 'Lesson';
        const lessonStatus = getLessonStatus(lesson);
        const statusChip = lessonStatus === 'draft'
            ? '<span class="inline-flex items-center rounded-full bg-amber-100 px-2.5 py-1 text-[11px] font-semibold text-amber-700">Draft</span>'
            : '<span class="inline-flex items-center rounded-full bg-emerald-100 px-2.5 py-1 text-[11px] font-semibold text-emerald-700">Published</span>';
        const isAdmin = isAdminUser();
        const adminButtons = isAdmin
            ? `<div class="absolute top-3 right-3 flex items-center gap-1.5">
                <button onclick="event.stopPropagation(); editLesson('${escapeJS(lesson.id)}')" class="p-2 bg-blue-500/85 text-white rounded-full hover:bg-blue-600 transition-colors" title="Edit lesson"><i class="fas fa-pen"></i></button>
                <button onclick="event.stopPropagation(); toggleLessonPublishStatus('${escapeJS(lesson.id)}', ${lessonStatus !== 'published'})" class="p-2 ${lessonStatus === 'published' ? 'bg-amber-500/85 hover:bg-amber-600' : 'bg-emerald-500/85 hover:bg-emerald-600'} text-white rounded-full transition-colors" title="${lessonStatus === 'published' ? 'Move to draft' : 'Publish lesson'}"><i class="fas ${lessonStatus === 'published' ? 'fa-box-archive' : 'fa-bullhorn'}"></i></button>
                <button onclick="event.stopPropagation(); deleteLesson('${escapeJS(lesson.id)}')" class="p-2 bg-red-500/85 text-white rounded-full hover:bg-red-600 transition-colors" title="Delete lesson"><i class="fas fa-trash"></i></button>
            </div>`
            : '';

        card.className = 'lesson-card relative rounded-2xl border border-blue-100 bg-white p-5 shadow-sm hover:shadow-md transition-shadow';
        card.innerHTML = `
            ${adminButtons}
            <div class="flex items-center justify-between gap-2">
                <span class="inline-flex items-center rounded-full border px-3 py-1 text-[11px] font-bold uppercase tracking-[0.16em] ${accessBadge.classes}">${accessBadge.label}</span>
                <span class="text-xs font-semibold text-slate-500">${escapeHTML(lessonNumberText)}</span>
            </div>
            <h3 class="mt-3 text-xl font-black text-slate-900 leading-tight">${escapeHTML(lesson.title || 'Untitled lesson')}</h3>
            <p class="mt-2 text-sm text-slate-600">${contentPreview || 'Open this lesson to view the complete interactive content.'}${contentPreview ? '…' : ''}</p>
            <p class="mt-3 text-xs font-semibold text-blue-700">${escapeHTML(lessonPath)}</p>
            <div class="mt-2 flex flex-wrap items-center gap-2">
                ${statusChip}
                ${viewed ? '<span class="inline-flex items-center rounded-full bg-slate-100 px-2.5 py-1 text-[11px] font-semibold text-slate-700">Viewed</span>' : ''}
                ${completed ? '<span class="inline-flex items-center rounded-full bg-emerald-100 px-2.5 py-1 text-[11px] font-semibold text-emerald-700">Completed</span>' : ''}
            </div>
            <div class="mt-2 flex flex-wrap gap-2">${tagChips}</div>
            <div class="mt-4 flex items-center justify-between gap-2">
                <span class="text-xs text-slate-500">${lessonStatus === 'published' ? 'Published' : 'Saved'} ${publishText}</span>
                <button class="inline-flex items-center gap-2 rounded-lg bg-blue-600 px-3 py-2 text-xs font-bold text-white hover:bg-blue-700 transition-colors" ${accessBadge.locked ? 'disabled' : ''} onclick="openLessonViewer('${escapeJS(lesson.id)}')">
                    ${accessBadge.locked ? 'Locked' : 'Open lesson'}
                </button>
            </div>
            <div class="mt-3 flex items-center justify-between text-[11px] font-semibold text-slate-500">
                <span><i class="fas fa-eye mr-1 text-slate-400"></i>${metrics.views} views</span>
                <span><i class="fas fa-check-circle mr-1 text-emerald-500"></i>${metrics.completions} completions</span>
            </div>
        `;
        list.appendChild(card);
    });
}

function setupLessonsFilters() {
    if (lessonsFiltersBound) return;
    lessonsFiltersBound = true;

    const search = document.getElementById('lesson-search');
    const subject = document.getElementById('lesson-subject-filter');
    const topic = document.getElementById('lesson-topic-filter');
    const subtopic = document.getElementById('lesson-subtopic-filter');
    const category = document.getElementById('lesson-category-filter');
    const sort = document.getElementById('lesson-sort');
    const clear = document.getElementById('lesson-clear-filters');

    if (search) {
        search.addEventListener('input', () => {
            LESSON_VIEW_STATE.search = search.value.trim();
            renderLessonsPage(allLessons);
        });
    }
    if (subject) {
        subject.addEventListener('change', () => {
            LESSON_VIEW_STATE.subject = subject.value;
            if (LESSON_VIEW_STATE.subject === 'all') {
                LESSON_VIEW_STATE.topic = 'all';
                LESSON_VIEW_STATE.subtopic = 'all';
            }
            renderLessonsPage(allLessons);
        });
    }
    if (topic) {
        topic.addEventListener('change', () => {
            LESSON_VIEW_STATE.topic = topic.value;
            if (LESSON_VIEW_STATE.topic === 'all') {
                LESSON_VIEW_STATE.subtopic = 'all';
            }
            renderLessonsPage(allLessons);
        });
    }
    if (subtopic) {
        subtopic.addEventListener('change', () => {
            LESSON_VIEW_STATE.subtopic = subtopic.value;
            renderLessonsPage(allLessons);
        });
    }
    if (category) {
        category.addEventListener('change', () => {
            LESSON_VIEW_STATE.category = category.value;
            renderLessonsPage(allLessons);
        });
    }
    if (sort) {
        sort.addEventListener('change', () => {
            LESSON_VIEW_STATE.sort = sort.value;
            renderLessonsPage(allLessons);
        });
    }
    if (clear) {
        clear.addEventListener('click', () => {
            LESSON_VIEW_STATE.search = '';
            LESSON_VIEW_STATE.subject = 'all';
            LESSON_VIEW_STATE.topic = 'all';
            LESSON_VIEW_STATE.subtopic = 'all';
            LESSON_VIEW_STATE.category = 'all';
            LESSON_VIEW_STATE.sort = 'path';
            if (search) search.value = '';
            if (subject) subject.value = 'all';
            if (topic) topic.value = 'all';
            if (subtopic) subtopic.value = 'all';
            if (category) category.value = 'all';
            if (sort) sort.value = 'path';
            renderLessonsPage(allLessons);
        });
    }
}

function setLessonTreeFilter(level = 'all', subject = '', topic = '', subtopic = '') {
    LESSON_VIEW_STATE.subject = 'all';
    LESSON_VIEW_STATE.topic = 'all';
    LESSON_VIEW_STATE.subtopic = 'all';

    if (level === 'subject') {
        LESSON_VIEW_STATE.subject = subject || 'all';
    } else if (level === 'topic') {
        LESSON_VIEW_STATE.subject = subject || 'all';
        LESSON_VIEW_STATE.topic = topic || 'all';
    } else if (level === 'subtopic') {
        LESSON_VIEW_STATE.subject = subject || 'all';
        LESSON_VIEW_STATE.topic = topic || 'all';
        LESSON_VIEW_STATE.subtopic = subtopic || 'all';
    }

    renderLessonsPage(allLessons);
}

function serializeLessonForm(status = 'published') {
    const publishDateValue = document.getElementById('lesson-publish-date')?.value || '';
    const publishDate = publishDateValue ? new Date(publishDateValue) : null;
    const isValidPublishDate = publishDate && !Number.isNaN(publishDate.getTime());
    const normalizedStatus = String(status || 'published').toLowerCase() === 'draft' ? 'draft' : 'published';
    const sourceUrlValue = String(document.getElementById('lesson-source-url')?.value || '').trim();
    const sourceUrlValid = /^https?:\/\//i.test(sourceUrlValue);

    const builderQuestions = collectLessonQuestionsFromBuilder();
    return {
        status: normalizedStatus,
        title: document.getElementById('lesson-title')?.value?.trim() || '',
        summary: document.getElementById('lesson-summary')?.value?.trim() || '',
        subject: getSelectedLessonSubjectValue(),
        topic: document.getElementById('lesson-topic')?.value?.trim() || '',
        subtopic: document.getElementById('lesson-subtopic')?.value?.trim() || '',
        category: document.getElementById('lesson-category')?.value?.trim() || '',
        lessonNumber: normalizeLessonNumber(document.getElementById('lesson-number')?.value),
        sortOrder: normalizeLessonNumber(document.getElementById('lesson-sort-order')?.value),
        publishDate: isValidPublishDate ? firebase.firestore.Timestamp.fromDate(publishDate) : firebase.firestore.FieldValue.serverTimestamp(),
        publishedAt: normalizedStatus === 'published'
            ? (isValidPublishDate ? firebase.firestore.Timestamp.fromDate(publishDate) : firebase.firestore.FieldValue.serverTimestamp())
            : null,
        publishedBy: normalizedStatus === 'published' ? (currentUser?.uid || null) : null,
        draftSavedAt: normalizedStatus === 'draft' ? firebase.firestore.FieldValue.serverTimestamp() : null,
        coverImage: document.getElementById('lesson-cover-image')?.value?.trim() || null,
        tags: parseBlogTags(document.getElementById('lesson-tags')?.value || ''),
        content: sanitizeHTML(document.getElementById('lesson-content')?.innerHTML?.trim() || ''),
        interactiveHtml: sanitizeHTML(document.getElementById('lesson-interactive-html')?.value || ''),
        widgetHtml: sanitizeHTML(document.getElementById('lesson-widget-html')?.value || ''),
        links: parseMultilineValues(document.getElementById('lesson-links')?.value || ''),
        videoUrls: parseMultilineValues(document.getElementById('lesson-video-urls')?.value || ''),
        iframeUrls: parseMultilineValues(document.getElementById('lesson-iframe-urls')?.value || ''),
        imageUrls: parseMultilineValues(document.getElementById('lesson-image-urls')?.value || ''),
        attachments: parseMultilineValues(document.getElementById('lesson-attachments')?.value || ''),
        questions: builderQuestions.length
            ? builderQuestions
            : parseLessonQuestions(document.getElementById('lesson-questions')?.value || ''),
        buttonLabel: document.getElementById('lesson-button-label')?.value?.trim() || '',
        buttonUrl: document.getElementById('lesson-button-url')?.value?.trim() || '',
        scrapedFromUrl: sourceUrlValid ? sourceUrlValue : null,
        scrapedAt: sourceUrlValid ? firebase.firestore.FieldValue.serverTimestamp() : null,
        updatedAt: firebase.firestore.FieldValue.serverTimestamp(),
        createdBy: currentUser?.uid || null,
        authorName: currentUser?.displayName || currentUser?.email || 'GCSEMate'
    };
}

async function handleSaveLesson(status = 'published') {
    if (!isAdminUser()) return;
    autoArrangeLessonDraft();
    const messageEl = document.getElementById('add-lesson-message');
    if (!isFirestoreAvailable()) {
        const friendly = getFirebaseFriendlyMessage(getFirebaseBootstrapError(), 'Lessons are temporarily unavailable. Please try again shortly.');
        if (messageEl) {
            messageEl.textContent = friendly;
            messageEl.className = 'text-red-600 text-sm mt-2 h-4';
        }
        showToast(friendly, 'error');
        return;
    }

    const lessonId = document.getElementById('lesson-id')?.value || '';
    const lessonStatus = String(status || 'published').toLowerCase() === 'draft' ? 'draft' : 'published';
    const lessonData = serializeLessonForm(lessonStatus);
    const statusField = document.getElementById('lesson-status');
    if (statusField) statusField.value = lessonStatus;
    if (lessonStatus === 'published' && (!lessonData.title || !lessonData.content)) {
        if (messageEl) {
            messageEl.textContent = 'Lesson title and main content are required.';
            messageEl.className = 'text-red-600 text-sm mt-2 h-4';
        }
        showToast('Lesson title and main content are required.', 'error');
        return;
    }

    try {
        try {
            if (lessonData.subject) localStorage.setItem(LESSON_LAST_SUBJECT_KEY, lessonData.subject);
        } catch (_) {}
        if (lessonId) {
            await db.collection('lessons').doc(lessonId).update(lessonData);
        } else {
            lessonData.createdAt = firebase.firestore.FieldValue.serverTimestamp();
            await db.collection('lessons').add(lessonData);
        }
        resetLessonForm();
        if (messageEl) {
            messageEl.textContent = lessonStatus === 'draft' ? 'Lesson draft saved successfully!' : 'Lesson published successfully!';
            messageEl.className = 'text-green-600 text-sm mt-2 h-4';
            setTimeout(() => { messageEl.textContent = ''; }, 3000);
        }
    } catch (error) {
        console.error('Error saving lesson:', error);
        const friendly = getFirebaseFriendlyMessage(error, 'Could not save lesson. Please try again.');
        if (messageEl) {
            messageEl.textContent = friendly;
            messageEl.className = 'text-red-600 text-sm mt-2 h-4';
        }
        showToast(friendly, 'error');
    }
}

async function handleSaveLessonDraft() {
    await handleSaveLesson('draft');
}

async function toggleLessonPublishStatus(lessonId, shouldPublish = true) {
    if (!isAdminUser() || !lessonId || !isFirestoreAvailable()) return;
    const nextStatus = shouldPublish ? 'published' : 'draft';
    const payload = {
        status: nextStatus,
        updatedAt: firebase.firestore.FieldValue.serverTimestamp(),
        publishedAt: shouldPublish ? firebase.firestore.FieldValue.serverTimestamp() : null,
        publishedBy: shouldPublish ? (currentUser?.uid || null) : null,
        draftSavedAt: shouldPublish ? null : firebase.firestore.FieldValue.serverTimestamp()
    };

    try {
        await db.collection('lessons').doc(lessonId).update(payload);
        showToast(shouldPublish ? 'Lesson published.' : 'Lesson moved to draft.', 'success');
    } catch (error) {
        logError(error, 'Lesson Publish Toggle');
        showToast(getFirebaseFriendlyMessage(error, 'Could not update lesson status.'), 'error');
    }
}

function resetLessonForm() {
    const form = document.getElementById('add-lesson-form');
    if (form) form.reset();
    const idField = document.getElementById('lesson-id');
    if (idField) idField.value = '';
    const title = document.getElementById('lesson-form-title');
    if (title) title.textContent = 'Create New Lesson';
    const content = document.getElementById('lesson-content');
    if (content) content.innerHTML = '';
    const lessonPublishDate = document.getElementById('lesson-publish-date');
    if (lessonPublishDate) lessonPublishDate.value = '';
    const lessonStatus = document.getElementById('lesson-status');
    if (lessonStatus) lessonStatus.value = 'published';
    const lessonSourceUrl = document.getElementById('lesson-source-url');
    if (lessonSourceUrl) lessonSourceUrl.value = '';
    const templateSelect = document.getElementById('lesson-template-select');
    if (templateSelect) templateSelect.value = '';
    if (lessonEraserMode) {
        toggleLessonElementEraser(false);
    }
    populateLessonSubjectOptions();
    syncLessonSubjectCustomVisibility();
    renderLessonQuestionBuilder([]);
    updateLessonCoverPreview();
}

function editLesson(lessonId) {
    const lesson = allLessons.find(item => item.id === lessonId);
    if (!lesson) return;
    const normalized = normalizeLesson(lesson);

    const setValue = (id, value) => {
        const el = document.getElementById(id);
        if (el) el.value = value;
    };

    const formTitle = document.getElementById('lesson-form-title');
    if (formTitle) formTitle.textContent = 'Edit Lesson';
    setValue('lesson-id', normalized.id || '');
    setValue('lesson-title', normalized.title || '');
    setValue('lesson-summary', normalized.summary || '');
    populateLessonSubjectOptions(normalized.subject || '');
    syncLessonSubjectCustomVisibility();
    setValue('lesson-topic', normalized.topic || '');
    setValue('lesson-subtopic', normalized.subtopic || '');
    setValue('lesson-category', normalized.category || '');
    setValue('lesson-number', Number.isFinite(normalized.lessonNumber) ? normalized.lessonNumber : '');
    setValue('lesson-sort-order', Number.isFinite(normalized.sortOrder) ? normalized.sortOrder : '');
    setValue('lesson-status', normalized.status || 'published');
    setValue('lesson-cover-image', normalized.coverImage || '');
    setValue('lesson-tags', (normalized.tags || []).join(', '));
    setValue('lesson-interactive-html', normalized.interactiveHtml || '');
    setValue('lesson-widget-html', normalized.widgetHtml || '');
    setValue('lesson-links', (normalized.links || []).join('\n'));
    setValue('lesson-video-urls', (normalized.videoUrls || []).join('\n'));
    setValue('lesson-iframe-urls', (normalized.iframeUrls || []).join('\n'));
    setValue('lesson-image-urls', (normalized.imageUrls || []).join('\n'));
    setValue('lesson-attachments', (normalized.attachments || []).join('\n'));
    setValue('lesson-questions', JSON.stringify(normalized.questions || []));
    renderLessonQuestionBuilder(normalized.questions || []);
    setValue('lesson-button-label', normalized.buttonLabel || '');
    setValue('lesson-button-url', normalized.buttonUrl || '');
    setValue('lesson-source-url', normalized.scrapedFromUrl || '');

    const publishDateField = document.getElementById('lesson-publish-date');
    if (publishDateField && normalized.safeDate) {
        const localDate = new Date(normalized.safeDate.getTime() - normalized.safeDate.getTimezoneOffset() * 60000).toISOString().slice(0, 16);
        publishDateField.value = localDate;
    }

    const content = document.getElementById('lesson-content');
    if (content) content.innerHTML = sanitizeHTML(normalized.content || '');
    updateLessonCoverPreview();

    const formWrap = document.getElementById('add-lesson-form-container');
    if (formWrap) formWrap.scrollIntoView({ behavior: 'smooth' });
}

async function deleteLesson(lessonId) {
    if (!isAdminUser()) return;
    showConfirmationModal('Are you sure you want to delete this lesson? This cannot be undone.', async () => {
        try {
            await db.collection('lessons').doc(lessonId).delete();
            showToast('Lesson deleted.', 'success');
        } catch (error) {
            console.error('Error deleting lesson:', error);
            showToast('Could not delete lesson.', 'error');
        }
    });
}

function renderLessonMediaBlocks(lesson, options = {}) {
    const galleryOffset = Number(options.galleryOffset || 0);
    const isEmbeddableUrl = (value) => /^https?:\/\//i.test(String(value || '').trim());
    const links = (lesson.links || []).map(url => `<li><a href="${escapeHTML(url)}" target="_blank" rel="noopener noreferrer" class="text-blue-700 font-semibold hover:underline">${escapeHTML(url)}</a></li>`).join('');
    const videos = (lesson.videoUrls || []).map(url => `<div class="rounded-xl border border-gray-200 bg-white p-3"><a href="${escapeHTML(url)}" target="_blank" rel="noopener noreferrer" class="text-blue-700 font-semibold hover:underline">${escapeHTML(url)}</a></div>`).join('');
    const iframes = (lesson.iframeUrls || [])
        .filter(isEmbeddableUrl)
        .map(url => `<div class="rounded-xl border border-gray-200 bg-white p-2 overflow-hidden"><iframe src="${escapeHTML(url)}" loading="lazy" referrerpolicy="no-referrer" class="w-full h-64 rounded-lg border-0" allowfullscreen></iframe></div>`)
        .join('');
    const images = (lesson.imageUrls || []).map((url, index) => `
        <button type="button" class="lesson-gallery-trigger group relative overflow-hidden rounded-xl border border-gray-200 bg-white" data-gallery-index="${galleryOffset + index}" aria-label="Open lesson image ${index + 1}">
            <img src="${escapeHTML(url)}" alt="Lesson image ${index + 1}" class="w-full rounded-xl transition-transform duration-300 group-hover:scale-[1.02]" loading="lazy" decoding="async">
            <span class="lesson-image-zoom-chip"><i class="fas fa-expand mr-1"></i>Open</span>
        </button>
    `).join('');
    const attachments = (lesson.attachments || []).map(url => `<li><a href="${escapeHTML(url)}" target="_blank" rel="noopener noreferrer" class="text-blue-700 font-semibold hover:underline">${escapeHTML(url)}</a></li>`).join('');
    const normalizedQuestions = (lesson.questions || []).map((item, index) => normalizeLessonQuestionItem(item, index)).filter(item => item.question);
    const questionCards = normalizedQuestions.map((item, index) => {
        const question = escapeHTML(item.question || '');
        const answer = escapeHTML(item.correctAnswer || item.answer || '');
        const points = Number(item.points || 1);
        const required = item.required !== false;
        const type = item.type || 'short';
        const optionsMarkup = type === 'mcq'
            ? `<div class="space-y-2 mt-3">${(item.options || []).map((option, optionIndex) => `<label class="flex items-center gap-2 rounded-lg border border-slate-200 bg-white px-3 py-2"><input type="radio" name="lesson-question-${index}" value="${escapeHTML(option)}" class="text-blue-600 focus:ring-blue-500" ${required ? 'required' : ''}><span class="text-sm text-slate-700">${escapeHTML(option || `Option ${optionIndex + 1}`)}</span></label>`).join('')}</div>`
            : (type === 'truefalse'
                ? `<div class="space-y-2 mt-3">${['True', 'False'].map(option => `<label class="flex items-center gap-2 rounded-lg border border-slate-200 bg-white px-3 py-2"><input type="radio" name="lesson-question-${index}" value="${option}" class="text-blue-600 focus:ring-blue-500" ${required ? 'required' : ''}><span class="text-sm text-slate-700">${option}</span></label>`).join('')}</div>`
                : `<input type="text" data-question-input="${index}" placeholder="${escapeHTML(item.placeholder || 'Type your answer...')}" class="mt-3 w-full rounded-lg border border-gray-300 bg-white px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500" ${required ? 'required' : ''}>`);
        if (!question) return '';
        return `
            <article class="lesson-question-card rounded-xl border border-slate-200 bg-white px-4 py-3" data-question-index="${index}" data-question-type="${escapeHTML(type)}" data-correct-answer="${escapeHTML(answer)}" data-points="${escapeHTML(String(points))}" data-explanation="${escapeHTML(item.explanation || '')}">
                <div class="flex items-center justify-between gap-2">
                    <p class="font-semibold text-slate-800">Q${index + 1}. ${question}</p>
                    <span class="text-[11px] font-bold uppercase tracking-[0.12em] text-slate-500">${points} pt${points === 1 ? '' : 's'}</span>
                </div>
                ${optionsMarkup}
                <p class="lesson-question-feedback mt-2 text-xs font-semibold"></p>
            </article>
        `;
    }).join('');

    const interactiveQuestions = normalizedQuestions.length
        ? `<section class="mt-8"><h4 class="text-lg font-bold text-slate-900 mb-2">Practice form</h4><form id="lesson-interactive-questions-form" class="space-y-3">${questionCards}<div class="flex flex-wrap gap-2 pt-2"><button type="submit" class="inline-flex items-center gap-2 rounded-lg bg-blue-600 px-4 py-2 text-sm font-bold text-white hover:bg-blue-700"><i class="fas fa-check-circle"></i>Submit answers</button><button type="reset" class="inline-flex items-center gap-2 rounded-lg border border-gray-300 bg-white px-4 py-2 text-sm font-semibold text-gray-700 hover:bg-gray-50">Reset form</button></div><p id="lesson-question-score" class="text-sm font-semibold text-slate-700"></p></form></section>`
        : '';

    return `
        ${lesson.buttonLabel && lesson.buttonUrl ? `<div class="mt-6"><a href="${escapeHTML(lesson.buttonUrl)}" target="_blank" rel="noopener noreferrer" class="inline-flex items-center gap-2 rounded-lg bg-blue-600 px-4 py-2 font-bold text-white hover:bg-blue-700 transition-colors">${escapeHTML(lesson.buttonLabel)} <i class="fas fa-arrow-up-right-from-square"></i></a></div>` : ''}
        ${links ? `<section class="mt-8"><h4 class="text-lg font-bold text-slate-900 mb-2">Lesson links</h4><ul class="list-disc pl-5 space-y-1 text-sm">${links}</ul></section>` : ''}
        ${videos ? `<section class="mt-8"><h4 class="text-lg font-bold text-slate-900 mb-2">Video resources</h4><div class="grid grid-cols-1 gap-2">${videos}</div></section>` : ''}
        ${iframes ? `<section class="mt-8"><h4 class="text-lg font-bold text-slate-900 mb-2">Embedded content</h4><div class="grid grid-cols-1 gap-3">${iframes}</div></section>` : ''}
        ${images ? `<section class="mt-8"><h4 class="text-lg font-bold text-slate-900 mb-2">Images</h4><div class="grid grid-cols-1 md:grid-cols-2 gap-3">${images}</div><p class="mt-2 text-xs text-slate-500">Click an image to open spotlight view with zoom, fullscreen, and gallery arrows.</p></section>` : ''}
        ${attachments ? `<section class="mt-8"><h4 class="text-lg font-bold text-slate-900 mb-2">Attachments</h4><ul class="list-disc pl-5 space-y-1 text-sm">${attachments}</ul></section>` : ''}
        ${interactiveQuestions}
        ${lesson.interactiveHtml ? `<section class="mt-8"><h4 class="text-lg font-bold text-slate-900 mb-2">Interactive HTML</h4><div class="rounded-xl border border-gray-200 bg-white p-4 overflow-auto">${sanitizeHTML(lesson.interactiveHtml)}</div></section>` : ''}
        ${lesson.widgetHtml ? `<section class="mt-8"><h4 class="text-lg font-bold text-slate-900 mb-2">Widget</h4><div class="rounded-xl border border-gray-200 bg-white p-4 overflow-auto">${sanitizeHTML(lesson.widgetHtml)}</div></section>` : ''}
    `;
}

function setupLessonQuestionForm(questions = []) {
    const form = document.getElementById('lesson-interactive-questions-form');
    const scoreEl = document.getElementById('lesson-question-score');
    if (!form || !Array.isArray(questions) || questions.length === 0) return;

    const normalized = questions.map((item, index) => normalizeLessonQuestionItem(item, index));
    const normalizeToken = (value) => String(value || '').trim().toLowerCase();

    form.addEventListener('submit', (event) => {
        event.preventDefault();
        let scoredPoints = 0;
        let maxPoints = 0;
        let correctCount = 0;

        normalized.forEach((question, index) => {
            const card = form.querySelector(`[data-question-index="${index}"]`);
            if (!card) return;
            const feedback = card.querySelector('.lesson-question-feedback');
            const points = Number(question.points || 1);
            maxPoints += points;

            let userValue = '';
            if (question.type === 'mcq' || question.type === 'truefalse') {
                const selected = form.querySelector(`input[name="lesson-question-${index}"]:checked`);
                userValue = String(selected?.value || '').trim();
            } else {
                userValue = String(form.querySelector(`[data-question-input="${index}"]`)?.value || '').trim();
            }

            const isCorrect = normalizeToken(userValue) === normalizeToken(question.correctAnswer || question.answer || '');
            card.classList.toggle('lesson-question-card-correct', isCorrect);
            card.classList.toggle('lesson-question-card-wrong', !isCorrect);
            if (feedback) {
                const explanation = String(question.explanation || '').trim();
                if (isCorrect) {
                    feedback.textContent = `Correct (+${points})${explanation ? ` · ${explanation}` : ''}`;
                    feedback.className = 'lesson-question-feedback mt-2 text-xs font-semibold text-emerald-700';
                } else {
                    const answerLabel = String(question.correctAnswer || question.answer || '').trim() || 'No model answer set';
                    feedback.textContent = `Not quite. Correct answer: ${answerLabel}${explanation ? ` · ${explanation}` : ''}`;
                    feedback.className = 'lesson-question-feedback mt-2 text-xs font-semibold text-rose-700';
                }
            }

            if (isCorrect) {
                scoredPoints += points;
                correctCount += 1;
            }
        });

        if (scoreEl) {
            const totalQuestions = normalized.length;
            scoreEl.textContent = `Score: ${scoredPoints}/${maxPoints} points · ${correctCount}/${totalQuestions} correct`;
            scoreEl.className = 'text-sm font-bold text-blue-700';
        }
    });

    form.addEventListener('reset', () => {
        setTimeout(() => {
            form.querySelectorAll('.lesson-question-card').forEach(card => {
                card.classList.remove('lesson-question-card-correct', 'lesson-question-card-wrong');
                const feedback = card.querySelector('.lesson-question-feedback');
                if (feedback) feedback.textContent = '';
            });
            if (scoreEl) {
                scoreEl.textContent = '';
                scoreEl.className = 'text-sm font-semibold text-slate-700';
            }
        }, 0);
    });
}

function renderLessonImageSpotlight() {
    const imageEl = document.getElementById('lesson-spotlight-image');
    const counterEl = document.getElementById('lesson-spotlight-counter');
    const prevEl = document.getElementById('lesson-spotlight-prev');
    const nextEl = document.getElementById('lesson-spotlight-next');
    const { images, index, zoom } = lessonImageSpotlightState;
    if (!imageEl || !counterEl || !Array.isArray(images) || !images.length) return;
    const boundedIndex = Math.max(0, Math.min(images.length - 1, index));
    lessonImageSpotlightState.index = boundedIndex;
    imageEl.src = images[boundedIndex];
    imageEl.style.transform = `scale(${zoom})`;
    counterEl.textContent = `${boundedIndex + 1} / ${images.length}`;
    if (prevEl) prevEl.disabled = images.length <= 1;
    if (nextEl) nextEl.disabled = images.length <= 1;
}

function openLessonImageSpotlight(startIndex = 0, images = []) {
    const modal = document.getElementById('lesson-image-spotlight-modal');
    if (!modal) return;
    const safeImages = (images || []).map(item => String(item || '').trim()).filter(item => /^https?:\/\//i.test(item));
    if (!safeImages.length) return;
    lessonImageSpotlightState.images = safeImages;
    lessonImageSpotlightState.index = Math.max(0, Math.min(safeImages.length - 1, Number(startIndex) || 0));
    lessonImageSpotlightState.zoom = 1;
    modal.style.display = 'flex';
    modal.classList.remove('hidden');
    document.body.classList.add('modal-open');
    renderLessonImageSpotlight();
}

function closeLessonImageSpotlight() {
    const modal = document.getElementById('lesson-image-spotlight-modal');
    if (!modal) return;
    modal.style.display = 'none';
    modal.classList.add('hidden');
    lessonImageSpotlightState.images = [];
    lessonImageSpotlightState.index = 0;
    lessonImageSpotlightState.zoom = 1;
    if (document.fullscreenElement) {
        document.exitFullscreen().catch(() => {});
    }
    if (!document.querySelector('#preview-modal[style*="display: flex"]') &&
        !document.querySelector('#blog-viewer-modal[style*="display: flex"]') &&
        !document.querySelector('#lesson-viewer-modal[style*="display: flex"]')) {
        document.body.classList.remove('modal-open');
    }
}

function stepLessonImageSpotlight(delta = 1) {
    const total = lessonImageSpotlightState.images.length;
    if (total <= 1) return;
    const next = (lessonImageSpotlightState.index + delta + total) % total;
    lessonImageSpotlightState.index = next;
    lessonImageSpotlightState.zoom = 1;
    renderLessonImageSpotlight();
}

function setLessonImageSpotlightZoom(delta = 0.2) {
    const nextZoom = Math.max(0.5, Math.min(3, lessonImageSpotlightState.zoom + delta));
    lessonImageSpotlightState.zoom = Number(nextZoom.toFixed(2));
    renderLessonImageSpotlight();
}

function resetLessonImageSpotlightZoom() {
    lessonImageSpotlightState.zoom = 1;
    renderLessonImageSpotlight();
}

async function toggleLessonImageSpotlightFullscreen() {
    const stage = document.getElementById('lesson-spotlight-stage');
    if (!stage || !document.fullscreenEnabled) return;
    try {
        if (document.fullscreenElement) {
            await document.exitFullscreen();
        } else {
            await stage.requestFullscreen();
        }
    } catch (_) {}
}

function setupLessonImageGalleryBindings(images = []) {
    const modal = document.getElementById('lesson-viewer-modal');
    if (!modal) return;
    const triggers = modal.querySelectorAll('.lesson-gallery-trigger');
    triggers.forEach(trigger => {
        trigger.addEventListener('click', () => {
            const idx = Number(trigger.getAttribute('data-gallery-index') || 0);
            openLessonImageSpotlight(idx, images);
        });
    });
}

function setupLessonSpotlightKeyboardSupport() {
    if (document.body.dataset.lessonSpotlightKeysBound === 'true') return;
    document.body.dataset.lessonSpotlightKeysBound = 'true';
    const spotlightModal = document.getElementById('lesson-image-spotlight-modal');
    if (spotlightModal) {
        spotlightModal.addEventListener('click', (event) => {
            if (event.target === spotlightModal) {
                closeLessonImageSpotlight();
            }
        });
    }
    document.addEventListener('keydown', (event) => {
        const modal = document.getElementById('lesson-image-spotlight-modal');
        if (!modal || modal.classList.contains('hidden')) return;
        if (event.key === 'Escape') {
            closeLessonImageSpotlight();
            return;
        }
        if (event.key === 'ArrowLeft') {
            event.preventDefault();
            stepLessonImageSpotlight(-1);
            return;
        }
        if (event.key === 'ArrowRight') {
            event.preventDefault();
            stepLessonImageSpotlight(1);
            return;
        }
        if (event.key === '+' || event.key === '=') {
            event.preventDefault();
            setLessonImageSpotlightZoom(0.2);
            return;
        }
        if (event.key === '-') {
            event.preventDefault();
            setLessonImageSpotlightZoom(-0.2);
            return;
        }
        if (event.key === '0') {
            event.preventDefault();
            resetLessonImageSpotlightZoom();
        }
    });
}

function closeLessonViewer() {
    if (lessonViewerSession.completionTimer) {
        clearTimeout(lessonViewerSession.completionTimer);
        lessonViewerSession.completionTimer = null;
    }
    lessonViewerSession.lessonId = null;
    lessonViewerSession.openedAt = 0;
    lessonViewerSession.hasAutoCompleted = false;
    if (unsubscribeLessonComments) {
        try { unsubscribeLessonComments(); } catch (_) {}
        unsubscribeLessonComments = null;
    }
    const modal = document.getElementById('lesson-viewer-modal');
    if (!modal) return;
    modal.style.display = 'none';
    modal.classList.add('hidden');
    modal.innerHTML = '';
    closeLessonImageSpotlight();
}

function setupLessonAutoCompletionWatch(lessonId) {
    const scrollRoot = document.querySelector('#lesson-viewer-modal .overflow-y-auto');
    if (!scrollRoot) return;

    const maybeAutoComplete = () => {
        if (lessonViewerSession.hasAutoCompleted || !lessonViewerSession.lessonId) return;
        const bottomReached = scrollRoot.scrollTop + scrollRoot.clientHeight >= (scrollRoot.scrollHeight - 24);
        const openLongEnough = Date.now() - lessonViewerSession.openedAt >= 5000;
        if (!bottomReached || !openLongEnough) return;
        lessonViewerSession.hasAutoCompleted = true;
        markLessonComplete(lessonId, 'auto-scroll');
    };

    scrollRoot.addEventListener('scroll', maybeAutoComplete, { passive: true });
    lessonViewerSession.completionTimer = setTimeout(maybeAutoComplete, 5200);
}

function renderLessonComments(lessonId) {
    const list = document.getElementById('lesson-comments-list');
    if (!list) return;
    if (!isFirestoreAvailable()) {
        list.innerHTML = '<div class="rounded-xl border border-amber-200 bg-amber-50 px-4 py-3 text-sm text-amber-800">Comments are temporarily unavailable while the live database reconnects.</div>';
        return;
    }

    if (unsubscribeLessonComments) {
        try { unsubscribeLessonComments(); } catch (_) {}
        unsubscribeLessonComments = null;
    }

    unsubscribeLessonComments = db.collection('lessons').doc(lessonId).collection('comments')
        .orderBy('createdAt', 'asc')
        .onSnapshot(snapshot => {
            const comments = [];
            snapshot.forEach(doc => comments.push({ id: doc.id, ...doc.data() }));
            if (!comments.length) {
                list.innerHTML = '<div class="text-sm text-slate-500">No comments yet. Start the discussion.</div>';
                return;
            }
            list.innerHTML = comments.map(c => {
                const name = escapeHtml(c.authorName || 'User');
                const text = escapeHtml(c.text || '');
                const when = c.createdAt?.toDate ? c.createdAt.toDate() : null;
                const rel = when ? timeAgo(when) : '';
                return `<div class="rounded-xl border border-slate-200 bg-white p-3"><div class="text-xs text-slate-500 mb-1">${name} • ${rel}</div><div class="text-sm text-slate-700 whitespace-pre-wrap">${text}</div></div>`;
            }).join('');
        }, err => {
            logError(err, 'Lesson Comments');
            list.innerHTML = `<div class="rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">${escapeHTML(getFirebaseFriendlyMessage(err, 'Could not load lesson comments.'))}</div>`;
        });

    const form = document.getElementById('lesson-add-comment-form');
    if (form && !form.dataset.bound) {
        form.dataset.bound = 'true';
        form.addEventListener('submit', async (event) => {
            event.preventDefault();
            const input = document.getElementById('lesson-comment-input');
            const msg = document.getElementById('lesson-comment-message');
            const text = String(input?.value || '').trim();
            if (msg) msg.textContent = '';
            if (!text) return;
            const allowed = isAdminUser() || currentUser?.tier === 'paid';
            if (!allowed) {
                if (msg) {
                    msg.textContent = 'Only Pro users and admins can comment.';
                    msg.className = 'text-red-600 text-sm h-4';
                }
                return;
            }
            try {
                await db.collection('lessons').doc(lessonId).collection('comments').add({
                    text,
                    authorId: currentUser.uid,
                    authorName: currentUser.displayName || currentUser.email || 'User',
                    createdAt: firebase.firestore.FieldValue.serverTimestamp()
                });
                if (input) input.value = '';
                if (msg) {
                    msg.textContent = 'Comment posted.';
                    msg.className = 'text-green-600 text-sm h-4';
                }
            } catch (error) {
                logError(error, 'Lesson Comment Submit');
                if (msg) {
                    msg.textContent = getFirebaseFriendlyMessage(error, 'Could not post comment.');
                    msg.className = 'text-red-600 text-sm h-4';
                }
            }
        });
    }
}

function openLessonViewer(lessonId) {
    const lesson = allLessons.find(item => item.id === lessonId);
    if (!lesson) return;
    if (!canUserReadLesson(lesson)) {
        showToast('This lesson is currently saved as draft and only visible to admins.', 'info');
        return;
    }

    if (!currentUser) {
        showAuthPage(true);
        return;
    }

    const access = getLessonAccessState(lessonId);
    if (!access.allowed) {
        openUpgradeModal(access.reason || 'Upgrade to Pro to unlock the full lessons library.');
        return;
    }

    if (!isAdminUser() && currentUser.tier !== 'paid') {
        setFreeLessonAccessRecord(lessonId);
        renderLessonsPage(allLessons);
    }

    recordLessonView(lesson);

    const normalized = normalizeLesson(lesson);
    const modal = document.getElementById('lesson-viewer-modal');
    if (!modal) return;

    const tagChips = (normalized.tags || []).slice(0, 8).map(tag => `<span class="blog-tag-chip">#${escapeHTML(tag)}</span>`).join('');
    const galleryImages = [...new Set([
        normalized.coverImage,
        ...(normalized.imageUrls || [])
    ].map(item => String(item || '').trim()).filter(item => /^https?:\/\//i.test(item)))];
    const pathLabel = [normalized.subject, normalized.topic, normalized.subtopic].filter(Boolean).join(' • ') || 'General lesson';
    const publishText = normalized.safeDate.toLocaleDateString('en-GB', { day: '2-digit', month: 'long', year: 'numeric' });
    const metrics = getLessonMetrics(normalized.id);
    const progress = getLessonProgress(normalized.id);
    const canComment = isAdminUser() || currentUser?.tier === 'paid';
    const viewedLabel = progress?.viewedAt || progress?.lastOpenedAt ? 'Viewed' : 'Not viewed yet';
    const completedLabel = progress?.completedAt ? 'Completed' : 'Not completed';

    modal.innerHTML = `
        <div class="bg-white/95 backdrop-blur-lg rounded-2xl shadow-xl w-full max-w-5xl flex flex-col fade-in max-h-[90vh]">
            <div class="p-4 border-b border-gray-200/50 flex justify-between items-center gap-3">
                <div class="min-w-0">
                    <p class="text-xs font-semibold uppercase tracking-[0.14em] text-blue-700">${escapeHTML(pathLabel)}</p>
                    <h3 class="text-xl font-black text-slate-900 truncate">${escapeHTML(normalized.title || 'Lesson')}</h3>
                    <p class="text-xs text-slate-500">Published ${publishText}</p>
                </div>
                <button onclick="closeLessonViewer()" class="text-2xl font-bold text-gray-500 hover:text-gray-800 p-1 leading-none" title="Close">×</button>
            </div>
            <div class="overflow-y-auto p-6 md:p-8">
                ${normalized.coverImage ? `<button type="button" class="lesson-gallery-trigger block w-full text-left mb-6" data-gallery-index="0" aria-label="Open cover image in spotlight"><img src="${escapeHTML(normalized.coverImage)}" alt="Lesson cover" class="w-full max-h-72 object-cover rounded-xl border border-gray-200" loading="lazy" decoding="async"><span class="lesson-image-open-chip-inline mt-2 inline-flex"><i class="fas fa-expand mr-1"></i>Open cover image</span></button>` : ''}
                ${normalized.summary ? `<p class="text-sm text-slate-600 mb-5">${escapeHTML(normalized.summary)}</p>` : ''}
                <div class="mb-5 grid grid-cols-1 sm:grid-cols-3 gap-3">
                    <div class="rounded-xl border border-slate-200 bg-slate-50 px-3 py-2 text-xs font-semibold text-slate-700"><i class="fas fa-eye mr-1 text-slate-500"></i>${metrics.views} views</div>
                    <div class="rounded-xl border border-emerald-200 bg-emerald-50 px-3 py-2 text-xs font-semibold text-emerald-700"><i class="fas fa-check-circle mr-1"></i>${metrics.completions} completions</div>
                    <div class="rounded-xl border border-blue-200 bg-blue-50 px-3 py-2 text-xs font-semibold text-blue-700">${escapeHTML(viewedLabel)} • ${escapeHTML(completedLabel)}</div>
                </div>
                <div class="prose prose-sm md:prose-base max-w-none lesson-rich-content">${formatBlogLinks(sanitizeHTML(normalized.content || ''))}</div>
                <div class="mt-5 flex flex-wrap gap-2">${tagChips}</div>
                ${renderLessonMediaBlocks(normalized, { galleryOffset: normalized.coverImage ? 1 : 0 })}
                <div class="mt-8 flex flex-wrap items-center gap-3 border-t border-slate-200 pt-6">
                    <button type="button" onclick="markLessonComplete('${escapeJS(normalized.id)}')" class="inline-flex items-center gap-2 rounded-xl bg-emerald-600 px-4 py-2 text-sm font-bold text-white hover:bg-emerald-700 transition-colors">
                        <i class="fas fa-check"></i>
                        Mark lesson as complete
                    </button>
                    <span class="text-xs font-semibold text-slate-500">Auto-completes when you reach the end and stay for at least 5 seconds.</span>
                </div>
                <section class="mt-8 rounded-2xl border border-slate-200 bg-slate-50 p-4">
                    <h4 class="text-lg font-bold text-slate-900 mb-2">Lesson comments</h4>
                    <div id="lesson-comments-list" class="space-y-3"></div>
                    ${canComment ? `
                        <form id="lesson-add-comment-form" class="mt-4 space-y-2">
                            <textarea id="lesson-comment-input" class="w-full p-3 rounded-lg border border-gray-300/60 bg-white focus:outline-none focus:ring-2 focus:ring-blue-500" rows="3" placeholder="Ask a question or share your answer strategy..."></textarea>
                            <div class="flex justify-end">
                                <button type="submit" class="px-4 py-2 rounded-lg bg-blue-600 text-white font-semibold hover:bg-blue-700">Post comment</button>
                            </div>
                            <p id="lesson-comment-message" class="text-sm h-4"></p>
                        </form>
                    ` : '<div class="mt-3 text-sm text-gray-600 bg-white border border-gray-200 rounded-lg p-3">Comments are available to Pro users and admins. <a href="#" class="text-blue-600 font-semibold" onclick="showPage(\'features-page\')">Upgrade to Pro</a> to join the discussion.</div>'}
                </section>
            </div>
        </div>
    `;

    modal.style.display = 'flex';
    modal.classList.remove('hidden');
    lessonViewerSession.lessonId = lessonId;
    lessonViewerSession.openedAt = Date.now();
    lessonViewerSession.hasAutoCompleted = false;
    lessonViewerSession.galleryImages = galleryImages;
    setupLessonAutoCompletionWatch(lessonId);
    setupLessonImageGalleryBindings(galleryImages);
    setupLessonQuestionForm(normalized.questions || []);
    setupLessonSpotlightKeyboardSupport();
    renderLessonComments(lessonId);
}

function setupLessonsImagePasteHandler() {
    const zone = document.getElementById('lesson-image-paste-zone');
    const imageUrls = document.getElementById('lesson-image-urls');
    const iframeUrls = document.getElementById('lesson-iframe-urls');
    const editor = document.getElementById('lesson-content');
    const coverInput = document.getElementById('lesson-cover-image');
    if (!zone || !imageUrls || !editor || zone.dataset.bound === 'true') return;
    zone.dataset.bound = 'true';

    const subjectSelect = document.getElementById('lesson-subject');
    if (subjectSelect && !subjectSelect.dataset.bound) {
        subjectSelect.dataset.bound = 'true';
        subjectSelect.addEventListener('change', syncLessonSubjectCustomVisibility);
    }

    const appendImageUrl = (url) => {
        const clean = String(url || '').trim();
        if (!clean) return;
        const existing = parseMultilineValues(imageUrls.value || '');
        if (!existing.includes(clean)) {
            imageUrls.value = existing.length ? `${existing.join('\n')}\n${clean}` : clean;
        }
    };

    const appendIframeUrl = (url) => {
        if (!iframeUrls) return;
        const clean = String(url || '').trim();
        if (!clean) return;
        const existing = parseMultilineValues(iframeUrls.value || '');
        if (!existing.includes(clean)) {
            iframeUrls.value = existing.length ? `${existing.join('\n')}\n${clean}` : clean;
        }
    };

    const insertImageInLessonEditor = (url) => {
        const clean = String(url || '').trim();
        if (!clean) return;
        editor.focus();
        document.execCommand('insertHTML', false, `<figure><img src="${escapeHTML(clean)}" alt="Lesson image" class="w-full rounded-xl border border-gray-200" loading="lazy" decoding="async"></figure><p><br></p>`);
        appendImageUrl(clean);
    };

    const insertIframeInLessonEditor = (url) => {
        const clean = String(url || '').trim();
        if (!/^https?:\/\//i.test(clean)) return;
        editor.focus();
        document.execCommand('insertHTML', false, `<div class="my-4 rounded-xl border border-slate-200 bg-slate-50 p-2"><iframe src="${escapeHTML(clean)}" class="w-full h-64 rounded-lg border-0" loading="lazy" referrerpolicy="no-referrer" allowfullscreen></iframe></div><p><br></p>`);
        appendIframeUrl(clean);
    };

    const handleTextDropOrPaste = (text) => {
        const clean = String(text || '').trim();
        if (!clean) return false;
        if (/^https?:\/\/.+\.(png|jpe?g|gif|webp|svg)(\?.*)?$/i.test(clean)) {
            insertImageInLessonEditor(clean);
            showToast('Image URL inserted into lesson.', 'success');
            return true;
        }
        if (/^https?:\/\//i.test(clean)) {
            insertIframeInLessonEditor(clean);
            showToast('IFrame URL embedded into lesson.', 'success');
            return true;
        }
        return false;
    };

    zone.addEventListener('paste', async (event) => {
        const textPaste = String(event.clipboardData?.getData('text/plain') || '').trim();
        if (handleTextDropOrPaste(textPaste)) {
            event.preventDefault();
            return;
        }

        const items = event.clipboardData?.items || [];
        for (const item of items) {
            if (!item.type || !item.type.startsWith('image/')) continue;
            const file = item.getAsFile();
            if (!file) continue;
            event.preventDefault();
            try {
                const uploadResult = await uploadImageWithFallback(file, 'lesson-paste');
                const imageUrl = uploadResult?.url || uploadResult;
                if (!imageUrl) throw new Error('No uploaded URL returned');
                insertImageInLessonEditor(imageUrl);
                if (coverInput && !String(coverInput.value || '').trim()) {
                    coverInput.value = imageUrl;
                    updateLessonCoverPreview();
                }
                showToast('Pasted image uploaded and inserted.', 'success');
            } catch (error) {
                logError(error, 'Lesson Image Paste');
                showToast('Could not upload pasted image.', 'error');
            }
            break;
        }
    });

    editor.addEventListener('paste', async (event) => {
        const textPaste = String(event.clipboardData?.getData('text/plain') || '').trim();
        if (handleTextDropOrPaste(textPaste)) event.preventDefault();
    });

    const onDragOver = (event) => {
        event.preventDefault();
        zone.classList.add('lesson-drop-target');
    };

    const onDragLeave = () => {
        zone.classList.remove('lesson-drop-target');
    };

    const onDrop = async (event) => {
        event.preventDefault();
        zone.classList.remove('lesson-drop-target');
        const dt = event.dataTransfer;
        if (!dt) return;

        const droppedText = String(dt.getData('text/plain') || '').trim();
        if (handleTextDropOrPaste(droppedText)) return;

        const files = Array.from(dt.files || []);
        const imageFile = files.find(file => isBlogImageFile(file));
        if (!imageFile) return;

        try {
            const uploadResult = await uploadImageWithFallback(imageFile, 'lesson-drop');
            const imageUrl = uploadResult?.url || uploadResult;
            if (!imageUrl) throw new Error('No uploaded URL returned');
            insertImageInLessonEditor(imageUrl);
            if (coverInput && !String(coverInput.value || '').trim()) {
                coverInput.value = imageUrl;
                updateLessonCoverPreview();
            }
            showToast('Dropped image uploaded and inserted.', 'success');
        } catch (error) {
            logError(error, 'Lesson Image Drop');
            showToast('Could not upload dropped image.', 'error');
        }
    };

    zone.addEventListener('dragover', onDragOver);
    zone.addEventListener('dragleave', onDragLeave);
    zone.addEventListener('drop', onDrop);
    editor.addEventListener('dragover', onDragOver);
    editor.addEventListener('dragleave', onDragLeave);
    editor.addEventListener('drop', onDrop);

    if (coverInput && !coverInput.dataset.bound) {
        coverInput.dataset.bound = 'true';
        coverInput.addEventListener('input', updateLessonCoverPreview);
    }

    syncLessonSubjectCustomVisibility();
}

