// Stripe Checkout + Billing Portal launcher
function setupStripeCheckoutUI() {
    const alertBox = document.getElementById('checkout-alert');
    const checkoutBtns = document.querySelectorAll('[data-checkout-button]');
    const portalBtns = document.querySelectorAll('[data-billing-portal-button]');

    function showAlert(kind, message) {
        if (!alertBox) return;
        alertBox.classList.remove('hidden');
        alertBox.classList.remove('bg-green-50', 'text-green-800', 'border-green-200', 'bg-yellow-50', 'text-yellow-800', 'border-yellow-200', 'bg-red-50', 'text-red-800', 'border-red-200');
        if (kind === 'success') alertBox.classList.add('bg-green-50', 'text-green-800', 'border-green-200');
        else if (kind === 'warning') alertBox.classList.add('bg-yellow-50', 'text-yellow-800', 'border-yellow-200');
        else alertBox.classList.add('bg-red-50', 'text-red-800', 'border-red-200');
        alertBox.textContent = message;
    }

    // Surface success/cancel from query string
    try {
        const params = new URLSearchParams(window.location.search);
        const checkoutStatus = params.get('checkout');
        if (checkoutStatus === 'success') {
            showAlert('success', 'Payment successful. Your Pro features will activate shortly.');
            showToast('Payment successful. Unlocking Pro…', 'success');
        } else if (checkoutStatus === 'cancel') {
            showAlert('warning', 'Checkout was cancelled. You can try again anytime.');
            showToast('Checkout cancelled.', 'info');
        }
        if (checkoutStatus) {
            params.delete('checkout');
            const newUrl = `${window.location.pathname}${params.toString() ? '?' + params.toString() : ''}${window.location.hash}`;
            window.history.replaceState({}, document.title, newUrl);
        }
    } catch (e) {
        logError(e, 'Stripe checkout query handling');
    }

    if (checkoutBtns && checkoutBtns.length) {
        checkoutBtns.forEach((btn) => {
            const original = btn.textContent;
            btn.addEventListener('click', async () => {
                const priceId = btn.dataset.priceId;
                if (!priceId) {
                    showAlert('warning', 'Price ID is not configured. Set data-price-id on the checkout button.');
                    return;
                }

                btn.disabled = true;
                btn.textContent = 'Redirecting…';

                try {
                    const res = await fetch('/api/stripe-checkout', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({
                            priceId,
                            customerEmail: currentUser && currentUser.email ? currentUser.email : undefined
                        })
                    });

                    const data = await res.json();
                    if (data && data.url) {
                        window.location.href = data.url;
                    } else {
                        const msg = (data && data.error) || 'Unable to start checkout.';
                        showAlert('error', msg);
                        btn.disabled = false;
                        btn.textContent = original;
                    }
                } catch (error) {
                    logError(error, 'Stripe checkout launch');
                    showAlert('error', 'Network error. Please try again.');
                    btn.disabled = false;
                    btn.textContent = original;
                }
            });
        });
    }

    if (portalBtns && portalBtns.length) {
        portalBtns.forEach((portalBtn) => {
            portalBtn.addEventListener('click', async () => {
                const defaultLabel = portalBtn.dataset.billingDefaultLabel || portalBtn.textContent.trim() || 'Manage billing';
                portalBtn.disabled = true;
                portalBtn.textContent = 'Opening…';
                try {
                    const billingWindow = window.open(STRIPE_BILLING_PORTAL_URL, '_blank', 'noopener,noreferrer');
                    if (!billingWindow) {
                        window.location.href = STRIPE_BILLING_PORTAL_URL;
                    }
                    showToast('Opening Stripe billing portal...', 'info');
                } catch (error) {
                    logError(error, 'Stripe portal launch');
                    if (alertBox) showAlert('error', 'Unable to open the Stripe billing portal. Please try again or email admin@gcsemate.com.');
                    showToast('Unable to open the Stripe billing portal. Email admin@gcsemate.com if it keeps failing.', 'error');
                } finally {
                    portalBtn.disabled = false;
                    portalBtn.textContent = defaultLabel;
                }
            });
        });
    }
}

function initializeFaqAccordion() {
    const faqContainer = document.getElementById('faq-container');
    if (!faqContainer) return;
    // Accordion expand/collapse with dynamic height
    faqContainer.addEventListener('click', (e) => {
        const questionHeader = e.target.closest('.faq-question');
        if (!questionHeader) return;
        const faqItem = questionHeader.parentElement;
        const answer = faqItem.querySelector('.faq-answer');
        if (!answer) return;
        const isOpen = faqItem.classList.contains('open');

        // Close others for an accordion behavior
        faqContainer.querySelectorAll('.faq-item.open').forEach(openItem => {
            if (openItem !== faqItem) {
                const openAnswer = openItem.querySelector('.faq-answer');
                if (openAnswer) {
                    openAnswer.style.maxHeight = '0px';
                    openAnswer.style.paddingBottom = '0px';
                    openItem.classList.remove('open');
                }
            }
        });

        if (!isOpen) {
            faqItem.classList.add('open');
            // Set padding first, then measure height so content isn't cut off.
            // Use a temp auto height to get true content height for transitions.
            answer.style.paddingBottom = '1.25rem';
            answer.style.maxHeight = 'none';
            const full = answer.scrollHeight;
            answer.style.maxHeight = '0px';
            // Next frame set to measured height to animate
            requestAnimationFrame(() => { answer.style.maxHeight = full + 'px'; });
        } else {
            answer.style.maxHeight = '0px';
            answer.style.paddingBottom = '0px';
            faqItem.classList.remove('open');
        }
    });

    // Initialize: force closed state first, then compute size on click for accuracy
    faqContainer.querySelectorAll('.faq-answer').forEach(ans => {
        ans.style.maxHeight = '0px';
        ans.style.paddingBottom = '0px';
    });
}
function showSpecificationModal(pdfUrl, title) {
    // Create or get modal container
    let modal = document.getElementById('specification-pdf-modal');
    if (!modal) {
        modal = document.createElement('div');
        modal.id = 'specification-pdf-modal';
        modal.className = 'fixed inset-0 z-[10000] bg-black/60 backdrop-blur-sm flex items-center justify-center p-4';
        modal.style.display = 'none';
        document.body.appendChild(modal);
    }
    
    modal.style.display = 'flex';
    modal.innerHTML = `
        <div class="bg-white rounded-xl shadow-2xl w-full max-w-6xl max-h-[90vh] flex flex-col fade-in">
            <div class="flex items-center justify-between p-4 border-b border-gray-200 bg-gray-50 rounded-t-xl">
                <h3 class="text-lg font-semibold text-gray-800 flex items-center gap-2">
                    <i class="fas fa-file-pdf text-red-600"></i>
                    <span>${escapeHtml(title)}</span>
                </h3>
                <div class="flex items-center gap-2">
                    <a href="${pdfUrl}" download class="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors flex items-center gap-2 font-semibold" target="_blank">
                        <i class="fas fa-download"></i>
                        <span>Download</span>
                    </a>
                    <button onclick="document.getElementById('specification-pdf-modal').style.display='none'" class="p-2 text-gray-600 hover:text-gray-800 hover:bg-gray-200 rounded-lg transition-colors" aria-label="Close modal">
                        <i class="fas fa-times"></i>
                    </button>
                </div>
            </div>
            <div class="flex-1 overflow-hidden p-4">
                <iframe src="${pdfUrl}" class="w-full h-full border-0 rounded-lg" style="min-height: 70vh;"></iframe>
            </div>
        </div>
    `;
    
    // Close on backdrop click
    modal.addEventListener('click', (e) => {
        if (e.target === modal) {
            modal.style.display = 'none';
        }
    });
    
    // Close on Escape key
    const handleEscape = (e) => {
        if (e.key === 'Escape' && modal.style.display !== 'none') {
            modal.style.display = 'none';
            document.removeEventListener('keydown', handleEscape);
        }
    };
    document.addEventListener('keydown', handleEscape);
}

function showConfirmationModal(message, onConfirm, options = {}) {
    const {
        okText = 'OK',
        cancelText = 'Cancel',
        showCancel = true,
        onCancel = null,
        tone = 'danger'
    } = options;
    const modal = document.getElementById('confirmation-modal');
    if (!modal || typeof onConfirm !== 'function') return;

    const toneClass = tone === 'primary'
        ? 'px-6 py-2 bg-blue-600 text-white font-bold rounded-md hover:bg-blue-700'
        : tone === 'success'
            ? 'px-6 py-2 bg-emerald-600 text-white font-bold rounded-md hover:bg-emerald-700'
            : 'px-6 py-2 bg-red-600 text-white font-bold rounded-md hover:bg-red-700';

    modal.classList.remove('hidden');
    modal.innerHTML = `
        <div class="bg-white/90 backdrop-blur-lg rounded-lg shadow-xl w-full max-w-sm p-6 text-center fade-in">
            <p class="text-lg font-semibold text-gray-800 mb-6">${message}</p>
            <div class="flex justify-center gap-4">
                ${showCancel ? `<button id="confirm-cancel" class="px-6 py-2 bg-gray-200 text-gray-800 font-bold rounded-md hover:bg-gray-300">${cancelText}</button>` : ''}
                <button id="confirm-yes" class="${toneClass}">${okText}</button>
            </div>
        </div>
    `;
    modal.style.display = 'flex';

    let resolved = false;
    const cleanup = () => {
        modal.style.display = 'none';
        modal.classList.add('hidden');
        modal.innerHTML = '';
        modal.removeEventListener('click', handleBackdropClick);
        document.removeEventListener('keydown', handleEscapeClose);
    };

    const resolveModal = (confirmed) => {
        if (resolved) return;
        resolved = true;
        cleanup();
        if (confirmed) {
            onConfirm();
        } else if (typeof onCancel === 'function') {
            onCancel();
        }
    };

    const handleBackdropClick = (event) => {
        if (event.target === modal) {
            resolveModal(false);
        }
    };

    const handleEscapeClose = (event) => {
        if (event.key === 'Escape') {
            resolveModal(false);
        }
    };

    modal.addEventListener('click', handleBackdropClick);
    document.addEventListener('keydown', handleEscapeClose);

    const confirmButton = document.getElementById('confirm-yes');
    if (confirmButton) {
        confirmButton.onclick = () => resolveModal(true);
    }

    if (showCancel) {
        const cancelButton = document.getElementById('confirm-cancel');
        if (cancelButton) {
            cancelButton.onclick = () => resolveModal(false);
        }
    }
}

function confirmActionWithModal(message, options = {}) {
    return new Promise((resolve) => {
        showConfirmationModal(message, () => resolve(true), {
            ...options,
            onCancel: () => resolve(false)
        });
    });
}

function showDeleteAccountModal() {
    showConfirmationModal(
        'Are you sure you want to permanently delete your account? This action cannot be undone.',
        handleDeleteAccount,
        { okText: 'Delete Account' }
    );
}

async function handleDeleteAccount() {
    if (!currentUser) return;
    try {
        const userId = currentUser.uid;
        // First delete Firestore document
        await db.collection('users').doc(userId).delete();
        // Then delete auth user
        await auth.currentUser.delete();
        showToast('Your account has been successfully deleted.', 'success');
        // onAuthStateChanged will handle the UI redirect
    } catch (error) {
        console.error("Account deletion failed:", error);
        showToast(`Error deleting account: ${error.message}`, 'error');
        // Handle re-authentication if needed
        if (error.code === 'auth/requires-recent-login') {
            showToast('Please log out and log back in to delete your account.', 'error');
        }
    }
}
